  'base64__all.py': "import base64\nimport binascii\n\n# === b64encode / b64decode ===\nassert base64.b64encode(b'') == b''\nassert base64.b64encode(b'a') == b'YQ=='\nassert base64.b64encode(b'ab') == b'YWI='\nassert base64.b64encode(b'abc') == b'YWJj'\nassert base64.b64encode(b'\\x00\\xff\\xfe') == b'AP/+'\nassert base64.b64decode(b'YWJj') == b'abc'\nassert base64.b64decode(b'YQ==') == b'a'\nassert base64.b64decode(b'') == b''\nassert base64.b64decode('YWJj') == b'abc'\nassert base64.b64decode(s=b'YWJj') == b'abc'\n\n# === b64 round trip over every byte value ===\nevery_byte = b''\n_hex_digits = '0123456789abcdef'\nfor _i in range(256):\n    every_byte += bytes.fromhex(_hex_digits[_i // 16] + _hex_digits[_i % 16])\nassert base64.b64decode(base64.b64encode(every_byte)) == every_byte\n\n# === altchars ===\nassert base64.b64encode(b'\\xfb\\xef', altchars=b'-_') == b'--8='\nassert base64.b64decode(b'--8=', altchars=b'-_') == b'\\xfb\\xef'\nassert base64.b64decode('--8=', altchars='-_') == b'\\xfb\\xef'\nassert base64.b64encode(b'\\xfb\\xef', b'-_') == b'--8='\n\n# === standard_b64 / urlsafe_b64 ===\nassert base64.standard_b64encode(b'\\xfb\\xef') == b'++8='\nassert base64.standard_b64decode(b'++8=') == b'\\xfb\\xef'\nassert base64.urlsafe_b64encode(b'\\xfb\\xef') == b'--8='\nassert base64.urlsafe_b64decode(b'--8=') == b'\\xfb\\xef'\nassert base64.urlsafe_b64decode('--8=') == b'\\xfb\\xef'\n# urlsafe decoding leaves the standard alphabet working too\nassert base64.urlsafe_b64decode(b'++8=') == b'\\xfb\\xef'\n\n# === non-strict decoding discards junk ===\nassert base64.b64decode(b'YWJj\\n') == b'abc'\nassert base64.b64decode('abcd!!') == b'i\\xb7\\x1d'\nassert base64.b64decode(b'Y W J j') == b'abc'\nassert base64.b64decode(b'YWJj=') == b'abc'\nassert base64.b64decode(b'YWJjZA===') == b'abcd'\n\n# === padding permits a quad to end, it does not stop the scan ===\n# junk after the padding is still discarded\nassert base64.b64decode(b'YWJjZA==!!') == b'abcd'\n# but alphabet characters resume the same quad, so concatenated base64 runs together\nassert base64.b64decode(b'YQ==YQ==') == b'a\\x06\\x10'\nassert base64.b64decode(b'YWJjZA==xx') == b'abcd\\x0cq'\ntry:\n    base64.b64decode(b'YWJjZA==x')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\n# a long padding run leaves the closed quad alone rather than accumulating\nassert base64.b64decode(b'AA' + b'=' * 253) == b'\\x00'\nassert base64.b64decode(b'AA' + b'=' * 254) == b'\\x00'\nassert base64.b64decode(b'AA' + b'=' * 600) == b'\\x00'\n\n# === validate=True rejects what the default accepts ===\nassert base64.b64decode(b'YWJj', validate=True) == b'abc'\ntry:\n    base64.b64decode(b'abcd!!', validate=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Only base64 data is allowed'\n\ntry:\n    base64.b64decode(b'=YWJj', validate=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Leading padding not allowed'\n\ntry:\n    base64.b64decode(b'YWJj==', validate=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Excess padding not allowed'\n\ntry:\n    base64.b64decode(b'YW=Jj', validate=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Discontinuous padding not allowed'\n\ntry:\n    base64.b64decode(b'YWJjZA==x', validate=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Excess data after padding'\n\n# padding one character into a quad reports the length error, not a padding one\ntry:\n    base64.b64decode(b'YWJjZ=', validate=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert (\n        str(exc) == 'Invalid base64-encoded string: number of data characters (5) cannot be 1 more than a multiple of 4'\n    )\n\n# === padding and length errors (both modes) ===\ntry:\n    base64.b64decode(b'a')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert (\n        str(exc) == 'Invalid base64-encoded string: number of data characters (1) cannot be 1 more than a multiple of 4'\n    )\n\ntry:\n    base64.b64decode(b'YWJjY')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert (\n        str(exc) == 'Invalid base64-encoded string: number of data characters (5) cannot be 1 more than a multiple of 4'\n    )\n\ntry:\n    base64.b64decode(b'YWJ')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\n# === binascii.Error is a ValueError subclass ===\ntry:\n    base64.b64decode(b'YWJ')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'Incorrect padding'\n\n# === input type errors ===\ntry:\n    base64.b64encode('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'str'\"\n\ntry:\n    base64.b64decode(123)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"argument should be a bytes-like object or ASCII string, not 'int'\"\n\ntry:\n    base64.b64decode('café')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'string argument should contain only ASCII characters'\n\ntry:\n    base64.b64encode([1, 2, 3])\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'list'\"\n\ntry:\n    base64.b64encode(b'abc', altchars='-_')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'str'\"\n\n# altchars is length-checked before its type, so a non-sized value fails in `len()`\ntry:\n    base64.b64encode(b'abc', altchars=5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"object of type 'int' has no len()\"\n\n# altchars of the wrong length trips base64.py's own assert\ntry:\n    base64.b64encode(b'abc', altchars=b'-')\n    assert False, 'expected AssertionError'\nexcept AssertionError as exc:\n    assert str(exc) == \"b'-'\"\n\ntry:\n    base64.b64decode(b'YWJj', altchars=b'-')\n    assert False, 'expected AssertionError'\nexcept AssertionError as exc:\n    assert str(exc) == \"b'-'\"\n\n# === module constants ===\nassert base64.MAXBINSIZE == 57\nassert base64.MAXLINESIZE == 76\n\n# === b32encode / b32decode ===\nassert base64.b32encode(b'') == b''\nassert base64.b32encode(b'a') == b'ME======'\nassert base64.b32encode(b'ab') == b'MFRA===='\nassert base64.b32encode(b'abc') == b'MFRGG==='\nassert base64.b32encode(b'abcd') == b'MFRGGZA='\nassert base64.b32encode(b'abcde') == b'MFRGGZDF'\nassert base64.b32encode(b'abcdef') == b'MFRGGZDFMY======'\nassert base64.b32decode(b'MFRGGZDF') == b'abcde'\nassert base64.b32decode(b'ME======') == b'a'\nassert base64.b32decode('MFRGG===') == b'abc'\nassert base64.b32decode(base64.b32encode(every_byte)) == every_byte\n\n# === b32 casefold and map01 ===\nassert base64.b32decode(b'mfrggzdf', casefold=True) == b'abcde'\nassert base64.b32decode(b'MFRGG0DF', map01=b'L') == base64.b32decode(b'MFRGGODF')\nassert base64.b32decode(b'MFRGG1DF', map01=b'L') == base64.b32decode(b'MFRGGLDF')\n\ntry:\n    base64.b32decode(b'mfrggzdf')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Non-base32 digit found'\n\ntry:\n    base64.b32decode(b'MFRGG!!!')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Non-base32 digit found'\n\ntry:\n    base64.b32decode(b'MFRGGZD')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\ntry:\n    base64.b32decode(b'MFRGGZ==')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\ntry:\n    base64.b32decode(b'MFRGG', map01=b'L')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\ntry:\n    base64.b32decode(b'MFRGGZDF', map01=b'LL')\n    assert False, 'expected AssertionError'\nexcept AssertionError as exc:\n    assert str(exc) == \"b'LL'\"\n\n# === b32hex ===\nassert base64.b32hexencode(b'abc') == b'C5H66==='\nassert base64.b32hexdecode(b'C5H66===') == b'abc'\nassert base64.b32hexdecode(b'c5h66===', casefold=True) == b'abc'\nassert base64.b32hexdecode(base64.b32hexencode(every_byte)) == every_byte\n\ntry:\n    base64.b32hexdecode(b'c5h66===')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Non-base32 digit found'\n\ntry:\n    base64.b32hexdecode(b'C5H66')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\n# the base32 encoders coerce through `memoryview`, so their TypeError is prefixed\ntry:\n    base64.b32encode('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"memoryview: a bytes-like object is required, not 'str'\"\n\ntry:\n    base64.b32hexencode(5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"memoryview: a bytes-like object is required, not 'int'\"\n\n# b16encode reaches binascii directly, so it keeps the unprefixed wording\ntry:\n    base64.b16encode('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'str'\"\n\n# === b16encode / b16decode ===\nassert base64.b16encode(b'') == b''\nassert base64.b16encode(b'abc') == b'616263'\nassert base64.b16encode(b'\\xde\\xad') == b'DEAD'\nassert base64.b16decode(b'DEAD') == b'\\xde\\xad'\nassert base64.b16decode('616263') == b'abc'\nassert base64.b16decode(b'dead', casefold=True) == b'\\xde\\xad'\nassert base64.b16decode(base64.b16encode(every_byte)) == every_byte\n\ntry:\n    base64.b16decode(b'dead')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Non-base16 digit found'\n\ntry:\n    base64.b16decode(b'ABC')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Odd-length string'\n\n# === b85encode / b85decode ===\nassert base64.b85encode(b'') == b''\nassert base64.b85encode(b'a') == b'VE'\nassert base64.b85encode(b'abcd') == b'VPa!s'\nassert base64.b85encode(b'abcde') == b'VPa!sWd'\nassert base64.b85encode(b'\\xff\\xff\\xff\\xff') == b'|NsC0'\n# `pad` keeps the characters the zero-padding produced, so the length is a\n# multiple of five\nassert base64.b85encode(b'abc') == b'VPaz'\nassert base64.b85encode(b'abc', pad=True) == b'VPazd'\nassert base64.b85decode(b'VPa!s') == b'abcd'\nassert base64.b85decode('VPaz') == b'abc'\nassert base64.b85decode(b'') == b''\nassert base64.b85decode(base64.b85encode(every_byte)) == every_byte\n# a trailing partial group decodes to however many bytes it carries, and a\n# single leftover character carries none\nassert base64.b85decode(b'VPa') == b'ab'\nassert base64.b85decode(b'v') == b''\n\n# base85 failures are plain ValueErrors, not binascii.Error\ntry:\n    base64.b85decode(b'|-.CM')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'bad base85 character at position 2'\n\ntry:\n    base64.b85decode(b'|NsC1')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'base85 overflow in hunk starting at byte 0'\n\ntry:\n    base64.b85encode('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"memoryview: a bytes-like object is required, not 'str'\"\n\ntry:\n    base64.b85decode(5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"argument should be a bytes-like object or ASCII string, not 'int'\"\n\n# === z85encode / z85decode ===\nassert base64.z85encode(b'abcd') == b'vpA.S'\nassert base64.z85encode(b'abc') == b'vpAZ'\nassert base64.z85decode(b'vpA.S') == b'abcd'\nassert base64.z85decode('vpA.S') == b'abcd'\nassert base64.z85decode(base64.z85encode(every_byte)) == every_byte\n\n# the five base85 characters z85 does not share are rejected, not decoded\ntry:\n    base64.z85decode(b'vpA.~')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'bad z85 character at position 4'\n\ntry:\n    base64.z85decode(b'#####')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'z85 overflow in hunk starting at byte 0'\n\n# === a85encode / a85decode ===\nassert base64.a85encode(b'') == b''\nassert base64.a85encode(b'hello world') == b'BOu!rD]j7BEbo7'\nassert base64.a85encode(b'abcd') == b'@:E_W'\n# a short final group is zero-padded, then the digits that padding made are cut\nassert base64.a85encode(b'abc') == b'@:E^'\nassert base64.a85encode(b'abc', pad=True) == b'@:E^H'\n# an all-zero word folds to `z`, which is expanded again when it must be trimmed\nassert base64.a85encode(b'\\x00\\x00\\x00\\x00') == b'z'\nassert base64.a85encode(b'\\x00') == b'!!'\nassert base64.a85encode(b'\\x00\\x00\\x00\\x00\\x00') == b'z!!'\nassert base64.a85encode(b'\\xff\\xff\\xff\\xff') == b's8W-!'\n# `y` for four spaces is btoa's extension, off unless asked for\nassert base64.a85encode(b'    ') == b'+<VdL'\nassert base64.a85encode(b'    ', foldspaces=True) == b'y'\nassert base64.a85decode(b'BOu!rD]j7BEbo7') == b'hello world'\nassert base64.a85decode('BOu!rD]j7BEbo7') == b'hello world'\nassert base64.a85decode(b'z') == b'\\x00\\x00\\x00\\x00'\nassert base64.a85decode(b'y', foldspaces=True) == b'    '\nassert base64.a85decode(b='!!!!!') == b'\\x00\\x00\\x00\\x00'\nassert base64.a85decode(base64.a85encode(every_byte)) == every_byte\n\n# whitespace between digits is ignored, other characters are not\nassert base64.a85decode(b'BOu!r D]j7B\\nEbo7') == b'hello world'\n# ignorechars is only consulted for bytes no digit rule matched, so `*` — a\n# digit itself — is decoded rather than skipped, while `~` is skipped\nassert base64.a85decode(b'BOu!r~D]j7B~Ebo7', ignorechars=b'~') == b'hello world'\nassert base64.a85decode(b'BOu!r*D]j7B') == b'hell\\x1dOZO'\n\n# === a85 Adobe framing ===\nassert base64.a85encode(b'hello world', adobe=True) == b'<~BOu!rD]j7BEbo7~>'\nassert base64.a85encode(b'', adobe=True) == b'<~~>'\nassert base64.a85decode(b'<~BOu!rD]j7BEbo7~>', adobe=True) == b'hello world'\n# only the terminator is required, so a PDF stream without `<~` still decodes\nassert base64.a85decode(b'BOu!rD]j7BEbo7~>', adobe=True) == b'hello world'\nassert base64.a85decode(b'<~~>', adobe=True) == b''\n\n# === a85 line wrapping ===\nassert base64.a85encode(b'hello world foo bar', wrapcol=5) == b'BOu!r\\nD]j7B\\nEbo8/\\nAoDT1\\n@UX9'\n# a width below one (or below two with the framing) is raised to that floor\nassert base64.a85encode(b'hello', wrapcol=-5) == b'B\\nO\\nu\\n!\\nr\\nD\\nZ'\n# `~>` must fit on the last line, so a full line gets an empty one after it\nassert base64.a85encode(b'hi', wrapcol=1, adobe=True) == b'<~\\nBP\\n@\\n~>'\nassert base64.a85encode(b'hello world foo bar', wrapcol=6, adobe=True) == b'<~BOu!\\nrD]j7B\\nEbo8/A\\noDT1@U\\nX9~>'\nassert base64.a85decode(base64.a85encode(every_byte, adobe=True, wrapcol=13), adobe=True) == every_byte\n\n# === a85 errors ===\ntry:\n    base64.a85encode('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"memoryview: a bytes-like object is required, not 'str'\"\n\ntry:\n    base64.a85decode(5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"argument should be a bytes-like object or ASCII string, not 'int'\"\n\ntry:\n    base64.a85encode(b'hello', wrapcol=3.0)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"'float' object cannot be interpreted as an integer\"\n\n# a width that loses the `max` is never converted, so a float below the floor is fine\nassert base64.a85encode(b'hello', wrapcol=0.5) == b'B\\nO\\nu\\n!\\nr\\nD\\nZ'\n\ntry:\n    base64.a85encode(b'hello', wrapcol='x')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"'>' not supported between instances of 'str' and 'int'\"\n\ntry:\n    base64.a85decode(b'!!!!~')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'Non-Ascii85 digit found: ~'\n\n# `y` is not a digit at all unless foldspaces is set\ntry:\n    base64.a85decode(b'y')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'Non-Ascii85 digit found: y'\n\ntry:\n    base64.a85decode(b'!z')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'z inside Ascii85 5-tuple'\n\ntry:\n    base64.a85decode(b'!y', foldspaces=True)\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'y inside Ascii85 5-tuple'\n\n# five digits reach 85**5 - 1, half again as much as the four bytes they fill\ntry:\n    base64.a85decode(b'uuuuu')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'Ascii85 overflow'\n\ntry:\n    base64.a85decode(b'BOu!rD]j7BEbo7', adobe=True)\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == \"Ascii85 encoded byte sequences must end with b'~>'\"\n\n# an explicit ignorechars is tested with `in`, so a str rejects the byte probe\ntry:\n    base64.a85decode(b'BOu!r D]j7B', ignorechars=' ')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"'in <string>' requires string as left operand, not int\"\n\ntry:\n    base64.a85decode(b'BOu!r D]j7B', ignorechars=None)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"argument of type 'NoneType' is not a container or iterable\"\n\ntry:\n    base64.a85encode(b'x', True)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == 'a85encode() takes 1 positional argument but 2 were given'\n\ntry:\n    base64.a85decode(b'x', nope=1)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a85decode() got an unexpected keyword argument 'nope'\"\n\n# === encodebytes / decodebytes ===\nassert base64.encodebytes(b'') == b''\nassert base64.encodebytes(b'abc') == b'YWJj\\n'\n# 57 input bytes fill exactly one 76-character line\nassert base64.encodebytes(b'x' * 57) == base64.b64encode(b'x' * 57) + b'\\n'\nassert base64.encodebytes(b'x' * 58).count(b'\\n') == 2\nassert base64.decodebytes(base64.encodebytes(b'x' * 200)) == b'x' * 200\nassert base64.decodebytes(b'YWJj\\n') == b'abc'\n\ntry:\n    base64.encodebytes('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == 'expected bytes-like object, not str'\n\n# decodebytes takes bytes only — unlike b64decode it rejects str\ntry:\n    base64.decodebytes('YWJj')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == 'expected bytes-like object, not str'\n",
  'bench__kitchen_sink.py': "# This test case is also used in the benchmark (benches/main.rs)\n# List operations\nmy_list = []\nmy_list.append(1)\nmy_list.append(2)\nmy_list.insert(0, 0)\nlist_len = len(my_list)\nlist_item = my_list[1]\n\n# Dict operations\nmy_dict = {}\nmy_dict['a'] = 10\nmy_dict['b'] = 20\ndict_val = my_dict['a']\npopped = my_dict.pop('b')\ndict_len = len(my_dict)\n\n# Tuple operations\nmy_tuple = (1, 2, 3)\ntuple_item = my_tuple[0]\ntuple_len = len(my_tuple)\n\n# String operations\ns = 'hello'\ns += ' world'\nstr_len = len(s)\n\n\n# Function definition and call\ndef add(x, y):\n    return x + y\n\n\nfunc_result = add(3, 4)\n\n# For loop with if/elif/else\ntotal = 0\nfor i in range(10):\n    if i < 3:\n        total += 1\n    elif i < 6:\n        total += 2\n    else:\n        total += 3\n\n# Boolean operators and comparisons\nflag = True and not False\ncheck = 1 < 2 and 3 > 2\nidentity = None is None\nnot_identity = 1 is not None\ncompare = 5 >= 5 and 5 <= 5 and 4 != 5\n\n# Assert with message\nassert total > 0\n\n# List comprehension\nsquares = [x * x for x in range(10)]\ncomp_sum = sum(squares)\n\n# Dict comprehension\nsquare_dict = {x: x * x for x in range(5)}\ndict_comp_sum = sum(square_dict.values())\n\n# Final result\nresult = list_len + list_item + dict_val + dict_len + tuple_item + tuple_len\nresult += str_len + func_result + total + comp_sum + dict_comp_sum\nresult\n# Return=373\n",
  'binascii__all.py': "import binascii\n\n# === hexlify / b2a_hex ===\nassert binascii.hexlify(b'') == b''\nassert binascii.hexlify(b'\\xde\\xad') == b'dead'\nassert binascii.hexlify(b'abc') == b'616263'\nassert binascii.b2a_hex(b'\\xde') == b'de'\nassert binascii.hexlify(data=b'ab') == b'6162'\n\n# === hexlify separators ===\n# a positive bytes_per_sep groups from the right, so a short group leads\nassert binascii.hexlify(b'abcd', b'-') == b'61-62-63-64'\nassert binascii.hexlify(b'abcd', '-') == b'61-62-63-64'\nassert binascii.hexlify(b'abcde', b'-', 2) == b'61-6263-6465'\nassert binascii.hexlify(b'abcde', b'-', -2) == b'6162-6364-65'\nassert binascii.hexlify(b'abcde', b'-', 3) == b'6162-636465'\nassert binascii.hexlify(b'abcde', b'-', -3) == b'616263-6465'\n# a group wider than the input, or a zero width, means no separator at all\nassert binascii.hexlify(b'abcde', b'-', 99) == b'6162636465'\nassert binascii.hexlify(b'abcd', b'-', 0) == b'61626364'\nassert binascii.hexlify(b'', b'-') == b''\nassert binascii.hexlify(b'ab', sep=b'-') == b'61-62'\nassert binascii.hexlify(b'ab', b'-', bytes_per_sep=2) == b'6162'\n# the separator is a byte, not a character, so it need not be ASCII\nassert binascii.hexlify(b'ab', b'\\xff') == b'61\\xff62'\nassert binascii.hexlify(b'ab', '\\xff') == b'61\\xff62'\n\n# === hexlify errors ===\ntry:\n    binascii.hexlify(b'abcd', b'--')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'sep must be length 1.'\n\ntry:\n    binascii.hexlify(b'ab', b'')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'sep must be length 1.'\n\ntry:\n    binascii.hexlify(b'ab', '€')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'sep must be ASCII.'\n\ntry:\n    binascii.hexlify(b'ab', 5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"object of type 'int' has no len()\"\n\n# a sized object of length one is still only accepted as `str` or `bytes`,\n# and the length is measured first, so a longer one is a ValueError instead\ntry:\n    binascii.hexlify(b'ab', [1])\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == 'sep must be str or bytes.'\n\ntry:\n    binascii.hexlify(b'ab', (1,))\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == 'sep must be str or bytes.'\n\ntry:\n    binascii.hexlify(b'ab', [1, 2])\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'sep must be length 1.'\n\n# `sep` defaults to unset, not None, so an explicit None has no length\ntry:\n    binascii.hexlify(b'ab', None)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"object of type 'NoneType' has no len()\"\n\ntry:\n    binascii.hexlify('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'str'\"\n\ntry:\n    binascii.hexlify(b'a', b'-', 1.5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"'float' object cannot be interpreted as an integer\"\n\n# === unhexlify / a2b_hex ===\nassert binascii.unhexlify(b'') == b''\nassert binascii.unhexlify(b'dead') == b'\\xde\\xad'\n# unlike b16decode, either case is accepted without a flag\nassert binascii.unhexlify(b'DeAd') == b'\\xde\\xad'\nassert binascii.unhexlify('dead') == b'\\xde\\xad'\nassert binascii.a2b_hex(b'dead') == b'\\xde\\xad'\n\ntry:\n    binascii.unhexlify(b'abc')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Odd-length string'\n\ntry:\n    binascii.unhexlify(b'zz')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Non-hexadecimal digit found'\n\ntry:\n    binascii.unhexlify('caf\\xe9')\n    assert False, 'expected ValueError'\nexcept ValueError as exc:\n    assert str(exc) == 'string argument should contain only ASCII characters'\n\ntry:\n    binascii.unhexlify(5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"argument should be bytes, buffer or ASCII string, not 'int'\"\n\n# === b2a_base64 / a2b_base64 ===\nassert binascii.b2a_base64(b'abc') == b'YWJj\\n'\n# the newline is unconditional, so empty input still produces one\nassert binascii.b2a_base64(b'') == b'\\n'\nassert binascii.b2a_base64(b'abc', newline=False) == b'YWJj'\nassert binascii.a2b_base64(b'YWJj') == b'abc'\nassert binascii.a2b_base64('YWJj') == b'abc'\nassert binascii.a2b_base64(b'') == b''\n# the same forgiving scan base64.b64decode gets\nassert binascii.a2b_base64(b'YQ==YQ==') == b'a\\x06\\x10'\n\ntry:\n    binascii.a2b_base64(b'YWJ')\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Incorrect padding'\n\ntry:\n    binascii.a2b_base64(b'ab!cd', strict_mode=True)\n    assert False, 'expected binascii.Error'\nexcept binascii.Error as exc:\n    assert str(exc) == 'Only base64 data is allowed'\n\ntry:\n    binascii.a2b_base64(5)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"argument should be bytes, buffer or ASCII string, not 'int'\"\n\ntry:\n    binascii.b2a_base64('abc')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'str'\"\n\n# === crc32 ===\nassert binascii.crc32(b'') == 0\nassert binascii.crc32(b'hello') == 907060870\n# feeding the previous result back in resumes the checksum\nassert binascii.crc32(b'lo', binascii.crc32(b'hel')) == binascii.crc32(b'hello')\n# the seed is taken modulo 2**32, so negative and oversized values are fine\nassert binascii.crc32(b'x', -1) == binascii.crc32(b'x', 4294967295)\nassert binascii.crc32(b'x', 4294967296) == binascii.crc32(b'x', 0)\nassert binascii.crc32(b'x', 1180591620717411303424) == binascii.crc32(b'x', 0)\nassert binascii.crc32(b'x', True) == binascii.crc32(b'x', 1)\n\ntry:\n    binascii.crc32('x')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"a bytes-like object is required, not 'str'\"\n\ntry:\n    binascii.crc32(b'x', 'y')\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"'str' object cannot be interpreted as an integer\"\n\n# `crc` defaults to unset, so an explicit None is converted and rejected\ntry:\n    binascii.crc32(b'x', None)\n    assert False, 'expected TypeError'\nexcept TypeError as exc:\n    assert str(exc) == \"'NoneType' object cannot be interpreted as an integer\"\n\n# === round trips over every byte value ===\n_hex_digits = '0123456789abcdef'\nevery_byte = b''\nfor _i in range(256):\n    every_byte += bytes.fromhex(_hex_digits[_i // 16] + _hex_digits[_i % 16])\n\nassert binascii.unhexlify(binascii.hexlify(every_byte)) == every_byte\nassert binascii.a2b_base64(binascii.b2a_base64(every_byte)) == every_byte\nassert binascii.crc32(every_byte) == 688229491\n",
  'bool__ops.py': "import itertools\n\n# === Boolean 'and' operator ===\n# returns first falsy value, or last value if all truthy\nassert (5 and 3) == 3\nassert (0 and 3) == 0\nassert (1 and 2 and 3) == 3\n\n# === Boolean 'or' operator ===\n# returns first truthy value, or last value if all falsy\nassert (5 or 3) == 5\nassert (0 or 3) == 3\nassert (0 or 0 or 3) == 3\n\n# === Boolean 'not' operator ===\nassert (not 5) == False\nassert (not 0) == True\nassert (not None) == True\n\n# === Complex boolean expressions ===\nassert ((1 and 2) or (3 and 0)) == 2\nassert (not (0 and 1)) == True\n\n# === Boolean bitwise operators ===\nassert (True & True) == True\nassert (True & False) == False\nassert (False | True) == True\nassert (False | False) == False\nassert (True ^ False) == True\nassert (True ^ True) == False\nassert type(True & True) == bool\nassert type(False | True) == bool\nassert type(True ^ False) == bool\n\n# Mixing bool and int uses integer bitwise operations.\nassert type(True & 1) == int\nassert type(1 | False) == int\nassert type(True ^ 1) == int\n\n# === bool is accepted wherever an integer argument is ===\n# `bool` is an `int` subclass in CPython, so every \"cannot be interpreted as an\n# integer\" consumer takes it directly.\nassert list(range(True)) == [0]\nassert list(range(False, True)) == [0]\nassert list(range(False, True, True)) == [0]\nassert 'x'.center(True) == 'x'\nassert 'x'.ljust(True) == 'x'\nassert 'x'.rjust(True) == 'x'\nassert 'abcabc'.find('b', True) == 1\nassert b'abcabc'.find(b'b', True) == 1\nassert 'a\\tb'.expandtabs(True) == 'a b'\nassert list(itertools.repeat('x', True)) == ['x']\nassert round(1.234, True) == 1.2\n\n# The same holds for indexing and slicing, which take a separate path.\nassert [10, 20, 30][True] == 20\nassert [10, 20, 30][False] == 10\nassert [1, 2, 3, 4][True:] == [2, 3, 4]\nassert [1, 2, 3, 4][:True] == [1]\n",
  'builtin__add_type_error.py': "len + 1\n# Raise=TypeError(\"unsupported operand type(s) for +: 'builtin_function_or_method' and 'int'\")\n",
  'builtin__filter.py': "assert list(filter(None, [0, 1, False, True, '', 'hello'])) == [1, True, 'hello']\nassert list(filter(None, [])) == []\nassert list(filter(None, [0, 0, 0])) == []\nassert list(filter(None, [1, 2, 3])) == [1, 2, 3]\nassert list(filter(None, ['', '', 'x'])) == ['x']\n\nassert list(filter(abs, [-1, 0, 1])) == [-1, 1]\nassert list(filter(abs, [0, 0, 0])) == []\nassert list(filter(abs, [-5, -3, 0, 2, 0, 4])) == [-5, -3, 2, 4]\n\nassert list(filter(bool, [0, 1, '', 'x'])) == [1, 'x']\nassert list(filter(bool, [False, True, 0, 1])) == [True, 1]\nassert list(filter(bool, [[], [1], (), (2,)])) == [[1], (2,)]\n\n# Note: len returns int, so empty containers return 0 (falsy), non-empty return truthy\nassert list(filter(len, ['', 'a', '', 'bc'])) == ['a', 'bc']\nassert list(filter(len, [[], [1], [], [2, 3]])) == [[1], [2, 3]]\nassert list(filter(len, [(), (1,), (), (2, 3)])) == [(1,), (2, 3)]\n\nassert list(filter(int, ['0', '1', '2', '0'])) == ['1', '2']\nassert list(filter(int, [0.0, 1.5, 0.0, 2.3])) == [1.5, 2.3]\n\nassert list(filter(str, [0, 1, '', 'x'])) == [0, 1, 'x']\n\nassert list(filter(None, [1, 2, 3])) == [1, 2, 3]\n\nassert list(filter(None, (0, 1, 2))) == [1, 2]\n\nassert list(filter(None, 'abc')) == ['a', 'b', 'c']\nassert list(filter(None, 'a b')) == ['a', ' ', 'b']\n\nassert list(filter(None, range(0, 5))) == [1, 2, 3, 4]\nassert list(filter(None, range(1, 4))) == [1, 2, 3]\n\nassert list(filter(None, {0, 1, 2})) == [1, 2] or list(filter(None, {0, 1, 2})) == [2, 1], 'filter set'\n\nassert list(filter(None, [])) == []\nassert list(filter(None, ())) == []\nassert list(filter(None, '')) == []\nassert list(filter(None, range(0))) == []\n\nassert list(filter(None, [[], [1], []])) == [[1]]\nassert list(filter(None, [(), (1,), ()])) == [(1,)]\n\n\n# filter() with user-defined function\n# This should error until user-defined functions are supported\ndef is_positive(x):\n    return x > 0\n\n\nassert list(filter(is_positive, [-1, 1])) == [1]\n\n\nassert list(filter(lambda x: x > 0, [-1, 1])) == [1]\n\n\ntry:\n    list(filter(4, [1, 2]))\n    assert False, 'filter with non-callable first argument should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"'int' object is not callable\"\n",
  'builtin__filter_not_iterable.py': "# filter() with non-iterable second argument\nfilter(None, 42)\n\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"builtin__filter_not_iterable.py\", line 2, in <module>\n    filter(None, 42)\n    ~~~~~~~~~~~~~~~~\nTypeError: 'int' object is not iterable\n\"\"\"\n",
  'builtin__getattr.py': "# Test getattr() builtin function\n\ns = slice(1, 10, 2)\nassert getattr(s, 'start') == 1\nassert getattr(s, 'stop') == 10\nassert getattr(s, 'step') == 2\n\nassert getattr(s, 'nonexistent', 'default') == 'default'\nassert getattr(s, 'nonexistent', None) == None\nassert getattr(s, 'nonexistent', 42) == 42\n\nassert getattr(s, 'start', 999) == 1\n\ntry:\n    getattr(s, 'nonexistent')\n    assert False, 'getattr should raise AttributeError for missing attribute'\nexcept AttributeError:\n    pass\n\ntry:\n    getattr()\n    assert False, 'getattr() with no args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'getattr expected at least 2 arguments, got 0', str(e)\n\ntry:\n    getattr(kwarg=1)\n    assert False, 'getattr() with keyword arg should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'getattr() takes no keyword arguments', str(e)\n\ntry:\n    getattr(s)\n    assert False, 'getattr() with 1 arg should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'getattr expected at least 2 arguments, got 1', str(e)\n\ntry:\n    getattr(s, 'start', 'default', 'extra')\n    assert False, 'getattr() with 4 args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'getattr expected at most 3 arguments, got 4', str(e)\n\ntry:\n    getattr(s, 123)\n    assert False, 'getattr() with non-string name should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"attribute name must be string, not 'int'\", str(e)\n\ntry:\n    getattr(s, None)\n    assert False, 'getattr() with None name should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"attribute name must be string, not 'NoneType'\", str(e)\n\ntry:\n    raise ValueError('test error')\nexcept ValueError as e:\n    args = getattr(e, 'args')\n    assert args == ('test error',)\n\n# === Dynamic (heap-allocated) attribute name strings ===\n# These test that getattr works with non-interned strings (e.g. from concatenation)\ns2 = slice(5, 15, 3)\nattr_name = 'sta' + 'rt'\nassert getattr(s2, attr_name) == 5\n\nattr_name = 'st' + 'op'\nassert getattr(s2, attr_name) == 15\n\nattr_name = 'st' + 'ep'\nassert getattr(s2, attr_name) == 3\n\n# Dynamic attribute name with default for missing attribute\nattr_name = 'non' + 'existent'\nassert getattr(s2, attr_name, 42) == 42\n\n# Dynamic attribute name on exception\ntry:\n    raise TypeError('dynamic test')\nexcept TypeError as e:\n    attr_name = 'ar' + 'gs'\n    args = getattr(e, attr_name)\n    assert args == ('dynamic test',)\n\n# === Dynamic names on builtin types ===\n# Builtin attributes dispatch on interned string ids, so a name built at\n# runtime has to be resolved back through the interner before dispatch.\nimport datetime\n\nassert getattr(datetime.timezone, 'ut' + 'c') is datetime.timezone.utc\nassert getattr(datetime.time(12, 30), 'ho' + 'ur') == 12\nassert getattr(datetime.date(2024, 6, 15), 'mon' + 'th') == 6\nassert getattr(datetime.timedelta(hours=1), 'sec' + 'onds') == 3600\n# a name the interner has never seen still misses, rather than erroring oddly\nassert getattr(datetime.date(2024, 6, 15), 'no' + 'pe', 'MISSING') == 'MISSING'\n",
  'builtin__hasattr.py': "# Test hasattr() builtin function\n\ns = slice(1, 10, 2)\n\nassert hasattr(s, 'start') == True\nassert hasattr(s, 'stop') == True\nassert hasattr(s, 'step') == True\n\nassert hasattr(s, 'nonexistent') == False\nassert hasattr(s, 'foo') == False\nassert hasattr(s, 'bar') == False\n\ntry:\n    raise ValueError('test error')\nexcept ValueError as e:\n    assert hasattr(e, 'args') == True\n    assert hasattr(e, 'nonexistent') == False\n\nassert hasattr(42, 'start') == False\nassert hasattr('hello', 'nonexistent') == False\n\ntry:\n    hasattr()\n    assert False, 'hasattr() with no args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'hasattr expected 2 arguments, got 0', str(e)\n\ntry:\n    hasattr(s)\n    assert False, 'hasattr() with 1 arg should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'hasattr expected 2 arguments, got 1', str(e)\n\ntry:\n    hasattr(s, 'start', 'extra')\n    assert False, 'hasattr() with 3 args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'hasattr expected 2 arguments, got 3', str(e)\n\ntry:\n    hasattr(s, 123)\n    assert False, 'hasattr() with non-string name should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"attribute name must be string, not 'int'\", str(e)\n\ntry:\n    hasattr(s, None)\n    assert False, 'hasattr() with None name should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"attribute name must be string, not 'NoneType'\", str(e)\n\n# === Dynamic names on builtin types ===\n# Same interner round-trip as `getattr`: a runtime-built name must resolve.\nimport datetime\n\nassert hasattr(datetime.timezone, 'ut' + 'c')\nassert hasattr(datetime.time(12, 30), 'ho' + 'ur')\nassert not hasattr(datetime.time(12, 30), 'no' + 'pe')\n",
  'builtin__iter_err_unpack_int.py': "iterator = 0\n\niter(**42)\n# Raise=TypeError('iter() argument after ** must be a mapping, not int')\n",
  'builtin__iter_funcs.py': "# === sum() ===\n# Basic sum operations\nassert sum([1, 2, 3]) == 6\nassert sum([1, 2, 3], 10) == 16\nassert sum([1, 2, 3], start=10) == 16\nassert sum(()) == 0\nassert sum([], 5) == 5\nassert sum(range(5)) == 10\nassert sum([1.5, 2.5, 3.0], 0.0) == 7.0\n# Note: sum of floats without start requires py_add to support int+float\n\n# str/bytes start values are rejected, pointing at join() instead\ntry:\n    sum([], 'x')\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sum() can't sum strings [use ''.join(seq) instead]\"\n\ntry:\n    sum([], b'x')\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sum() can't sum bytes [use b''.join(seq) instead]\"\n\ntry:\n    sum([b'a'], start=b'')\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sum() can't sum bytes [use b''.join(seq) instead]\"\n\n# sum with different iterables\nassert sum({1, 2, 3}) == 6\nassert sum({1: 'a', 2: 'b', 3: 'c'}) == 6\n\n# === any() ===\n# Basic any operations\nassert any([True, False, False]) == True\nassert any([False, False, False]) == False\nassert any([]) == False\nassert any([0, 0, 1]) == True\nassert any([0, '', None]) == False\nassert any(['', 'hello']) == True\nassert any(range(0, 5)) == True\nassert any(range(0, 1)) == False\n\n# === all() ===\n# Basic all operations\nassert all([True, True, True]) == True\nassert all([True, False, True]) == False\nassert all([]) == True\nassert all([1, 2, 3]) == True\nassert all([1, 0, 3]) == False\nassert all(['a', 'b', 'c']) == True\nassert all(['a', '', 'c']) == False\n\n# More edge cases with nested structures\nassert any([[1], [], [3]]) == True\nassert all([[1], [2], [3]]) == True\n\n# sum with lists (list + list is supported)\nassert sum([[1], [2], [3]], []) == [1, 2, 3]\n# Note: sum with tuples requires Tuple py_add which is not implemented\n",
  'builtin__iter_next.py': "# === iter() on various iterables ===\n# iter() creates an iterator from an iterable\n\n# iter() on list\nit = iter([1, 2, 3])\nassert next(it) == 1\nassert next(it) == 2\nassert next(it) == 3\n\n# iter() on tuple\nit = iter((10, 20))\nassert next(it) == 10\nassert next(it) == 20\n\n# iter() on string\nit = iter('ab')\nassert next(it) == 'a'\nassert next(it) == 'b'\n\n# iter() on range\nit = iter(range(3))\nassert next(it) == 0\nassert next(it) == 1\nassert next(it) == 2\n\n# iter() on dict iterates over keys\nd = {'x': 1, 'y': 2}\nit = iter(d)\nkeys = [next(it), next(it)]\nassert 'x' in keys\nassert 'y' in keys\n\n# === next() with default value ===\n# next() returns default when iterator is exhausted\n\nit = iter([42])\nassert next(it) == 42\nassert next(it, 'done') == 'done'\n\n# Check default with various types\nit = iter([])\nassert next(it, None) is None\nassert next(it, 0) == 0\nassert next(it, []) == []\n\n# === iter() on iterator returns itself ===\n# Calling iter() on an iterator should return the same iterator\n\noriginal = iter([1, 2, 3])\nsame = iter(original)\n# They should iterate over the same values\nassert next(original) == 1\nassert next(same) == 2\nassert next(original) == 3\n\n# === Multiple independent iterators ===\n# Creating multiple iterators over the same iterable should be independent\n\ndata = [1, 2, 3]\nit1 = iter(data)\nit2 = iter(data)\nassert next(it1) == 1\nassert next(it1) == 2\nassert next(it2) == 1\nassert next(it1) == 3\nassert next(it2) == 2\n",
  'builtin__map.py': "assert list(map(abs, [-1, 0, 1, -2])) == [1, 0, 1, 2]\nassert list(map(abs, [0, 0, 0])) == [0, 0, 0]\n\nassert list(map(str, [1, 2, 3])) == ['1', '2', '3']\nassert list(map(str, [True, False])) == ['True', 'False']\n\nassert list(map(int, ['1', '2', '3'])) == [1, 2, 3]\nassert list(map(int, [1.1, 2.9, 3.5])) == [1, 2, 3]\nassert list(map(int, [True, False, True])) == [1, 0, 1]\n\nassert list(map(bool, [0, 1, '', 'x'])) == [False, True, False, True]\nassert list(map(bool, [[], [1], (), (2,)])) == [False, True, False, True]\n\nassert list(map(len, ['', 'a', 'ab', 'abc'])) == [0, 1, 2, 3]\nassert list(map(len, [[], [1], [1, 2], [1, 2, 3]])) == [0, 1, 2, 3]\n\nassert list(map(float, [1, 2, 3])) == [1.0, 2.0, 3.0]\nassert list(map(float, ['1.5', '2.5'])) == [1.5, 2.5]\n\nassert list(map(abs, [1, -2, 3])) == [1, 2, 3]\n\nassert list(map(abs, (1, -2, 3))) == [1, 2, 3]\n\nassert list(map(ord, 'abc')) == [97, 98, 99]\n\nassert list(map(abs, range(-3, 3))) == [3, 2, 1, 0, 1, 2]\n\nresult = list(map(abs, {-1, 0, 1}))\nassert sorted(result) == [0, 1, 1]\n\nassert list(map(abs, [])) == []\nassert list(map(abs, ())) == []\nassert list(map(abs, '')) == []\nassert list(map(abs, range(0))) == []\n\nassert list(map(list, [(1, 2), (3, 4)])) == [[1, 2], [3, 4]]\nassert list(map(tuple, [[1, 2], [3, 4]])) == [(1, 2), (3, 4)]\n\nassert list(map(pow, [2, 3, 4], [3, 2, 2])) == [8, 9, 16]\n\nassert list(map(divmod, [10, 20, 30], [3, 6, 7])) == [(3, 1), (3, 2), (4, 2)]\n\nassert list(map(pow, [2, 3, 4, 5], [3, 2])) == [8, 9]\nassert list(map(pow, [2, 3], [3, 2, 1, 0])) == [8, 9]\n\nassert list(map(pow, [2], [3, 4, 5])) == [8]\n\n\ndef f(x):\n    return x * 2\n\n\nassert list(map(f, [1, 2, 3])) == [2, 4, 6]\n\n\ndef raise_exception(x):\n    raise ValueError('Intentional error')\n\n\ntry:\n    list(map(raise_exception, [1, 2, 3]))\n    assert False, 'should have failed with exception'\nexcept ValueError as e:\n    assert str(e) == 'Intentional error'\n\ntry:\n    map()\n    assert False, 'map() should require arguments'\nexcept TypeError as e:\n    assert str(e) == 'map() must have at least two arguments.', f'map() arity: {e}'\n\ntry:\n    map(None)\n    assert False, 'map() with single arg should fail'\nexcept TypeError as e:\n    assert str(e) == 'map() must have at least two arguments.', f'map(fn) arity: {e}'\n",
  'builtin__map_not_iterable.py': "# map() with non-iterable second argument\nmap(abs, 42)\n\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"builtin__map_not_iterable.py\", line 2, in <module>\n    map(abs, 42)\n    ~~~~~~~~~~~~\nTypeError: 'int' object is not iterable\n\"\"\"\n",
  'builtin__math_funcs.py': "import sys\n\nis_monty = sys.platform == 'monty'\n\n# === abs() ===\n# Basic abs operations\nassert abs(5) == 5\nassert abs(-5) == 5\nassert abs(0) == 0\nassert abs(3.14) == 3.14\nassert abs(-3.14) == 3.14\nassert abs(True) == 1\nassert abs(False) == 0\n\n# === round() ===\n# Basic round operations\nassert round(2.5) == 2\nassert round(3.5) == 4\nassert round(0.5) == 0\nassert round(-0.5) == 0\nassert round(2.4) == 2\nassert round(2.6) == 3\nassert round(-2.5) == -2\nassert round(-1.5) == -2\nassert round(5) == 5\n\n# round with ndigits\nassert round(3.14159, 2) == 3.14\nassert round(3.14159, 0) == 3.0\n# both round() arguments are keyword-capable in CPython\nassert round(3.14159, ndigits=2) == 3.14\nassert round(number=3.14159, ndigits=2) == 3.14\nassert round(ndigits=2, number=3.14159) == 3.14\nassert repr(round(-0.4, 0)) == '-0.0'\nassert repr(round(-0.5, 0)) == '-0.0'\nassert round(1234, -2) == 1200\nassert round(1250, -2) == 1200\nassert round(1350, -2) == 1400\nassert round(15, -1) == 20\nassert round(25, -1) == 20\n\n# round with None\nassert round(2.5, None) == 2\nassert round(True, -1) == 0\nassert round(True, 2) == 1\nassert round(False, -3) == 0\n\n# round type errors\nthrew = False\ntry:\n    round(1.2, 1.5)\nexcept TypeError:\n    threw = True\nassert threw\n\n# ndigits wider than i64 is clamped by sign: huge positive returns the number\n# unchanged; huge negative rounds to 0 / ±0.0\nassert round(5, 10**30) == 5\nassert round(-5, 10**30) == -5\nassert round(2.675, 10**30) == 2.675\nassert round(5, 2**63 - 1) == 5\nassert round(1.5, -(10**30)) == 0.0\nassert repr(round(-1.5, -(10**30))) == '-0.0'\nassert round(1.5, -(2**63)) == 0.0\nassert round(12345, -(10**5)) == 0\n\n# negative ndigits round exactly in integers (no float corruption), promoting\n# past i64 when rounding up crosses it\nassert round(2**63 - 1, -1) == 9223372036854775810\nassert round(2**63 - 1, -19) == 10**19\nassert round(-(2**63 - 1), -19) == -(10**19)\nassert round(5 * 10**18, -19) == 0\nassert round(2**63 - 1, -25) == 0\nassert round(1234567890123456789, -5) == 1234567890123500000\nassert round(-1250, -2) == -1200\nif is_monty:\n    # CPython tries to materialise 10**(10**30) here and dies with\n    # MemoryError; Monty's clamp returns 0 immediately (limitations/builtins.md)\n    assert round(5, -(10**30)) == 0\n    assert round(5, -(2**63)) == 0\n\n# round edge cases with extreme values\nassert isinstance(round(1e15), int)\nassert isinstance(round(-1e15), int)\nassert round(9.223372036854776e18) == 9223372036854775808\nassert round(1e20) == 100000000000000000000\nassert round(-1e20) == -100000000000000000000\nassert round(1.7976931348623157e308) == (2**53 - 1) * 2**971\nassert round(0.0) == 0\nassert round(-0.0) == 0\n\n# round special float values (infinity / NaN)\ninf = float('inf')\nneg_inf = float('-inf')\nnan = float('nan')\n\nthrew = False\ntry:\n    round(inf)\nexcept OverflowError:\n    threw = True\nassert threw\n\nthrew = False\ntry:\n    round(neg_inf)\nexcept OverflowError:\n    threw = True\nassert threw\n\nthrew = False\ntry:\n    round(nan)\nexcept ValueError:\n    threw = True\nassert threw\n\nr = round(inf, 0)\nassert r == inf\n\nr = round(neg_inf, 0)\nassert r == neg_inf\n\nr = round(nan, 0)\nassert r != r\n\n# round with extreme ndigits values\nassert round(1.23, 10**6) == 1.23\nassert round(1.23, -(10**6)) == 0.0\nassert repr(round(-1.23, -(10**6))) == '-0.0'\n\n# round with float result (ndigits specified)\nassert isinstance(round(1.5, 1), float)\nassert round(1.25, 1) == 1.2\nassert round(1.35, 1) == 1.4\n\n# === divmod() ===\n# Basic divmod operations\nassert divmod(17, 5) == (3, 2)\nassert divmod(10, 3) == (3, 1)\nassert divmod(9, 3) == (3, 0)\nassert divmod(-10, 3) == (-4, 2)\nassert divmod(10, -3) == (-4, -2)\nassert divmod(-10, -3) == (3, -1)\n\n# divmod with floats\nr = divmod(7.5, 2.5)\nassert r[0] == 3.0 and r[1] == 0.0, 'divmod floats'\nassert divmod(True, 2) == (0, 1)\nassert divmod(5, True) == (5, 0)\n\n# === pow() ===\n# Basic pow operations\nassert pow(2, 3) == 8\nassert pow(2, 0) == 1\nassert pow(5, 1) == 5\nassert pow(2, 10) == 1024\n\n# pow with negative exponent\nassert pow(2, -1) == 0.5\nassert pow(4, -2) == 0.0625\n\n# pow with floats\nassert pow(2.0, 3.0) == 8.0\nassert pow(4.0, 0.5) == 2.0\n\n# Three-argument pow (modular exponentiation)\nassert pow(2, 10, 1000) == 24\nassert pow(3, 4, 5) == 1\nassert pow(7, 256, 13) == 9\n\n# Modular exponentiation with heap-backed integers\nbig = 2**63\nassert pow(big, 3, 7) == 1\nassert pow(2, big, 7) == 4\nassert pow(2, 3, big + 1) == 8\nassert pow(big, 3, -(big + 1)) == -1\n\n# Modular exponentiation edge cases\nassert pow(2, 0, 5) == 1\nassert pow(0, 5, 3) == 0\n\n# |modulo| == 1 always returns 0, including the exp == 0 corner case\nassert pow(5, 3, 1) == 0\nassert pow(5, 3, -1) == 0\nassert pow(5, 0, 1) == 0\nassert pow(5, 0, -1) == 0\n\n# i64::MIN base with modulo == -1 used to panic via rem_euclid overflow\nassert pow(-9223372036854775808, 1, -1) == 0\nassert pow(-9223372036854775808, 7, -1) == 0\nassert pow(True, 2) == 1\nassert pow(2, True) == 2\nassert pow(True, True) == 1\nassert pow(True, -1) == 1.0\n\nthrew = False\ntry:\n    pow(0, -1)\nexcept ZeroDivisionError:\n    threw = True\nassert threw\n\nthrew = False\ntry:\n    pow(0.0, -1)\nexcept ZeroDivisionError:\n    threw = True\nassert threw\n",
  'builtin__more_iter_funcs.py': "# === min() ===\n# Basic min operations\nassert min([1, 2, 3]) == 1\nassert min([3, 1, 2]) == 1\nassert min([5]) == 5\nassert min(1, 2, 3) == 1\nassert min(3, 1, 2) == 1\nassert min(-5, -10, -1) == -10\n\n# min with strings\nassert min(['b', 'a', 'c']) == 'a'\nassert min('b', 'a', 'c') == 'a'\n\n# min with floats\nassert min([1.5, 0.5, 2.5]) == 0.5\nassert min(1.5, 0.5) == 0.5\n\n# === max() ===\n# Basic max operations\nassert max([1, 2, 3]) == 3\nassert max([3, 1, 2]) == 3\nassert max([5]) == 5\nassert max(1, 2, 3) == 3\nassert max(3, 1, 2) == 3\nassert max(-5, -10, -1) == -1\n\n# max with strings\nassert max(['b', 'a', 'c']) == 'c'\nassert max('b', 'a', 'c') == 'c'\n\n# max with floats\nassert max([1.5, 0.5, 2.5]) == 2.5\nassert max(1.5, 2.5) == 2.5\n\n# max with keyword arguments\nassert max([3, -1, 2, -4], key=abs) == -4\nassert max(['a', 'bbb', 'cc'], key=len) == 'bbb'\nassert max(['a', 'bbb', 'cc'], key=lambda s: len(s)) == 'bbb'\nassert max('a', 'bbb', 'cc', key=len) == 'bbb'\nassert max([1, 2, 3], key=None) == 3\nassert max([], default='fallback') == 'fallback'\nassert max([], key=len, default='fallback') == 'fallback'\n\n# min with keyword arguments\nassert min([3, -1, 2, -4], key=abs) == -1\nassert min(['a', 'bbb', 'cc'], key=len) == 'a'\nassert min(['a', 'bbb', 'cc'], key=lambda s: len(s)) == 'a'\nassert min('a', 'bbb', 'cc', key=len) == 'a'\nassert min([1, 2, 3], key=None) == 1\nassert min([], default='fallback') == 'fallback'\nassert min([], key=len, default='fallback') == 'fallback'\n\n# max/min with tuple-producing key functions\nranked_items = [\n    {'downloads': 10, 'likes': 1},\n    {'downloads': 10, 'likes': 5},\n    {'downloads': 20, 'likes': 0},\n]\nassert max(ranked_items, key=lambda item: (item.get('downloads', 0), item.get('likes', 0))) == {\n    'downloads': 20,\n    'likes': 0,\n}\n\ntie_items = [\n    {'downloads': 10, 'likes': 5, 'name': 'first'},\n    {'downloads': 10, 'likes': 5, 'name': 'second'},\n]\nassert max(tie_items, key=lambda item: (item['downloads'], item['likes']))['name'] == 'first'\nassert min(tie_items, key=lambda item: (item['downloads'], item['likes']))['name'] == 'first'\n\nrows = [{'x': 1}, {'x': 2}]\nassert {name: max(rows, key=lambda row: row[name]) for name in ['x']} == {'x': {'x': 2}}\n\ntry:\n    max([1], nope=1)\n    assert False, 'invalid max keyword should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"max() got an unexpected keyword argument 'nope'\",)\n\ntry:\n    min([1], nope=1)\n    assert False, 'invalid min keyword should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"min() got an unexpected keyword argument 'nope'\",)\n\ntry:\n    max(key=int)\n    assert False, 'max with only kwargs should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('max expected at least 1 argument, got 0',)\n\ntry:\n    min(default=None, key=int)\n    assert False, 'min with only kwargs should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('min expected at least 1 argument, got 0',)\n\ntry:\n    max(nope=1)\n    assert False, 'max with only unexpected kwargs should still raise a TypeError'\nexcept TypeError:\n    # CPython: 'max expected at least 1 argument, got 0' (validates positional\n    # count first). Monty: \"max() got an unexpected keyword argument 'nope'\"\n    # (validates kwargs first, via the FromArgs macro pipeline).\n    pass\n\ntry:\n    min(nope=1)\n    assert False, 'min with only unexpected kwargs should still raise a TypeError'\nexcept TypeError:\n    # See note above; Monty differs from CPython on validation order.\n    pass\n\ntry:\n    max(key=int, nope=1)\n    assert False, 'max with mixed kwargs and no positional args should still raise a TypeError'\nexcept TypeError:\n    # See note above; Monty differs from CPython on validation order.\n    pass\n\ntry:\n    max(1, 2, default=3)\n    assert False, 'max with multiple args and default should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('Cannot specify a default for max() with multiple positional arguments',)\n\ntry:\n    min(1, 2, default=3)\n    assert False, 'min with multiple args and default should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('Cannot specify a default for min() with multiple positional arguments',)\n\ntry:\n    max(1, key=int)\n    assert False, 'max single non-iterable arg with key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"'int' object is not iterable\",)\n\ntry:\n    min(1, key=int)\n    assert False, 'min single non-iterable arg with key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"'int' object is not iterable\",)\n\ntry:\n    max([1], key=1)\n    assert False, 'max non-callable key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"'int' object is not callable\",)\n\ntry:\n    min([1], key=1)\n    assert False, 'min non-callable key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"'int' object is not callable\",)\n\ntry:\n    max([])\n    assert False, 'max empty iterable without default should raise ValueError'\nexcept ValueError as e:\n    assert e.args == ('max() iterable argument is empty',)\n\ntry:\n    min([])\n    assert False, 'min empty iterable without default should raise ValueError'\nexcept ValueError as e:\n    assert e.args == ('min() iterable argument is empty',)\n\nassert max([1], default=2) == 1\nassert min([1], default=2) == 1\nassert max([], key=1, default='fallback') == 'fallback'\nassert min([], key=1, default='fallback') == 'fallback'\n\ntry:\n    max([1], key=abs, **{'key': len})\n    assert False, 'duplicate max key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"max() got multiple values for keyword argument 'key'\",)\n\ntry:\n    min([], default='x', **{'default': 'y'})\n    assert False, 'duplicate min default should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"min() got multiple values for keyword argument 'default'\",)\n\ntry:\n    max([], **{1: 2})\n    assert False, 'max non-string keyword key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('keywords must be strings',)\n\ntry:\n    max([1, 'a'])\n    assert False, 'max with incomparable iterable items should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"'>' not supported between instances of 'str' and 'int'\",)\n\ntry:\n    min(1, 'a')\n    assert False, 'min with incomparable positional args should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"'<' not supported between instances of 'str' and 'int'\",)\n\nmax_key_map = {10: 1, 20: 3, 30: 3, 40: 2}\nassert max([10, 20, 30, 40], key=lambda item: max_key_map[item]) == 20\n\nmin_key_map = {10: 2, 20: 1, 30: 1, 40: 3}\nassert min([10, 20, 30, 40], key=lambda item: min_key_map[item]) == 20\n\n# === sorted() ===\n# Basic sorted operations\nassert sorted([3, 1, 2]) == [1, 2, 3]\nassert sorted([1, 2, 3]) == [1, 2, 3]\nassert sorted([3, 2, 1]) == [1, 2, 3]\nassert sorted([]) == []\nassert sorted([5]) == [5]\n\n# sorted with strings\nassert sorted(['c', 'a', 'b']) == ['a', 'b', 'c']\n\n# sorted with heap-allocated strings (from split)\nassert sorted('banana,apple,cherry'.split(',')) == ['apple', 'banana', 'cherry']\n\n# sorted with multi-char string literals (heap-allocated)\nassert sorted(['banana', 'apple', 'cherry']) == ['apple', 'banana', 'cherry']\n\n# min/max with heap-allocated strings\nassert min('banana,apple,cherry'.split(',')) == 'apple'\nassert max('banana,apple,cherry'.split(',')) == 'cherry'\n\n# sorted with negative numbers\nassert sorted([-3, 1, -2, 2]) == [-3, -2, 1, 2]\n\n# sorted with tuple\nassert sorted((3, 1, 2)) == [1, 2, 3]\n\n# sorted preserves duplicates\nassert sorted([3, 1, 2, 1, 3]) == [1, 1, 2, 3, 3]\n\n# sorted with range\nassert sorted(range(5, 0, -1)) == [1, 2, 3, 4, 5]\n\ntry:\n    sorted(1, 2)\n    assert False, 'sorted() with too many positional arguments should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('sorted expected 1 argument, got 2',)\n\ntry:\n    sorted([1], nope=1)\n    assert False, 'sorted() with invalid keyword should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sort() got an unexpected keyword argument 'nope'\", f'sorted unknown kw: {e}'\n\n# === sorted() with reverse ===\nassert sorted([3, 1, 2], reverse=True) == [3, 2, 1]\nassert sorted([3, 1, 2], reverse=False) == [1, 2, 3]\nassert sorted(['c', 'a', 'b'], reverse=True) == ['c', 'b', 'a']\nassert sorted([], reverse=True) == []\nassert sorted([5], reverse=True) == [5]\nassert sorted([3, 1, 2], reverse=0) == [1, 2, 3]\nassert sorted([3, 1, 2], reverse=1) == [3, 2, 1]\n\n# === sorted() with key ===\nassert sorted([3, -1, 2, -4], key=abs) == [-1, 2, 3, -4]\nassert sorted(['banana', 'apple', 'cherry'], key=len) == ['apple', 'banana', 'cherry']\nassert sorted([3, 1, 2], key=None) == [1, 2, 3]\n\ntry:\n    sorted([1], key=abs, **{'key': len})\n    assert False, 'duplicate sorted key should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"sorted() got multiple values for keyword argument 'key'\",)\n\n\ndef negate(x):\n    return -x\n\n\nassert sorted([1, -2, 3], key=negate) == [3, 1, -2]\n\n# === sorted() with key and reverse ===\nassert sorted([3, -1, 2, -4], key=abs, reverse=True) == [-4, 3, 2, -1]\nassert sorted(['banana', 'apple', 'cherry'], key=len, reverse=True) == ['banana', 'cherry', 'apple']\nassert sorted([3, 1, 2], key=None, reverse=True) == [3, 2, 1]\n\n# === reversed() ===\n# Basic reversed operations\nassert list(reversed([1, 2, 3])) == [3, 2, 1]\nassert list(reversed([1])) == [1]\nassert list(reversed([])) == []\n\n# reversed tuple\nassert list(reversed((1, 2, 3))) == [3, 2, 1]\n\n# reversed string\nassert list(reversed('abc')) == ['c', 'b', 'a']\n\n# reversed range\nassert list(reversed(range(1, 4))) == [3, 2, 1]\n\n# === enumerate() ===\n# Basic enumerate operations\nassert list(enumerate(['a', 'b', 'c'])) == [(0, 'a'), (1, 'b'), (2, 'c')]\nassert list(enumerate([])) == []\nassert list(enumerate(['x'])) == [(0, 'x')]\n\n# enumerate with start\nassert list(enumerate(['a', 'b'], 1)) == [(1, 'a'), (2, 'b')]\nassert list(enumerate(['a', 'b'], 10)) == [(10, 'a'), (11, 'b')]\n\n# a non-iterable errors out of iterator construction without leaking a\n# heap-backed start=\ntry:\n    enumerate(1, start=10**30)\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"'int' object is not iterable\"\n\n# enumerate keyword forms (CPython's vectorcall accepts all of these)\nassert list(enumerate(['a', 'b'], start=1)) == [(1, 'a'), (2, 'b')]\nassert list(enumerate(iterable=['a'])) == [(0, 'a')]\nassert list(enumerate(iterable=['a'], start=2)) == [(2, 'a')]\nassert list(enumerate(start=2, iterable=['a'])) == [(2, 'a')]\nassert list(enumerate(['a'], start=True)) == [(1, 'a')]\n\n# enumerate string\nassert list(enumerate('ab')) == [(0, 'a'), (1, 'b')]\n\n# enumerate range\nassert list(enumerate(range(3))) == [(0, 0), (1, 1), (2, 2)]\n\n# === zip() ===\n# Basic zip operations\nassert list(zip([1, 2], ['a', 'b'])) == [(1, 'a'), (2, 'b')]\nassert list(zip([1], ['a'])) == [(1, 'a')]\nassert list(zip([], [])) == []\n\n# zip truncates to shortest\nassert list(zip([1, 2, 3], ['a', 'b'])) == [(1, 'a'), (2, 'b')]\nassert list(zip([1], ['a', 'b', 'c'])) == [(1, 'a')]\n\n# zip three iterables\nassert list(zip([1, 2], ['a', 'b'], [True, False])) == [(1, 'a', True), (2, 'b', False)]\n\n# zip with different types\nassert list(zip(range(3), 'abc')) == [(0, 'a'), (1, 'b'), (2, 'c')]\n\n# zip single iterable\nassert list(zip([1, 2, 3])) == [(1,), (2,), (3,)]\n\n# zip with empty\nassert list(zip([1, 2], [])) == []\nassert list(zip([], [1, 2])) == []\n\n# === zip(strict=True) ===\n# Equal length iterables succeed\nassert list(zip([1, 2], [3, 4], strict=True)) == [(1, 3), (2, 4)]\nassert list(zip([1], [2], [3], strict=True)) == [(1, 2, 3)]\nassert list(zip([], [], strict=True)) == []\nassert list(zip(strict=True)) == []\nassert list(zip([1, 2, 3], strict=True)) == [(1,), (2,), (3,)]\n\n# strict=False behaves like default\nassert list(zip([1, 2, 3], [4, 5], strict=False)) == [(1, 4), (2, 5)]\n\n# Falsy values are accepted\nassert list(zip([1, 2, 3], [4, 5], strict=0)) == [(1, 4), (2, 5)]\n\n# Second argument shorter\ntry:\n    list(zip([1, 2, 3], [4, 5], strict=True))\n    assert False, 'zip strict should raise for shorter arg 2'\nexcept ValueError as e:\n    assert str(e) == 'zip() argument 2 is shorter than argument 1'\n\n# Second argument longer\ntry:\n    list(zip([1, 2], [4, 5, 6], strict=True))\n    assert False, 'zip strict should raise for longer arg 2'\nexcept ValueError as e:\n    assert str(e) == 'zip() argument 2 is longer than argument 1'\n\n# Third argument shorter with plural\ntry:\n    list(zip([1, 2], [3, 4], [5], strict=True))\n    assert False, 'zip strict should raise for shorter arg 3'\nexcept ValueError as e:\n    assert str(e) == 'zip() argument 3 is shorter than arguments 1-2'\n\n# Fourth argument shorter\ntry:\n    list(zip([1, 2], [3, 4], [5, 6], [7], strict=True))\n    assert False, 'zip strict should raise for shorter arg 4'\nexcept ValueError as e:\n    assert str(e) == 'zip() argument 4 is shorter than arguments 1-3'\n\n# Third argument longer than arguments 1-2 (both exhausted)\ntry:\n    list(zip([1], [2], [3, 4], strict=True))\n    assert False, 'zip strict should raise for longer arg 3'\nexcept ValueError as e:\n    assert str(e) == 'zip() argument 3 is longer than arguments 1-2'\n\n# Unexpected keyword argument\ntry:\n    list(zip([1], foo=True))\n    assert False, 'zip unexpected kwarg should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"zip() got an unexpected keyword argument 'foo'\"\n",
