  'builtin__print_kwargs.py': "# Tests dynamic keyword arguments for print()\n\n# === Dynamic sep via **kwargs ===\ndynamic_sep = 's' + 'e' + 'p'\nresult = print('left', 'right', **{dynamic_sep: '-'})\nassert result is None\n\n\n# === Dynamic end via **kwargs ===\ndynamic_end = 'e' + 'n' + 'd'\nresult2 = print('line', **{dynamic_end: ''})\nassert result2 is None\n",
  'builtin__repr.py': "# === repr of None, True, False, Ellipsis, NotImplemented ===\nassert repr(None) == 'None'\nassert repr(True) == 'True'\nassert repr(False) == 'False'\nassert repr(...) == 'Ellipsis'\nassert repr(NotImplemented) == 'NotImplemented'\n\n# === repr of ints (Value::Int) ===\nassert repr(0) == '0'\nassert repr(1) == '1'\nassert repr(-1) == '-1'\nassert repr(42) == '42'\nassert repr(-999) == '-999'\nassert repr(9223372036854775807) == '9223372036854775807'\nassert repr(-9223372036854775808) == '-9223372036854775808'\n\n# === repr of big ints (Value::InternLongInt / HeapData::LongInt) ===\nassert repr(9223372036854775808) == '9223372036854775808'\nassert repr(-9223372036854775809) == '-9223372036854775809'\nassert repr(10**20) == '100000000000000000000'\nassert repr(-(10**20)) == '-100000000000000000000'\n\n# === repr of floats (Value::Float) ===\nassert repr(0.0) == '0.0'\nassert repr(-0.0) == '-0.0'\nassert repr(1.0) == '1.0'\nassert repr(2.0) == '2.0'\nassert repr(0.5) == '0.5'\nassert repr(2.5) == '2.5'\nassert repr(100.0) == '100.0'\nassert repr(-3.14) == '-3.14'\nassert repr(0.1) == '0.1'\n\n# === repr of strings (Value::InternString / HeapData::Str) ===\nassert repr('') == \"''\"\nassert repr('hello') == \"'hello'\"\nassert repr(\"it's\") == '\"it\\'s\"'\nassert repr('say \"hi\"') == '\\'say \"hi\"\\''\nassert repr('it\\'s \"complex\"') == \"'it\\\\'s \\\"complex\\\"'\"\nassert repr('a\\nb') == \"'a\\\\nb'\"\nassert repr('a\\tb') == \"'a\\\\tb'\"\nassert repr('a\\\\b') == \"'a\\\\\\\\b'\"\n\n# === repr of bytes (Value::InternBytes) ===\nassert repr(b'') == \"b''\"\nassert repr(b'hello') == \"b'hello'\"\nassert repr(b'\\x00') == \"b'\\\\x00'\"\nassert repr(b'\\xff') == \"b'\\\\xff'\"\nassert repr(b\"it's\") == 'b\"it\\'s\"'\n\n# === repr of built-in functions (Value::Builtin) ===\nassert repr(len) == '<built-in function len>'\nassert repr(print) == '<built-in function print>'\nassert repr(repr) == '<built-in function repr>'\nassert repr(abs) == '<built-in function abs>'\nassert repr(min) == '<built-in function min>'\nassert repr(max) == '<built-in function max>'\nassert repr(sorted) == '<built-in function sorted>'\nassert repr(isinstance) == '<built-in function isinstance>'\nassert repr(hash) == '<built-in function hash>'\nassert repr(id) == '<built-in function id>'\nassert repr(bin) == '<built-in function bin>'\nassert repr(hex) == '<built-in function hex>'\nassert repr(oct) == '<built-in function oct>'\nassert repr(ord) == '<built-in function ord>'\nassert repr(chr) == '<built-in function chr>'\n\n# === repr of type objects (Value::Marker) ===\nassert repr(int) == \"<class 'int'>\"\nassert repr(str) == \"<class 'str'>\"\nassert repr(float) == \"<class 'float'>\"\nassert repr(list) == \"<class 'list'>\"\nassert repr(dict) == \"<class 'dict'>\"\nassert repr(tuple) == \"<class 'tuple'>\"\nassert repr(set) == \"<class 'set'>\"\nassert repr(bool) == \"<class 'bool'>\"\nassert repr(range) == \"<class 'range'>\"\nassert repr(bytes) == \"<class 'bytes'>\"\nassert repr(frozenset) == \"<class 'frozenset'>\"\n\n# === repr of lists (HeapData::List via Value::Ref) ===\nassert repr([]) == '[]'\nassert repr([1]) == '[1]'\nassert repr([1, 2, 3]) == '[1, 2, 3]'\nassert repr(['a', 'b']) == \"['a', 'b']\"\nassert repr([True, False]) == '[True, False]'\nassert repr([None]) == '[None]'\nassert repr([[1, 2], [3]]) == '[[1, 2], [3]]'\nassert repr([1, 'a', True, None]) == \"[1, 'a', True, None]\"\n\n# === repr of tuples (HeapData::Tuple via Value::Ref) ===\nassert repr(()) == '()'\nassert repr((1, 2)) == '(1, 2)'\nassert repr((1, 2, 3)) == '(1, 2, 3)'\nassert repr(('a', 'b')) == \"('a', 'b')\"\n\n# === repr of dicts (HeapData::Dict via Value::Ref) ===\nassert repr({}) == '{}'\nassert repr({1: 'a'}) == \"{1: 'a'}\"\nassert repr({1: 'a', 'b': 2}) == \"{1: 'a', 'b': 2}\"\nassert repr({'key': [1, 2]}) == \"{'key': [1, 2]}\"\nassert repr({'nested': {'a': 1}}) == \"{'nested': {'a': 1}}\"\n\n# === repr of sets (HeapData::Set via Value::Ref) ===\nassert repr(set()) == 'set()'\nassert repr({1}) == '{1}'\n\n# === repr of frozensets (HeapData::FrozenSet via Value::Ref) ===\nassert repr(frozenset()) == 'frozenset()'\n\n# === repr of ranges (HeapData::Range via Value::Ref) ===\nassert repr(range(10)) == 'range(0, 10)'\nassert repr(range(1, 10)) == 'range(1, 10)'\nassert repr(range(0, 10, 2)) == 'range(0, 10, 2)'\nassert repr(range(0)) == 'range(0, 0)'\nassert repr(range(-5, 5)) == 'range(-5, 5)'\n\n# === repr of slices (HeapData::Slice via Value::Ref) ===\nassert repr(slice(5)) == 'slice(None, 5, None)'\nassert repr(slice(1, 5)) == 'slice(1, 5, None)'\nassert repr(slice(1, 10, 2)) == 'slice(1, 10, 2)'\nassert repr(slice(None)) == 'slice(None, None, None)'\nassert repr(slice(None, None, -1)) == 'slice(None, None, -1)'\n\n# === repr of nested/mixed containers ===\nassert repr([1, 'hello', True, None, 2.5]) == \"[1, 'hello', True, None, 2.5]\"\nassert repr((1, [2, 3], {'a': 'b'})) == \"(1, [2, 3], {'a': 'b'})\"\nassert repr({'k': (1, 2)}) == \"{'k': (1, 2)}\"\nassert repr([range(3)]) == '[range(0, 3)]'\n\n# === repr preserves insertion order in dicts ===\nd = {}\nd['z'] = 1\nd['a'] = 2\nd['m'] = 3\nassert repr(d) == \"{'z': 1, 'a': 2, 'm': 3}\"\n\n# === repr escapes control characters numerically ===\nassert repr('\\x00') == \"'\\\\x00'\"\nassert repr('\\x01') == \"'\\\\x01'\"\nassert repr('\\x1b') == \"'\\\\x1b'\"\nassert repr('\\x7f') == \"'\\\\x7f'\"\nassert repr('\\x80') == \"'\\\\x80'\"\nassert repr('a\\x00b') == \"'a\\\\x00b'\"\nassert repr('\\x0b') == \"'\\\\x0b'\"\nassert repr('\\x0c') == \"'\\\\x0c'\"\n# the three short escapes are still preferred\nassert repr('\\t\\n\\r') == \"'\\\\t\\\\n\\\\r'\"\n# printable characters (including unicode) are left as-is\nassert repr('café 日本') == \"'café 日本'\"\n# non-printable unicode beyond the control range is escaped too (Cf/Zs/Co/...)\nassert repr('\\xa0') == \"'\\\\xa0'\"\nassert repr(' ') == \"'\\\\u2028'\"\nassert repr('\\xad') == \"'\\\\xad'\"\nassert repr('\\U000f4240') == \"'\\\\U000f4240'\"\nassert repr('　') == \"'\\\\u3000'\"\n\n# === repr vs str difference ===\nassert repr(42) == str(42)\nassert repr('hello') != str('hello')\nassert repr('hello') == \"'hello'\"\nassert str('hello') == 'hello'\n",
  'builtin__setattr.py': "# call-external\n# Test setattr() builtin function\n\nmut_point = make_mutable_point()\n\nsetattr(mut_point, 'x', 100)\nassert mut_point.x == 100\n\nsetattr(mut_point, 'y', 200)\nassert mut_point.y == 200\n\nsetattr(mut_point, 'z', 300)\nassert mut_point.z == 300\n\nsetattr(mut_point, 'name', 'test')\nassert mut_point.name == 'test'\n\nsetattr(mut_point, 'active', True)\nassert mut_point.active == True\n\nresult = setattr(mut_point, 'x', 999)\nassert result == None\n\n# setattr on any host instance mutates the local copy only\nother_point = make_point()\nsetattr(other_point, 'x', 10)\nassert other_point.x == 10\n\ntry:\n    setattr()\n    assert False, 'setattr() with no args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'setattr expected 3 arguments, got 0', str(e)\n\ntry:\n    setattr(mut_point)\n    assert False, 'setattr() with 1 arg should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'setattr expected 3 arguments, got 1', str(e)\n\ntry:\n    setattr(mut_point, 'x')\n    assert False, 'setattr() with 2 args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'setattr expected 3 arguments, got 2', str(e)\n\ntry:\n    setattr(mut_point, 'x', 10, 'extra')\n    assert False, 'setattr() with 4 args should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'setattr expected 3 arguments, got 4', str(e)\n\ntry:\n    setattr(mut_point, 123, 'value')\n    assert False, 'setattr() with non-string name should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"attribute name must be string, not 'int'\", str(e)\n\ntry:\n    setattr(mut_point, None, 'value')\n    assert False, 'setattr() with None name should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"attribute name must be string, not 'NoneType'\", str(e)\n\ntry:\n    setattr(42, 'x', 10)\n    assert False, 'setattr on int should raise AttributeError'\nexcept AttributeError as e:\n    assert str(e) == \"'int' object has no attribute 'x' and no __dict__ for setting new attributes\", str(e)\n\ntry:\n    setattr('hello', 'x', 10)\n    assert False, 'setattr on string should raise AttributeError'\nexcept AttributeError as e:\n    assert str(e) == \"'str' object has no attribute 'x' and no __dict__ for setting new attributes\", str(e)\n",
  'builtin__string_funcs.py': "# === ord() ===\n# Basic ord operations\nassert ord('a') == 97\nassert ord('A') == 65\nassert ord('0') == 48\nassert ord(' ') == 32\nassert ord('\\n') == 10\nassert ord('\\t') == 9\n\n# Unicode characters\nassert ord('\\u00e9') == 233\nassert ord('\\u4e2d') == 20013\nassert ord('\\U0001f600') == 128512\n\n# === chr() ===\n# Basic chr operations\nassert chr(97) == 'a'\nassert chr(65) == 'A'\nassert chr(48) == '0'\nassert chr(32) == ' '\nassert chr(10) == '\\n'\n\n# Unicode characters\nassert chr(233) == '\\u00e9'\nassert chr(20013) == '\\u4e2d'\nassert chr(128512) == '\\U0001f600'\n\n# Edge cases\nassert chr(0) == '\\x00'\nassert chr(0x10FFFF) != ''\n\n# Round-trip test\nassert chr(ord('x')) == 'x'\nassert ord(chr(1000)) == 1000\n\n# === bin() ===\n# Basic bin operations\nassert bin(0) == '0b0'\nassert bin(1) == '0b1'\nassert bin(2) == '0b10'\nassert bin(5) == '0b101'\nassert bin(255) == '0b11111111'\nassert bin(-5) == '-0b101'\nassert bin(True) == '0b1'\nassert bin(False) == '0b0'\nMIN_I64 = -9223372036854775807 - 1  # Smallest i64\nMIN_I64_BIN = '1' + '0' * 63\nMIN_I64_HEX = '8' + '0' * 15\nMIN_I64_OCT = '1' + '0' * 21\nassert bin(MIN_I64) == '-0b' + MIN_I64_BIN\n\n# === hex() ===\n# Basic hex operations\nassert hex(0) == '0x0'\nassert hex(15) == '0xf'\nassert hex(16) == '0x10'\nassert hex(255) == '0xff'\nassert hex(256) == '0x100'\nassert hex(-42) == '-0x2a'\nassert hex(True) == '0x1'\nassert hex(False) == '0x0'\nassert hex(MIN_I64) == '-0x' + MIN_I64_HEX\n\n# === oct() ===\n# Basic oct operations\nassert oct(0) == '0o0'\nassert oct(7) == '0o7'\nassert oct(8) == '0o10'\nassert oct(64) == '0o100'\nassert oct(-56) == '-0o70'\nassert oct(True) == '0o1'\nassert oct(False) == '0o0'\nassert oct(MIN_I64) == '-0o' + MIN_I64_OCT\n",
  'bytes__decode_invalid_utf8.py': "# Test that bytes.decode raises UnicodeDecodeError for invalid UTF-8\n# UnicodeDecodeError is a subclass of ValueError, so it should be caught by both\n\n# Test it raises UnicodeDecodeError\nraised_decode_error = False\ntry:\n    b'\\xff'.decode()\nexcept UnicodeDecodeError:\n    raised_decode_error = True\nassert raised_decode_error\n\n# Test it can be caught by ValueError (since UnicodeDecodeError is a subclass)\ncaught_by_value_error = False\ntry:\n    b'\\x80\\x81'.decode()\nexcept ValueError:\n    caught_by_value_error = True\nassert caught_by_value_error\n",
