  'dict__method_pop_missing_error.py': "d = {'a': 1}\nd.pop('missing')\n# Raise=KeyError('missing')\n",
  'dict__methods.py': "# === dict.clear() ===\nd = {'a': 1, 'b': 2}\nd.clear()\nassert d == {}\n\nd = {}\nd.clear()\nassert d == {}\n\n# === dict.copy() ===\nd = {'a': 1, 'b': 2}\ncopy = d.copy()\nassert copy == {'a': 1, 'b': 2}\nassert copy is not d\nd['c'] = 3\nassert 'c' not in copy\n\nd = {}\ncopy = d.copy()\nassert copy == {}\n\n# === dict.update() ===\nd = {'a': 1}\nd.update({'b': 2})\nassert d == {'a': 1, 'b': 2}\n\nd = {'a': 1}\nd.update({'a': 10})\nassert d == {'a': 10}\n\nd = {'a': 1}\nd.update()\nassert d == {'a': 1}\n\nd = {}\nd.update([('a', 1), ('b', 2)])\nassert d == {'a': 1, 'b': 2}\n\n# === dict.setdefault() ===\nd = {'a': 1}\nresult = d.setdefault('a', 10)\nassert result == 1\nassert d == {'a': 1}\n\nd = {'a': 1}\nresult = d.setdefault('b', 2)\nassert result == 2\nassert d == {'a': 1, 'b': 2}\n\nd = {'a': 1}\nresult = d.setdefault('b')\nassert result is None\nassert d == {'a': 1, 'b': None}\n\n# === dict.popitem() ===\nd = {'a': 1, 'b': 2}\nitem = d.popitem()\nassert item == ('b', 2)\nassert d == {'a': 1}\n\nd = {'x': 10}\nitem = d.popitem()\nassert item == ('x', 10)\nassert d == {}\n\n# === dict.fromkeys() ===\nd = dict.fromkeys(['a', 'b', 'c'])\nassert d == {'a': None, 'b': None, 'c': None}\n\nd = dict.fromkeys(['a', 'b'], 0)\nassert d == {'a': 0, 'b': 0}\n\nd = dict.fromkeys([])\nassert d == {}\n\nd = dict.fromkeys('abc')\nassert d == {'a': None, 'b': None, 'c': None}\n\nd = dict.fromkeys(range(3), 'x')\nassert d == {0: 'x', 1: 'x', 2: 'x'}\n\nd = dict.fromkeys((1, 2, 3), [])\nassert d[1] is d[2] and d[2] is d[3], 'fromkeys shares same value object for all keys'\n\n# Duplicate keys - later occurrence wins\nd = dict.fromkeys(['a', 'b', 'a'], 1)\nassert d == {'a': 1, 'b': 1}\nassert list(d.keys()) == ['a', 'b']\n\n# === dict.fromkeys() instance access ===\n# fromkeys is a classmethod but should also work on instances\nd = {}.fromkeys(['a', 'b'])\nassert d == {'a': None, 'b': None}\n\nd = {'x': 1}.fromkeys(['a', 'b'], 0)\nassert d == {'a': 0, 'b': 0}\n\n# === dict.update() with keyword arguments ===\nd = {'a': 1}\nd.update(b=2)\nassert d == {'a': 1, 'b': 2}\n\nd = {'a': 1}\nd.update(b=2, c=3)\nassert d == {'a': 1, 'b': 2, 'c': 3}\n\nd = {'a': 1}\nd.update(a=10)\nassert d == {'a': 10}\n\nd = {}\nd.update(a=1, b=2)\nassert d == {'a': 1, 'b': 2}\n\n# update with both positional dict and kwargs\nd = {'a': 1}\nd.update({'b': 2}, c=3)\nassert d == {'a': 1, 'b': 2, 'c': 3}\n\n# kwargs overwrite positional dict values\nd = {'a': 1}\nd.update({'b': 2}, b=20)\nassert d == {'a': 1, 'b': 20}\n\n# update with iterable and kwargs\nd = {}\nd.update([('a', 1)], b=2)\nassert d == {'a': 1, 'b': 2}\n\n# `**` unpacking with a runtime-built (non-interned) string key must still\n# reach **kwargs — only genuinely non-string keys are rejected.\nruntime_key = 'zzz' + 'qqq'\nd = dict(**{runtime_key: 1})\nassert d == {'zzzqqq': 1}\nd.update(**{runtime_key: 2})\nassert d == {'zzzqqq': 2}\n\n# === Error message for unknown classmethod ===\n# Error message should say 'dict' not 'type'\ntry:\n    dict.nonexistent()\n    assert False, 'should raise AttributeError'\nexcept AttributeError as e:\n    msg = str(e)\n    assert 'dict' in msg, f'error should mention dict, got: {e}'\n    assert 'nonexistent' in msg, f'error should mention method name, got: {e}'\n\n# === dict.update() sequence element error ===\n# Invalid sequence elements should raise ValueError\ntry:\n    d = {}\n    d.update([('a', 1), 'x', ('c', 3)])  # 'x' at index 1 is not a 2-tuple\n    assert False, 'should raise ValueError'\nexcept (ValueError, TypeError) as e:\n    msg = str(e)\n    # Error message should mention 'length' requirement\n    assert 'length' in msg.lower(), f'error should mention length, got: {e}'\n    # TODO: CPython includes element index (#N) in error message\n    # assert '#1' in msg, 'error should mention element index'\n",
  'dict__ops.py': "# === Dict literals ===\nassert {} == {}\nassert {'a': 1} == {'a': 1}\nassert {'a': 1, 'b': 2} == {'a': 1, 'b': 2}\nassert {1: 'a', 2: 'b'} == {1: 'a', 2: 'b'}\n\n# === Dict length ===\nassert len({}) == 0\nassert len({'a': 1, 'b': 2, 'c': 3}) == 3\n\n# === Dict equality ===\nassert ({'a': 1, 'b': 2} == {'b': 2, 'a': 1}) == True\nassert ({'a': 1} == {'a': 2}) == False\n\n# === Dict subscript get ===\nd = {'name': 'Alice', 'age': 30}\nassert d['name'] == 'Alice'\nassert d['age'] == 30\n\nd = {1: 'one', 2: 'two'}\nassert d[1] == 'one'\n\n# === Dict subscript set ===\nd = {'a': 1}\nd['b'] = 2\nassert d == {'a': 1, 'b': 2}\n\nd = {'a': 1}\nd['a'] = 99\nassert d == {'a': 99}\n\n# === Dict subscript augmented assignment ===\ntotals = {'photo': 1}\nrtype = 'photo'\nlikes = 2\ntotals[rtype] += likes\nassert totals == {'photo': 3}\n\ncalls = 0\n\n\ndef key():\n    global calls\n    calls += 1\n    return 'photo'\n\n\ntotals = {'photo': 10}\ntotals[key()] += 5\nassert totals == {'photo': 15}\nassert calls == 1\n\ncaptured_total = {'photo': 1}\ncaptured_likes = 2\n\n\ndef apply_captured_increment():\n    captured_total['photo'] += captured_likes\n\n\napply_captured_increment()\nassert captured_total == {'photo': 3}\n\nwalrus_key = None\nwalrus_total = {'photo': 10}\nwalrus_total[(walrus_key := 'photo')] += 4\nassert walrus_key == 'photo'\nassert walrus_total == {'photo': 14}\n\ntry:\n    missing = {}\n    missing['photo'] += 1\n    assert False, 'subscript += on a missing dict key should raise KeyError'\nexcept KeyError as e:\n    assert e.args == ('photo',)\n\ntry:\n    existing = {'photo': 'a'}\n    existing['photo'] += 1\n    assert False, 'subscript += with incompatible operand types should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('can only concatenate str (not \"int\") to str',)\n    assert existing == {'photo': 'a'}\n\n# === Dict.get() method ===\nd = {'a': 1, 'b': 2}\nassert d.get('a') == 1\nassert d.get('missing') is None\nassert d.get('missing', 'default') == 'default'\n\n# === Dict.pop() method ===\nd = {'a': 1, 'b': 2}\nassert d.pop('a') == 1\nassert d == {'b': 2}\n\nd = {'a': 1}\nassert d.pop('missing', 'default') == 'default'\n\n# === Dict with native immutable keys ===\nd = {(1, 2): 'tuple', b'key': 'bytes'}\nassert d[(1, 2)] == 'tuple'\nassert d[b'key'] == 'bytes'\n\n# Equal numeric types share hashes and address the same key.\nd = {1: 'number'}\nassert d[True] == 'number'\nassert d[1.0] == 'number'\n\n# === Dict repr ===\nassert repr({}) == '{}'\nassert repr({'a': 1}) == \"{'a': 1}\"\n\n# === Dict self-reference ===\nd = {}\nd['self'] = d\nassert d['self'] is d\n\nd = {}\nassert d.get('missing', d) is d\n\n# === Dict unpacking (PEP 448) ===\na = {'x': 1, 'y': 2}\nb = {'y': 99, 'z': 3}\nassert {**a} == {'x': 1, 'y': 2}\nassert {**a, **b} == {'x': 1, 'y': 99, 'z': 3}\nassert {**a, 'y': 0} == {'x': 1, 'y': 0}\nassert {'y': 0, **a} == {'y': 2, 'x': 1}\nassert {**a, 'z': 3} == {'x': 1, 'y': 2, 'z': 3}\nassert {**{}} == {}\nassert {**a, **b, 'w': 4} == {'x': 1, 'y': 99, 'z': 3, 'w': 4}\nassert list({**a, 'z': 3}.keys()) == ['x', 'y', 'z']\n\n# === Dict unpack TypeError for non-mapping heap ref ===\n# Unpacking a Ref that is NOT a dict (e.g. a list) should raise TypeError\ntry:\n    x = {**[1, 2, 3]}\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"'list' object is not a mapping\", f'wrong error: {e}'\n\n# === Duplicate literal keys: last value wins, replaced value is released ===\ndup = {'k': [1], 'k': [2]}\nassert dup == {'k': [2]}\nassert len(dup) == 1\n\n# === `in` / `not in` ===\n# `in` on a dict tests its keys, never its values.\nmembership = {'a': 1, 'b': 2}\nassert 'a' in membership\nassert 'z' not in membership\nassert 1 not in membership\n",
