  'dict__update_self.py': "d = {'x': 1}\nd.update(d)\nassert d == {'x': 1}\n",
  'dict__views.py': "# === Type identity and repr ===\nd = {'a': 1, 'b': 2}\n\nkeys = d.keys()\nitems = d.items()\nvalues = d.values()\n\nassert type(keys).__name__ == 'dict_keys'\nassert type(items).__name__ == 'dict_items'\nassert type(values).__name__ == 'dict_values'\n\nassert repr(keys) == \"dict_keys(['a', 'b'])\"\nassert repr(items) == \"dict_items([('a', 1), ('b', 2)])\"\nassert repr(values) == 'dict_values([1, 2])'\n\n# === len() and truthiness ===\nassert len(keys) == 2\nassert len(items) == 2\nassert len(values) == 2\nassert bool(keys) is True\nassert bool(items) is True\nassert bool(values) is True\nassert bool({}.keys()) is False\nassert bool({}.items()) is False\nassert bool({}.values()) is False\n\n# === Iteration order ===\nassert list(keys) == ['a', 'b']\nassert list(items) == [('a', 1), ('b', 2)]\nassert list(values) == [1, 2]\n\n# === Membership ===\nassert ('a' in keys) is True\nassert ('missing' in keys) is False\nassert (('a', 1) in items) is True\nassert (('a', 3) in items) is False\nassert (('a',) in items) is False\nassert (1 in values) is True\nassert (3 in values) is False\n\ntry:\n    ([1], 'x') in {1: 'x'}.items()\n    assert False, 'items membership should reject unhashable keys'\nexcept TypeError as e:\n    assert str(e) == \"cannot use 'list' as a dict key (unhashable type: 'list')\"\n\n# === Equality ===\nassert keys == keys\nassert items == items\nassert values == values\n\nassert keys == {'a', 'b'}\nassert {'b', 'a'} == keys\nassert keys == frozenset({'a', 'b'})\nassert frozenset({'a', 'b'}) == keys\nassert keys == {'b': 0, 'a': 9}.keys()\nassert keys != {'a'}\nassert keys != {'a', 'x'}\n\nassert items == {('a', 1), ('b', 2)}\nassert {('b', 2), ('a', 1)} == items\nassert items == frozenset({('a', 1), ('b', 2)})\nassert frozenset({('a', 1), ('b', 2)}) == items\nassert items == {'b': 2, 'a': 1}.items()\nassert items != {('a', 1)}\nassert items != {('a', 2), ('b', 2)}\nassert items != {('a', 1), ('x', 9)}\nassert ({'a': 1}.values() == {'a': 1}.values()) is False\n\n# === Live behavior after mutation ===\nlive = {'x': 10}\nlive_keys = live.keys()\nlive_items = live.items()\nlive_values = live.values()\nlive['y'] = 20\n\nassert list(live_keys) == ['x', 'y']\nassert list(live_items) == [('x', 10), ('y', 20)]\nassert list(live_values) == [10, 20]\nassert repr(live_keys) == \"dict_keys(['x', 'y'])\"\nassert len(live_values) == 2\n\n# === Dict mutation during iteration ===\nchanging = {'a': 1, 'b': 2}\nchanging_iter = iter(changing.keys())\nassert next(changing_iter) == 'a'\nchanging['c'] = 3\ntry:\n    next(changing_iter)\n    assert False, 'changing dict size during keys iteration should raise'\nexcept RuntimeError as e:\n    assert str(e) == 'dictionary changed size during iteration'\n\nchanging = {'a': 1, 'b': 2}\nchanging_iter = iter(changing.items())\nassert next(changing_iter) == ('a', 1)\nchanging['c'] = 3\ntry:\n    next(changing_iter)\n    assert False, 'changing dict size during items iteration should raise'\nexcept RuntimeError as e:\n    assert str(e) == 'dictionary changed size during iteration'\n\nchanging = {'a': 1, 'b': 2}\nchanging_iter = iter(changing.values())\nassert next(changing_iter) == 1\nchanging['c'] = 3\ntry:\n    next(changing_iter)\n    assert False, 'changing dict size during values iteration should raise'\nexcept RuntimeError as e:\n    assert str(e) == 'dictionary changed size during iteration'\n\n# Exhausted iterators remain exhausted after the dictionary changes size.\nexhausted_dict = {'a': 1}\nexhausted_iter = iter(exhausted_dict)\nassert list(exhausted_iter) == ['a']\nexhausted_dict['b'] = 2\nassert next(exhausted_iter, None) is None\n\n# === Unsupported operators do not materialize views ===\n# `dict_items` materialization hashes its pairs, so unsupported operators must\n# reject the operand types before encountering an unhashable value.\nunhashable_values = {'a': [1]}\n\ntry:\n    unhashable_values.items() + 1\n    assert False, 'dict_items should not support +'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for +: 'dict_items' and 'int'\", 'items + int names the operand types'\n\ntry:\n    unhashable_values.items() * 2\n    assert False, 'dict_items should not support *'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for *: 'dict_items' and 'int'\", 'items * int names the operand types'\n\ntry:\n    unhashable_values.items() << 1\n    assert False, 'dict_items should not support <<'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for <<: 'dict_items' and 'int'\", (\n        'items << int names the operand types'\n    )\n\ntry:\n    unhashable_values.items() >> 1\n    assert False, 'dict_items should not support >>'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for >>: 'dict_items' and 'int'\", (\n        'items >> int names the operand types'\n    )\n\ntry:\n    1 + unhashable_values.items()\n    assert False, 'int + dict_items should not be supported'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for +: 'int' and 'dict_items'\", 'reflected + names the operand types'\n\ntry:\n    2 * unhashable_values.items()\n    assert False, 'int * dict_items should not be supported'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for *: 'int' and 'dict_items'\", 'reflected * names the operand types'\n\ntry:\n    unhashable_values.items() - [1]\n    assert False, 'items difference over unhashable values should raise'\nexcept TypeError as e:\n    assert str(e) == \"cannot use 'tuple' as a set element (unhashable type: 'list')\", (\n        'supported items difference materializes the view'\n    )\n\n# Intersection checks the other iterable before hashing any live item values.\nassert unhashable_values.items() & [] == set()\nassert [] & unhashable_values.items() == set()\nfor expression in (lambda: unhashable_values.items() & 1, lambda: 1 & unhashable_values.items()):\n    try:\n        expression()\n        assert False, 'items intersection should reject non-iterables first'\n    except TypeError as e:\n        assert str(e) == \"'int' object is not iterable\"\n\n# The other set-like operators materialize the items view first.\nfor expression in (\n    lambda: unhashable_values.items() | 1,\n    lambda: unhashable_values.items() ^ 1,\n):\n    try:\n        expression()\n        assert False, 'items operation should reject unhashable values'\n    except TypeError as e:\n        assert str(e) == \"cannot use 'tuple' as a set element (unhashable type: 'list')\"\n\n# Reflected operations validate the left iterable before materializing the view.\nfor expression in (\n    lambda: 1 | unhashable_values.items(),\n    lambda: 1 ^ unhashable_values.items(),\n    lambda: 1 - unhashable_values.items(),\n):\n    try:\n        expression()\n        assert False, 'reflected items operation should reject a non-iterable left operand'\n    except TypeError as e:\n        assert str(e) == \"'int' object is not iterable\"\n\n# === dict_keys & iterable ===\nd = {'a': 1, 'b': 2, 'c': 3}\nassert d.keys() & {'b', 'c', 'x'} == {'b', 'c'}\nassert d.keys() & ('b', 'x', 'a') == {'a', 'b'}\nassert d.keys() & iter(['c', 'c', 'a']) == {'a', 'c'}\nassert type(d.keys() & {'a'}).__name__ == 'set'\n\ntry:\n    d.keys() & 1\n    assert False, 'keys intersection should reject non-iterables'\nexcept TypeError as e:\n    assert str(e) == \"'int' object is not iterable\"\n\n# === dict_keys set-like operators ===\nassert d.keys() | ('c', 'd') == {'a', 'b', 'c', 'd'}, 'keys view unions arbitrary iterables'\nassert ['c', 'd'] | d.keys() == {'a', 'b', 'c', 'd'}, 'keys reflected union accepts arbitrary iterables'\nassert d.keys() ^ ('b', 'd', 'e') == {'a', 'c', 'd', 'e'}, 'keys view symmetric difference works'\nassert ['b', 'd', 'e'] ^ d.keys() == {'a', 'c', 'd', 'e'}, (\n    'keys reflected symmetric difference accepts arbitrary iterables'\n)\nassert d.keys() - ('b', 'd') == {'a', 'c'}, 'keys view difference works'\nassert ['b', 'd'] - d.keys() == {'d'}, 'keys reflected difference preserves operand order'\nassert d.keys() & {'b': 0, 'z': 9}.keys() == {'b'}, 'keys view intersects other keys views'\nassert d.keys() | {'c': 0, 'd': 1}.keys() == {'a', 'b', 'c', 'd'}, 'keys view unions other keys views'\nassert d.keys().isdisjoint(['x', 'y']) is True, 'keys isdisjoint accepts arbitrary iterables'\nassert d.keys().isdisjoint(iter(['x', 'a'])) is False, 'keys isdisjoint consumes iterators'\n\n# === dict_items set-like operators ===\nitems_dict = {'a': 1, 'b': 2}\nassert items_dict.items() & [('a', 1), ('x', 9)] == {('a', 1)}, 'items view intersects iterables of pairs'\nassert [('a', 1), ('x', 9)] & items_dict.items() == {('a', 1)}, (\n    'items reflected intersection accepts iterables of pairs'\n)\nassert items_dict.items() | [('c', 3)] == {('a', 1), ('b', 2), ('c', 3)}, 'items view unions iterables of pairs'\nassert [('c', 3)] | items_dict.items() == {('a', 1), ('b', 2), ('c', 3)}, (\n    'items reflected union accepts iterables of pairs'\n)\nassert items_dict.items() ^ [('a', 1), ('c', 3)] == {('b', 2), ('c', 3)}, 'items view symmetric difference works'\nassert [('a', 1), ('c', 3)] ^ items_dict.items() == {('b', 2), ('c', 3)}, 'items reflected symmetric difference works'\nassert items_dict.items() - [('a', 1)] == {('b', 2)}, 'items view difference works'\nassert [('a', 1), ('c', 3)] - items_dict.items() == {('c', 3)}, 'items reflected difference preserves operand order'\nassert items_dict.items() & {'b': 2, 'x': 9}.items() == {('b', 2)}, 'items view intersects other items views'\nassert items_dict.items().isdisjoint([('x', 1)]) is True, 'items isdisjoint accepts arbitrary iterables'\nassert items_dict.items().isdisjoint(iter([('a', 1)])) is False, 'items isdisjoint consumes iterators'\n\n# === dict_values remains non-set-like ===\ntry:\n    {'a': 1}.values() & [1]\n    assert False, 'dict_values should not support set-like operators'\nexcept TypeError:\n    pass\n\ntry:\n    {'a': 1}.values().isdisjoint([1])\n    assert False, 'dict_values should not gain isdisjoint'\nexcept AttributeError:\n    pass\n\n# === Motivating milestone examples ===\nassert ['foo', 'bar'] | {}.keys() == {'foo', 'bar'}, 'list union empty keys view returns set of list items'\n\nme_map = {'me': 1, 'you': 2, 'merve': 3}\nmerve_set = {'merve', 'unknown'}\ncommon_ids = me_map.keys() & merve_set\nassert common_ids == {'merve'}\n\n# === `in` / `not in` on the views ===\nview_source = {'a': 1, 'b': 2}\nassert 'a' in view_source.keys()\nassert 'z' not in view_source.keys()\nassert 2 in view_source.values()\nassert 9 not in view_source.values()\n# An items probe must be a (key, value) pair; anything else is simply absent.\nassert ('a', 1) in view_source.items()\nassert ('a', 2) not in view_source.items()\nassert 'a' not in view_source.items()\n\n# The values view is a linear scan comparing by value.\nnested_view = {'a': [1, 2], 'b': (3, 4), 'c': 1}\nassert [1, 2] in nested_view.values()\nassert (3, 4) in nested_view.values()\nassert [1, 3] not in nested_view.values()\nassert 1.0 in nested_view.values()\nassert True in nested_view.values()\nassert None not in nested_view.values()\n# Duplicate values are found once each.\ndupe_view = {'a': 1, 'b': 1}\nassert 1 in dupe_view.values()\nassert 2 not in dupe_view.values()\n# The items view looks the key up, then compares the stored value.\nassert ('a', [1, 2]) in nested_view.items()\nassert ('a', [1, 3]) not in nested_view.items()\nassert ('z', [1, 2]) not in nested_view.items()\nassert ('c', True) in nested_view.items()\nassert ('c', 1.0) in nested_view.items()\n# Probes that are not a 2-item pair can never be members.\nassert ('a', [1, 2], 'extra') not in nested_view.items()\nassert ('a',) not in nested_view.items()\nassert ['a', [1, 2]] not in nested_view.items()\n# Keys view membership rejects an unhashable probe, as dict lookup does.\ntry:\n    [1] in nested_view.keys()\n    assert False, 'expected TypeError for an unhashable keys probe'\nexcept TypeError as exc:\n    assert str(exc) == \"cannot use 'list' as a dict key (unhashable type: 'list')\"\n",
  'edge__all.py': "# === Empty container lengths ===\nassert (len([]), len(()), len('')) == (0, 0, 0)\n\n# === Large concatenations ===\nlst = []\nfor i in range(100):\n    lst += [i]\nassert len(lst) == 100\n\ns = ''\nfor i in range(100):\n    s += 'x'\nassert len(s) == 100\n\n# === Self-concatenation ===\nlst = [1]\nlst += lst\nlst += lst\nassert lst == [1, 1, 1, 1]\n\n# === Mod comparison in loop ===\ncount = 0\nfor i in range(100):\n    if i % 7 == 0:\n        count += 1\nassert count == 15\n",
  'edge__float_int_mod.py': "7.5 % 2\n# Return=1.5\n",
  'edge__int_float_mod.py': "7 % 2.5\n# Return=2.0\n",
  'exc__args.py': "# === Exception .args attribute ===\ntry:\n    raise ValueError('test message')\nexcept ValueError as e:\n    assert e.args == ('test message',)\n    assert e.args[0] == 'test message'\n\ntry:\n    raise ValueError()\nexcept ValueError as e:\n    assert e.args == ()\n\ntry:\n    raise TypeError('type error')\nexcept TypeError as e:\n    assert e.args[0] == 'type error'\n",
  'exc__str.py': "try:\n    raise ValueError\nexcept ValueError as e:\n    assert str(e) == ''\n    assert repr(e) == 'ValueError()'\nelse:\n    raise AssertionError('should raise an error')\n\ntry:\n    raise ValueError()\nexcept ValueError as e:\n    assert str(e) == ''\n    assert repr(e) == 'ValueError()'\nelse:\n    raise AssertionError('should raise an error')\n",
  'execute_ok__all.py': "# === Basic arithmetic ===\nassert 1 + 1 == 2\nassert 'a' + 'b' == 'ab'\n\n# === Equality tests ===\nassert (1 == 1) == True\nassert (1 == 2) == False\nassert ('a' == 'a') == True\nassert ('a' == 'b') == False\nassert ([1, 2] == [1, 2]) == True\nassert ((1, 2) == (1, 2)) == True\nassert (b'hello' == b'hello') == True\n\n# === Boolean repr/str ===\nassert repr(True) == 'True'\nassert str(True) == 'True'\nassert repr(False) == 'False'\nassert str(False) == 'False'\n\n# === None repr/str ===\nassert repr(None) == 'None'\nassert str(None) == 'None'\n\n# === Ellipsis repr/str ===\nassert repr(...) == 'Ellipsis'\nassert str(...) == 'Ellipsis'\n\n# === List repr/str ===\nassert repr([1, 2]) == '[1, 2]'\nassert str([1, 2]) == '[1, 2]'\n\n# === Discard expression result ===\na = 1\n[1, 2, 3]  # this list is created and discarded\nassert a == 1\n\n# === Shared list append ===\na = [1]\nb = a\nb.append(2)\nassert len(a) == 2\n\n# === For loop string append ===\nv = ''\nfor i in range(1000):\n    if i % 13 == 0:\n        v = v + 'x'\nassert len(v) == 77\n\nv = ''\nfor i in range(1000):\n    if i % 13 == 0:\n        v += 'x'\nassert len(v) == 77\n",
  'execute_raise__error_instance_str.py': "raise ValueError('testing')\n# Raise=ValueError('testing')\n",
  'execute_raise__error_no_args.py': "raise TypeError()\n# Raise=TypeError()\n",
  'execute_raise__error_string_arg.py': "raise TypeError('hello')\n# Raise=TypeError('hello')\n",
  'execute_raise__error_string_arg_quotes.py': "raise TypeError(\"hello 'there'\")\n# Raise=TypeError(\"hello 'there'\")\n",
  'execute_raise__error_type.py': "raise TypeError\n# Raise=TypeError()\n",
  'execute_raise__raise_instance_via_var.py': "# raise exception instance stored in a variable\na = ValueError('instance error')\nraise a\n# Raise=ValueError('instance error')\n",
  'execute_raise__raise_list.py': "raise []\n# Raise=TypeError('exceptions must derive from BaseException')\n",
  'execute_raise__raise_number.py': "raise 1 + 2\n# Raise=TypeError('exceptions must derive from BaseException')\n",
  'execute_raise__raise_type_call_via_var.py': "# raise exception type called via variable\na = ValueError\nraise a('error message')\n# Raise=ValueError('error message')\n",
  'execute_raise__raise_type_direct.py': "# raise exception type directly\nraise ValueError\n# Raise=ValueError()\n",
  'execute_raise__raise_type_via_var.py': "# raise exception type stored in a variable\na = ValueError\nraise a\n# Raise=ValueError()\n",
  'ext_call__arg_side_effect_bug.py': "# call-external\n# BUG: Side effects in arguments are duplicated when external call suspends\n#\n# When an external call is in one argument position and there's a side effect\n# in another argument position, the side effect may be executed multiple times\n# because argument evaluation is repeated during resumption.\n\ncall_count = 0\n\n\ndef side_effect(val):\n    global call_count\n    call_count += 1\n    return val\n\n\n# Side effect before external call in args\n# Expected: side_effect runs once, result is 10 + 3 = 13\ncall_count = 0\nresult = add_ints(side_effect(10), add_ints(1, 2))\nassert result == 13\nassert call_count == 1\n",
  'ext_call__augmented.py': "# call-external\n# External calls in augmented assignment expressions\n\n# += with external call\nx = 10\nx += add_ints(5, 5)\nassert x == 20\n\n# -= with external call\nx = 100\nx -= add_ints(20, 30)\nassert x == 50\n\n# *= with external call\nx = 5\nx *= add_ints(2, 1)\nassert x == 15\n",
  'ext_call__augmented_refcount_bug.py': "# call-external\n# BUG: Reference counting bug with string augmented assignment and external calls\n\n# String += with external call causes reference counting error\ns = 'hello'\ns += concat_strings(' ', 'world')\nassert s == 'hello world'\n",
  'ext_call__bare_raise_after_resume.py': "# call-external\n# Test bare raise after external call resumption in except handler\n# This tests that current_exception is properly restored after resuming\n# Note: bare raise after resumption only works when exception is bound (as e)\n\ncaught_reraised = False\ntry:\n    try:\n        raise ValueError('original error')\n    except ValueError as e:\n        # Make an external call, which will cause a suspend/resume\n        x = add_ints(1, 2)\n        # After resuming, bare raise should still work (exception restored from binding)\n        raise\nexcept ValueError as outer_e:\n    caught_reraised = repr(outer_e) == \"ValueError('original error')\"\n\nassert caught_reraised\n\n# === Nested handler bare raise after resumption ===\nouter_nested_reraise = False\ntry:\n    try:\n        raise ValueError('outer error')\n    except ValueError:\n        try:\n            raise KeyError('inner error')\n        except KeyError:\n            _ = add_ints(1, 2)\n        raise\nexcept ValueError as reraised:\n    outer_nested_reraise = repr(reraised) == \"ValueError('outer error')\"\n\nassert outer_nested_reraise\n",
  'ext_call__basic.py': "# call-external\n# === Basic external function tests ===\n\n# Simple calls\na = add_ints(10, 20)\nassert a == 30\n\nb = add_ints(-5, 15)\nassert b == 10\n\ns = concat_strings('hello', ' world')\nassert s == 'hello world'\n\nx = return_value(42)\nassert x == 42\n\ny = return_value('test')\nassert y == 'test'\n\n# === Assignment with external calls ===\nresult = add_ints(100, 200)\nassert result == 300\n\nname = concat_strings('foo', 'bar')\nassert name == 'foobar'\n\n# === Nested calls ===\nnested = add_ints(1, add_ints(2, 3))\nassert nested == 6\n\nnested2 = add_ints(add_ints(1, 2), 3)\nassert nested2 == 6\n\nnested3 = add_ints(add_ints(1, 2), add_ints(3, 4))\nassert nested3 == 10\n\ndeep = add_ints(add_ints(add_ints(1, 2), 3), 4)\nassert deep == 10\n\n# === Chained operations ===\nchained = add_ints(1, 2) + add_ints(3, 4)\nassert chained == 10\n\nchained2 = add_ints(10, 20) - add_ints(5, 10)\nassert chained2 == 15\n\nchained3 = add_ints(2, 3) * add_ints(4, 5)\nassert chained3 == 45\n\nstr_chain = concat_strings('a', 'b') + concat_strings('c', 'd')\nassert str_chain == 'abcd'\n\n# === External calls in assert statements ===\nassert add_ints(5, 5) == 10\nassert return_value(True)\nassert concat_strings('x', 'y') == 'xy'\nassert add_ints(1, add_ints(2, 3)) == 6\n\n# === Mixed with builtins ===\nlength = len(concat_strings('hello', 'world'))\nassert length == 10\n\nitems = [add_ints(1, 2), add_ints(3, 4)]\nassert items[0] == 3\nassert items[1] == 7\n\n# === Multiple external calls in single expression ===\n\n# Two ext calls added together\nsum_result = add_ints(1, 2) + add_ints(3, 4)\nassert sum_result == 10\n\n# Three ext calls in one expression\ntriple = add_ints(1, 1) + add_ints(2, 2) + add_ints(3, 3)\nassert triple == 12\n\n# Ext calls in multiplication\nmul_result = add_ints(2, 3) * add_ints(1, 1)\nassert mul_result == 10\n\n# Ext calls in subtraction\nsub_result = add_ints(10, 5) - add_ints(3, 2)\nassert sub_result == 10\n\n# Complex expression with multiple ext calls\ncomplex_expr = (add_ints(1, 2) + add_ints(3, 4)) * add_ints(0, 2)\nassert complex_expr == 20\n\n# String concatenation with multiple ext calls\nstr_result = concat_strings(return_value('a'), return_value('b')) + concat_strings('c', 'd')\nassert str_result == 'abcd'\n\n# Comparison with multiple ext calls\ncmp_result = add_ints(5, 5) == add_ints(3, 7)\nassert cmp_result == True\n\n# Nested ext calls in expression\nnested_expr = add_ints(add_ints(1, 2), add_ints(3, 4))\nassert nested_expr == 10\n",
  'ext_call__boolean.py': "# call-external\n# External calls in boolean short-circuit expressions\n\n# === Basic boolean operations ===\nresult = return_value(True) and return_value(42)\nassert result == 42\n\nresult = return_value(False) and return_value(42)\nassert result == False\n\nresult = return_value(0) or return_value(42)\nassert result == 42\n\nresult = return_value(99) or return_value(42)\nassert result == 99\n\n\n# === Chained boolean with external calls ===\nresult = return_value(True) and return_value(True) and return_value(42)\nassert result == 42\n\nresult = return_value(True) and return_value(False) and return_value(42)\nassert result == False\n\nresult = return_value(0) or return_value(0) or return_value(42)\nassert result == 42\n\nresult = return_value(0) or return_value(99) or return_value(42)\nassert result == 99\n\n\n# === Mixed and/or ===\nresult = return_value(True) and return_value(0) or return_value(42)\nassert result == 42\n\nresult = return_value(0) or return_value(True) and return_value(42)\nassert result == 42\n",
  'ext_call__boolean_side_effect_hang.py': "# call-external\n# BUG: This test hangs (infinite loop) - external calls in boolean expressions\n# with side effects cause incorrect behavior.\n\ncall_count = 0\n\n\ndef side_effect(val):\n    global call_count\n    call_count += 1\n    return val\n\n\n# This specific pattern causes a hang in Monty\nresult = return_value(True) and return_value(side_effect(42))\nassert result == 42\nassert call_count == 1\n",
  'ext_call__closure_bug.py': "# call-external\n# BUG: External calls in closures cannot access captured variables\n# When an external call is inside a closure, it fails to access free variables\n# Error: \"cannot access free variable 'x' where it is not associated with a value\"\n\n\ndef make_adder(x):\n    def adder(y):\n        return add_ints(x, y)\n\n    return adder\n\n\nadd5 = make_adder(5)\nresult = add5(10)\nassert result == 15\n",
  'ext_call__comparison.py': "# call-external\n# External calls in comparison expressions\n\n# External call on left side of comparison\nresult = add_ints(1, 2) == 3\nassert result == True\n\n# External call on right side\nresult = 3 == add_ints(1, 2)\nassert result == True\n\n# Both sides external calls\nresult = add_ints(1, 2) == add_ints(2, 1)\nassert result == True\n\n# Less than\nresult = add_ints(1, 1) < add_ints(2, 2)\nassert result == True\n\n# Greater than\nresult = add_ints(5, 5) > add_ints(2, 2)\nassert result == True\n\n# Not equal\nresult = add_ints(1, 2) != add_ints(3, 4)\nassert result == True\n",
  'ext_call__deep_call_stack.py': "# call-external\n# External function calls in deep call stacks (function calling function).\n# Tests that the outer function receives the return value correctly when\n# the inner function makes an external call.\n\n\ndef depth1(n):\n    return add_ints(n, 1)\n\n\ndef depth2(n):\n    return depth1(n) + 10\n\n\nresult = depth2(5)\n# depth2(5) should be: depth1(5) + 10 = 6 + 10 = 16\n\nassert result == 16, f'ext call through 2 levels of functions {result=}'\n",
  'ext_call__elif.py': "# call-external\n# === External calls in elif conditions ===\n\n# External call in elif condition - true\nresult1 = 0\nif add_ints(1, 1) == 3:\n    result1 = 1\nelif add_ints(2, 2) == 4:\n    result1 = 2\nelse:\n    result1 = 3\nassert result1 == 2, f'elif condition with ext call should be evaluated, {result1=}'\n\n# External call in elif condition - falls through to else\nresult2 = 0\nif add_ints(1, 1) == 3:\n    result2 = 1\nelif add_ints(2, 2) == 5:\n    result2 = 2\nelse:\n    result2 = 3\nassert result2 == 3\n\n# Multiple elif with external calls\nresult3 = 0\nif add_ints(1, 1) == 10:\n    result3 = 1\nelif add_ints(2, 2) == 10:\n    result3 = 2\nelif add_ints(3, 3) == 6:\n    result3 = 3\nelif add_ints(4, 4) == 10:\n    result3 = 4\nelse:\n    result3 = 5\nassert result3 == 3\n\n# === External calls in elif bodies ===\n\n# Ext call in elif body\nval1 = 0\nif False:\n    val1 = 1\nelif True:\n    val1 = add_ints(10, 20)\nelse:\n    val1 = 3\nassert val1 == 30\n\n# Ext call in else body after elif chain\nval2 = 0\nif False:\n    val2 = 1\nelif False:\n    val2 = 2\nelse:\n    val2 = add_ints(15, 25)\nassert val2 == 40\n\n# Multiple ext calls in elif body\nval3 = 0\nif False:\n    val3 = 1\nelif True:\n    a = add_ints(5, 5)\n    b = add_ints(10, 10)\n    val3 = add_ints(a, b)\nelse:\n    val3 = 3\nassert val3 == 30\n\n# === Nested ext calls ===\n\n# Nested ext calls in elif condition\nresult4 = 0\nif False:\n    result4 = 1\nelif add_ints(add_ints(1, 2), add_ints(3, 4)) == 10:\n    result4 = 2\nelse:\n    result4 = 3\nassert result4 == 2\n\n# === Short-circuit with ext calls ===\n\n# Ext call should not be evaluated if earlier condition is true\ncall_count = 0\n\n\ndef counting_add(a, b):\n    global call_count\n    call_count = call_count + 1\n    return a + b\n\n\n# This uses a regular function, not ext call, to verify short-circuit\n# but the ext calls in bodies still test suspension\nx = 0\nif True:\n    x = add_ints(1, 1)\nelif False:\n    x = add_ints(2, 2)\nassert x == 2\n\n# === Ext call in both condition and body ===\n\nresult5 = 0\nif add_ints(1, 1) == 3:\n    result5 = add_ints(100, 100)\nelif add_ints(2, 2) == 4:\n    result5 = add_ints(50, 50)\nelse:\n    result5 = add_ints(25, 25)\nassert result5 == 100\n\n# === Ext call in if body when condition is true ===\n\nif_body_result = 0\nif add_ints(5, 5) == 10:\n    if_body_result = add_ints(100, 200)\nelif add_ints(1, 1) == 2:\n    if_body_result = add_ints(10, 20)\nelse:\n    if_body_result = add_ints(1, 2)\nassert if_body_result == 300\n\n# === Ext calls returning values used as conditions ===\n\n# return_value returns its argument, so we can use it to test boolean coercion\ncond_result = 0\nif return_value(0):\n    cond_result = 1\nelif return_value(1):\n    cond_result = 2\nelse:\n    cond_result = 3\nassert cond_result == 2\n\n# === Ext calls with string concatenation ===\n\nstr_result = ''\nif add_ints(1, 1) == 3:\n    str_result = concat_strings('a', 'b')\nelif add_ints(2, 2) == 4:\n    str_result = concat_strings('hello', ' world')\nelse:\n    str_result = concat_strings('x', 'y')\nassert str_result == 'hello world'\n\n# === Multiple conditions with ext calls in same expression ===\n\nmulti_cond = 0\nif add_ints(1, 1) > 5:\n    multi_cond = 1\nelif add_ints(2, 2) < add_ints(3, 3):\n    multi_cond = 2\nelse:\n    multi_cond = 3\nassert multi_cond == 2\n\n# === Ext call in all three branches ===\n\nall_branches = 0\nval = add_ints(5, 5)\nif val < 5:\n    all_branches = add_ints(1, 0)\nelif val < 15:\n    all_branches = add_ints(2, 0)\nelse:\n    all_branches = add_ints(3, 0)\nassert all_branches == 2\n",
  'ext_call__exc.py': "# call-external\n# External call in raise statement\nraise ValueError(return_value('foobar'))\n# Raise=ValueError('foobar')\n",
  'ext_call__exc_deep_stack.py': "# call-external\ndef level4():\n    x = 1\n    raise_error('RuntimeError', 'deep error')\n\n\ndef level3():\n    level4()\n\n\ndef level2():\n    level3()\n\n\ndef level1():\n    level2()\n\n\nlevel1()\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"ext_call__exc_deep_stack.py\", line 19, in <module>\n    level1()\n    ~~~~~~~~\n  File \"ext_call__exc_deep_stack.py\", line 16, in level1\n    level2()\n    ~~~~~~~~\n  File \"ext_call__exc_deep_stack.py\", line 12, in level2\n    level3()\n    ~~~~~~~~\n  File \"ext_call__exc_deep_stack.py\", line 8, in level3\n    level4()\n    ~~~~~~~~\n  File \"ext_call__exc_deep_stack.py\", line 4, in level4\n    raise_error('RuntimeError', 'deep error')\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nRuntimeError: deep error\n\"\"\"\n",
  'ext_call__exc_in_function.py': "# call-external\ndef wrapper():\n    raise_error('ValueError', 'from external')\n\n\nwrapper()\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"ext_call__exc_in_function.py\", line 6, in <module>\n    wrapper()\n    ~~~~~~~~~\n  File \"ext_call__exc_in_function.py\", line 3, in wrapper\n    raise_error('ValueError', 'from external')\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nValueError: from external\n\"\"\"\n",
  'ext_call__exc_nested_functions.py': "# call-external\ndef inner():\n    raise_error('TypeError', 'nested error')\n\n\ndef middle():\n    inner()\n\n\ndef outer():\n    middle()\n\n\nouter()\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"ext_call__exc_nested_functions.py\", line 14, in <module>\n    outer()\n    ~~~~~~~\n  File \"ext_call__exc_nested_functions.py\", line 11, in outer\n    middle()\n    ~~~~~~~~\n  File \"ext_call__exc_nested_functions.py\", line 7, in middle\n    inner()\n    ~~~~~~~\n  File \"ext_call__exc_nested_functions.py\", line 3, in inner\n    raise_error('TypeError', 'nested error')\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nTypeError: nested error\n\"\"\"\n",
  'ext_call__ext_exc.py': "# call-external\n# === External function exceptions ===\n# Tests for exceptions raised by external functions\n\n# === Basic exception propagation ===\n\n# External function raising ValueError\ncaught_value_error = False\ntry:\n    result = raise_error('ValueError', 'test error')\n    assert False, 'should not reach here'\nexcept ValueError:\n    caught_value_error = True\nassert caught_value_error\n\n# External function raising TypeError\ncaught_type_error = False\ntry:\n    result = raise_error('TypeError', 'type error message')\n    assert False, 'should not reach here'\nexcept TypeError:\n    caught_type_error = True\nassert caught_type_error\n\n# External function raising KeyError\ncaught_key_error = False\ntry:\n    result = raise_error('KeyError', 'missing key')\n    assert False, 'should not reach here'\nexcept KeyError:\n    caught_key_error = True\nassert caught_key_error\n\n# External function raising RuntimeError\ncaught_runtime_error = False\ntry:\n    result = raise_error('RuntimeError', 'runtime error')\n    assert False, 'should not reach here'\nexcept RuntimeError:\n    caught_runtime_error = True\nassert caught_runtime_error\n\n# === Exception not caught by wrong handler ===\n\n# ValueError not caught by TypeError handler\ncaught_outer = False\ntry:\n    try:\n        raise_error('ValueError', 'inner error')\n    except TypeError:\n        assert False, 'TypeError should not catch ValueError'\nexcept ValueError:\n    caught_outer = True\nassert caught_outer\n\n# === Exception in expression with multiple ext calls ===\n\n# First ext call raises, second should not be called\ntry:\n    x = raise_error('ValueError', 'first') + add_ints(1, 2)\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# === External exception in try body with finally ===\n\nfinally_ran = False\ntry:\n    raise_error('ValueError', 'in try')\nexcept ValueError:\n    pass  # Caught\nfinally:\n    finally_ran = True\nassert finally_ran\n\n# External exception propagating through finally\nouter_caught = False\nfinally_ran2 = False\ntry:\n    try:\n        raise_error('KeyError', 'will propagate')\n    except ValueError:\n        assert False, 'ValueError should not catch KeyError'\n    finally:\n        finally_ran2 = True\nexcept KeyError:\n    outer_caught = True\nassert finally_ran2\nassert outer_caught\n\n# === Mix of normal returns and exceptions ===\n\n# Normal return, then exception\nvalue1 = add_ints(10, 20)\nassert value1 == 30\ntry:\n    raise_error('ValueError', 'after success')\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# Exception, then normal return (after catching)\ncaught_exc = False\ntry:\n    raise_error('TypeError', 'will be caught')\nexcept TypeError:\n    caught_exc = True\nvalue2 = add_ints(5, 5)\nassert caught_exc\nassert value2 == 10\n\n# === Exception in except handler from external function ===\n\nouter_catch = False\ntry:\n    try:\n        raise ValueError('inner')\n    except ValueError:\n        raise_error('TypeError', 'from handler')\nexcept TypeError:\n    outer_catch = True\nassert outer_catch\n\n# === Exception in else block from external function ===\n\nelse_exc_caught = False\ntry:\n    try:\n        pass  # No exception\n    except:\n        assert False, 'should not reach except'\n    else:\n        raise_error('RuntimeError', 'from else')\nexcept RuntimeError:\n    else_exc_caught = True\nassert else_exc_caught\n\n# === Exception in finally block ===\n\n# Note: exception in finally replaces any pending exception\nfinally_exc_caught = False\ntry:\n    try:\n        pass\n    finally:\n        raise_error('ValueError', 'from finally')\nexcept ValueError:\n    finally_exc_caught = True\nassert finally_exc_caught\n\n# === Nested try blocks with external exceptions ===\n\ninner_handled = False\nouter_handled = False\nfinally_count = 0\ntry:\n    try:\n        raise_error('ValueError', 'inner error')\n    except ValueError:\n        inner_handled = True\n        raise_error('TypeError', 'from inner handler')\n    finally:\n        finally_count += 1\nexcept TypeError:\n    outer_handled = True\nfinally:\n    finally_count += 1\n\nassert inner_handled\nassert outer_handled\nassert finally_count == 2\n\n# === external call in return position: handlers still catch on resume ===\n# Regression: `try: return raise_error(...)` used to leave the resume point\n# outside the protected region, bypassing except/finally.\n\n\ndef return_ext_except():\n    try:\n        return raise_error('ValueError', 'return boom')\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_ext_except() == 'caught return boom'\n\nreturn_finally_events = []\n\n\ndef return_ext_finally():\n    try:\n        return raise_error('ValueError', 'through finally')\n    finally:\n        return_finally_events.append('finally')\n\n\ntry:\n    return_ext_finally()\nexcept ValueError as e:\n    return_finally_events.append(str(e))\nassert return_finally_events == ['finally', 'through finally']\n",
  'ext_call__for.py': "# call-external\n# === External calls in for loops ===\n\n# Ext call in loop body\ntotal = 0\nfor i in range(3):\n    total = add_ints(total, 1)\nassert total == 3, f'ext call accumulator in loop, {total=}'\n\n# Ext call with loop variable\nsum_val = 0\nfor i in range(4):\n    sum_val = add_ints(sum_val, i)\nassert sum_val == 6\n\n# Multiple ext calls per iteration\nresult = 0\nfor i in range(3):\n    result = add_ints(result, add_ints(i, i))\nassert result == 6\n\n# Building list with ext calls\nitems = []\nfor i in range(3):\n    items.append(add_ints(i, 10))\nassert items[0] == 10\nassert items[1] == 11\nassert items[2] == 12\n\n# Chained ext calls in loop\nacc = 0\nfor i in range(3):\n    acc = add_ints(acc, 1) + add_ints(0, 1)\nassert acc == 6\n\n# Nested loops with ext calls\nmatrix_sum = 0\nfor i in range(2):\n    for j in range(2):\n        matrix_sum = add_ints(matrix_sum, add_ints(i, j))\nassert matrix_sum == 4\n\n# === More nested loop edge cases ===\n\n# Nested loops building a result list\nresults = []\nfor i in range(2):\n    for j in range(2):\n        results.append(concat_strings(return_value(str(i)), return_value(str(j))))\nassert results[0] == '00'\nassert results[1] == '01'\nassert results[2] == '10'\nassert results[3] == '11'\n\n# If inside for loop with external call condition\nfiltered = []\nfor i in range(3):\n    if return_value(i) == i:\n        filtered.append(i)\nassert filtered == [0, 1, 2]\n\n# If inside for loop - some iterations match\nresults2 = []\nfor i in range(4):\n    # Only append even numbers (using modulo check with add_ints)\n    if add_ints(i, 0) % 2 == 0:\n        results2.append(return_value(i))\nassert results2 == [0, 2]\n\n# Nested for with different ranges\nouter_sum = 0\nfor i in range(2):\n    inner_sum = 0\n    for j in range(3):\n        inner_sum = add_ints(inner_sum, add_ints(i, j))\n    outer_sum = add_ints(outer_sum, inner_sum)\n# i=0: (0+0)+(0+1)+(0+2) = 0+1+2 = 3\n# i=1: (1+0)+(1+1)+(1+2) = 1+2+3 = 6\n# total = 3 + 6 = 9\nassert outer_sum == 9\n\n# Three levels of nested loops\ncount = 0\nfor i in range(2):\n    for j in range(2):\n        for k in range(2):\n            count = add_ints(count, 1)\nassert count == 8\n\n# multiple ext calls in iterable\n\next_ints = []\nfor i in add_ints(1, 1), add_ints(2, 2), add_ints(3, 3):\n    ext_ints.append(i)\nassert ext_ints == [2, 4, 6]\n\n# ext call iterable, get_list() returns [1, 2, 3]\ntotal = 0\nfor x in get_list():\n    total = add_ints(total, x)\nassert total == 6\n\n# string iteration with ext call in body\nchars = []\nfor c in 'abc':\n    chars.append(return_value(c))\nassert chars == ['a', 'b', 'c'], f'string iteration with ext call: {chars}'\n\n# unicode string iteration with ext call in body\n# Tests decr() handling of multi-byte UTF-8 characters (1-4 bytes each)\nunicode_chars = []\nfor c in 'aé中😀b':  # a (1 byte), e-acute (2), chinese (3), emoji (4), b (1)\n    unicode_chars.append(return_value(c))\nassert unicode_chars == ['a', 'é', '中', '😀', 'b'], f'unicode iteration: {unicode_chars}'\n",
  'ext_call__fstring.py': "# call-external\n# External calls in f-strings\n\ns = f'result is {add_ints(10, 20)}'\nassert s == 'result is 30'\n\ns = f'a={add_ints(1, 2)}, b={add_ints(3, 4)}'\nassert s == 'a=3, b=7'\n\n# Nested external call in f-string\ns = f'nested={add_ints(add_ints(1, 2), 3)}'\nassert s == 'nested=6'\n",
  'ext_call__if.py': "# call-external\n# === External calls in if/else expressions ===\n\n# Ternary expression with ext call in condition\nresult = 'yes' if add_ints(1, 1) == 2 else 'no'\nassert result == 'yes'\n\nresult2 = 'yes' if add_ints(1, 1) == 3 else 'no'\nassert result2 == 'no'\n\n# Ext call in true branch\nval = add_ints(10, 20) if True else 0\nassert val == 30\n\n# Ext call in false branch\nval2 = 0 if False else add_ints(5, 5)\nassert val2 == 10\n\n# Ext calls in both branches\nval3 = add_ints(1, 2) if True else add_ints(3, 4)\nassert val3 == 3\n\nval4 = add_ints(1, 2) if False else add_ints(3, 4)\nassert val4 == 7\n\n# === If statements with external calls ===\n\n# Ext call in if condition\nx = 0\nif add_ints(1, 1) == 2:\n    x = 100\nassert x == 100\n\ny = 0\nif add_ints(1, 1) == 3:\n    y = 100\nassert y == 0\n\n# Ext call in if body\nz = 0\nif True:\n    z = add_ints(50, 50)\nassert z == 100\n\n# Ext call in else body\nw = 0\nif False:\n    w = 1\nelse:\n    w = add_ints(25, 75)\nassert w == 100\n\n# Nested ext calls in condition\nnested = 0\nif add_ints(add_ints(1, 2), add_ints(3, 4)) == 10:\n    nested = 1\nassert nested == 1\n\n# Chained conditions with ext calls\nresult3 = 0\nif add_ints(1, 1) == 2 and add_ints(2, 2) == 4:\n    result3 = 1\nassert result3 == 1\n\nresult4 = 0\nif add_ints(1, 1) == 3 or add_ints(2, 2) == 4:\n    result4 = 1\nassert result4 == 1\n\n# Comparison with ext call results\ncmp = add_ints(10, 5) > add_ints(5, 5)\nassert cmp == True\n\n# === Nested if statements with external calls ===\n\n# Nested if with ext calls in both conditions (both true)\nresult = 'none'\nif return_value(1) == 1:\n    if return_value(2) == 2:\n        result = 'inner'\n    else:\n        result = 'outer_only'\nelse:\n    result = 'failed'\nassert result == 'inner'\n\n# Nested if - outer true, inner false\nresult2 = 'none'\nif return_value(1) == 1:\n    if return_value(2) == 999:\n        result2 = 'inner'\n    else:\n        result2 = 'outer_only'\nelse:\n    result2 = 'failed'\nassert result2 == 'outer_only'\n\n# Nested if - outer false\nresult3 = 'none'\nif return_value(1) == 999:\n    if return_value(2) == 2:\n        result3 = 'inner'\n    else:\n        result3 = 'outer_only'\nelse:\n    result3 = 'xxx'\nassert result3 == 'xxx'\n\n# Triple nested if - all true\nresult4 = 0\nif return_value(1) == 1:\n    if return_value(2) == 2:\n        if return_value(3) == 3:\n            result4 = 123\nassert result4 == 123\n\n# If condition with multiple ext calls (addition)\nresult5 = 0\nif add_ints(1, 2) + add_ints(3, 4) == 10:\n    result5 = 1\nassert result5 == 1\n\n# For loop inside if with external condition\ntotal = 0\nif return_value(1) == 1:\n    for i in range(3):\n        total = add_ints(total, return_value(i))\nassert total == 3\n\n# For loop inside if - condition false\ntotal2 = 0\nif return_value(1) == 999:\n    for i in range(3):\n        total2 = add_ints(total2, i)\nassert total2 == 0\n",
  'ext_call__if_condition.py': "# call-external\n# External calls in if conditions\n\n\ndef check_positive():\n    if add_ints(1, 2) > 0:\n        return 'positive'\n    return 'not positive'\n\n\nresult = check_positive()\nassert result == 'positive'\n\n\ndef check_with_else():\n    if add_ints(-5, 3) > 0:\n        return 'positive'\n    else:\n        return 'negative or zero'\n\n\nresult = check_with_else()\nassert result == 'negative or zero'\n\n\ndef check_elif():\n    val = add_ints(5, 5)\n    if val > 15:\n        return 'big'\n    elif val > 5:\n        return 'medium'\n    else:\n        return 'small'\n\n\nresult = check_elif()\nassert result == 'medium'\n",
  'ext_call__in_closure.py': "# call-external\n# External function calls inside closures (nested functions with captured variables).\n\n\ndef outer_with_nested():\n    x = 10\n\n    def inner():\n        return add_ints(x, 5)\n\n    return inner()\n\n\nassert outer_with_nested() == 15\n\n\n# An external call (which suspends the frame) inside a closure capturing a\n# variable *two* levels up — exercises suspend/resume of frames holding a\n# transitively threaded cell.\ndef outer_two_levels():\n    x = 100\n\n    def mid():\n        def inner():\n            return add_ints(x, 7)\n\n        return inner()\n\n    return mid()\n\n\nassert outer_two_levels() == 107\n",
  'ext_call__in_function.py': "# call-external\n# === External function calls inside user-defined functions ===\n\n# Basic function calling external function\ndef add_wrapper(a, b):\n    return add_ints(a, b)\n\n\nresult = add_wrapper(10, 20)\nassert result == 30\n\n\n# Function with multiple external calls (sequential)\ndef multi_ext():\n    x = add_ints(1, 2)\n    y = add_ints(3, 4)\n    return add_ints(x, y)\n\n\nassert multi_ext() == 10\n\n\n# External call in function with local variable usage\ndef with_locals():\n    x = 100\n    y = add_ints(x, 50)\n    z = y * 2\n    return z\n\n\nassert with_locals() == 300\n\n\n# Function returning external call result\ndef get_sum(a, b, c):\n    temp = add_ints(a, b)\n    return add_ints(temp, c)\n\n\nassert get_sum(1, 2, 3) == 6\n",
  'ext_call__in_function_simple.py': "# call-external\ndef foo():\n    return add_ints(1, 2)\n\n\nresult = foo()\nassert result == 3\n",
  'ext_call__literals.py': "# call-external\n# External calls in list and dict literals\n\n# External call in list literal\nlst = [add_ints(1, 2), add_ints(3, 4)]\nassert lst[0] == 3\nassert lst[1] == 7\n\n# External call in tuple literal\ntup = (add_ints(1, 1), add_ints(2, 2))\nassert tup[0] == 2\nassert tup[1] == 4\n\n# External call in dict value\nd = {'a': add_ints(5, 5), 'b': add_ints(10, 10)}\nassert d['a'] == 10\nassert d['b'] == 20\n",
  'ext_call__multi_in_func.py': "# call-external\n# Multiple external calls within user-defined functions\n\n\ndef compute_sum():\n    a = add_ints(1, 2)\n    b = add_ints(3, 4)\n    c = add_ints(5, 6)\n    return a + b + c\n\n\nresult = compute_sum()\nassert result == 21\n\n\ndef compute_nested():\n    return add_ints(add_ints(1, 2), add_ints(3, 4))\n\n\nresult = compute_nested()\nassert result == 10\n\n\ndef outer():\n    def inner():\n        return add_ints(10, 20)\n\n    return inner() + add_ints(1, 2)\n\n\nresult = outer()\nassert result == 33\n",
  'ext_call__name_lookup.py': "# call-external\n# Tests for NameLookup resolution with various value types.\n# Verifies that the host can inject non-function values (constants)\n# into the sandbox namespace via the NameLookup mechanism.\n\n# === Integer constant ===\nassert CONST_INT == 42, f'CONST_INT should be 42, got {CONST_INT}'\nassert CONST_INT + 8 == 50\nassert type(CONST_INT) == int, f'CONST_INT type should be int, got {type(CONST_INT)}'\n\n# === String constant ===\nassert CONST_STR == 'hello', f'CONST_STR should be hello, got {CONST_STR}'\nassert CONST_STR + ' world' == 'hello world'\nassert len(CONST_STR) == 5, f'CONST_STR length should be 5, got {len(CONST_STR)}'\nassert type(CONST_STR) == str, f'CONST_STR type should be str, got {type(CONST_STR)}'\n\n# === Float constant ===\nassert CONST_FLOAT == 3.14, f'CONST_FLOAT should be 3.14, got {CONST_FLOAT}'\nassert CONST_FLOAT + 0.86 == 4.0\nassert type(CONST_FLOAT) == float, f'CONST_FLOAT type should be float, got {type(CONST_FLOAT)}'\n\n# === Boolean constant ===\nassert CONST_BOOL == True, f'CONST_BOOL should be True, got {CONST_BOOL}'\nassert CONST_BOOL and True, 'CONST_BOOL in boolean expression'\nassert type(CONST_BOOL) == bool, f'CONST_BOOL type should be bool, got {type(CONST_BOOL)}'\n\n# === List constant ===\nassert CONST_LIST == [1, 2, 3], f'CONST_LIST should be [1, 2, 3], got {CONST_LIST}'\nassert len(CONST_LIST) == 3, f'CONST_LIST length should be 3, got {len(CONST_LIST)}'\nassert CONST_LIST[0] == 1\nassert CONST_LIST[-1] == 3\nassert type(CONST_LIST) == list, f'CONST_LIST type should be list, got {type(CONST_LIST)}'\n\n# === None constant ===\nassert CONST_NONE is None, f'CONST_NONE should be None, got {CONST_NONE}'\nassert type(CONST_NONE) == type(None), f'CONST_NONE type should be NoneType, got {type(CONST_NONE)}'\n\n# === Caching: same constant used twice should work ===\nx = CONST_INT\ny = CONST_INT\nassert x == y == 42, 'cached CONST_INT should be consistent'\n\n# === Mixed: constants and external functions in the same code ===\nresult = add_ints(CONST_INT, 8)\nassert result == 50, f'add_ints(CONST_INT, 8) should be 50, got {result}'\n\nstr_result = concat_strings(CONST_STR, ' world')\nassert str_result == 'hello world', f'concat with CONST_STR should be hello world, got {str_result}'\n\n# === Constants used in control flow ===\nif CONST_BOOL:\n    flag = 'yes'\nelse:\n    flag = 'no'\nassert flag == 'yes', f'CONST_BOOL in if should take true branch, got {flag}'\n\n# === Constants used in loops ===\ntotal = 0\nfor item in CONST_LIST:\n    total = total + item\nassert total == 6, f'sum of CONST_LIST should be 6, got {total}'\n\n\n# === Constants in function scope ===\ndef use_constant():\n    return CONST_INT * 2\n\n\nassert use_constant() == 84, f'CONST_INT in function should be 84, got {use_constant()}'\n",
  'ext_call__name_lookup_undefined.py': "# call-external\n# When NameLookup returns Undefined for an unknown name, NameError is raised.\ntotally_unknown_name\n# Raise=NameError(\"name 'totally_unknown_name' is not defined\")\n",
  'ext_call__nested_calls.py': "# call-external\n# External calls in nested call expressions\n\n# Nested external calls - inner first\nresult = add_ints(add_ints(1, 2), 3)\nassert result == 6\n\n# Triple nested\nresult = add_ints(add_ints(add_ints(1, 1), 2), 3)\nassert result == 7\n\n# Two separate nested calls\nresult = add_ints(add_ints(1, 2), add_ints(3, 4))\nassert result == 10\n",
  'ext_call__recursion_bug.py': "# call-external\n# BUG: External calls in recursive functions produce wrong results\n# Recursion with external calls doesn't compute the correct value\n\n\ndef sum_with_ext(n):\n    if n <= 0:\n        return 0\n    return add_ints(n, sum_with_ext(n - 1))\n\n\n# sum_with_ext(3) should compute:\n#   add_ints(3, sum_with_ext(2))\n#   add_ints(3, add_ints(2, sum_with_ext(1)))\n#   add_ints(3, add_ints(2, add_ints(1, sum_with_ext(0))))\n#   add_ints(3, add_ints(2, add_ints(1, 0)))\n#   = 3 + 2 + 1 = 6\nresult = sum_with_ext(3)\nassert result == 6\n",
  'ext_call__return.py': "# call-external\n# External calls in return statements\n\n\ndef direct_return():\n    return add_ints(10, 20)\n\n\nresult = direct_return()\nassert result == 30\n\n\ndef return_with_expression():\n    return add_ints(1, 2) + add_ints(3, 4)\n\n\nresult = return_with_expression()\nassert result == 10\n\n\ndef conditional_return():\n    if return_value(True):\n        return add_ints(100, 200)\n    return add_ints(1, 1)\n\n\nresult = conditional_return()\nassert result == 300\n",
  'ext_call__side_effects.py': "# call-external\ndef log(msg):\n    print(msg)\n    return 1\n\n\ndef inner(x):\n    print('Inner called')\n    val = add_ints(x, 1)  # External call\n    print('Inner resumed')\n    return val\n\n\ndef outer():\n    print('Outer calling inner')\n    # If side effects are duplicated, we'll see \"Evaluating arg\" twice\n    res = inner(log('Evaluating arg'))\n    print('Outer returned')\n    return res\n\n\nprint('Starting')\nres = outer()\nprint(f'Result: {res}')\nassert res == 2\n",
  'ext_call__subscript.py': "# call-external\n# External calls in subscript operations\n\n# External call as subscript index\nitems = [10, 20, 30]\nresult = items[add_ints(0, 1)]\nassert result == 20\n",
  'ext_call__ternary.py': "# call-external\n# External calls in ternary expressions (if/else expressions)\n\n# External call in true branch\nresult = add_ints(1, 2) if True else add_ints(10, 20)\nassert result == 3\n\n# External call in false branch\nresult = add_ints(1, 2) if False else add_ints(10, 20)\nassert result == 30\n\n# External call in condition\nresult = 'yes' if return_value(True) else 'no'\nassert result == 'yes'\n\nresult = 'yes' if return_value(False) else 'no'\nassert result == 'no'\n\n# External calls in both branches\nresult = add_ints(1, 2) if return_value(True) else add_ints(10, 20)\nassert result == 3\n\nresult = add_ints(1, 2) if return_value(False) else add_ints(10, 20)\nassert result == 30\n\n# Nested ternary with external calls\nresult = add_ints(1, 1) if return_value(True) else (add_ints(2, 2) if return_value(False) else add_ints(3, 3))\nassert result == 2\n",
  'ext_call__try.py': "# call-external\n# === External calls in try blocks ===\n\n# Basic external call in try body\nresult = None\ntry:\n    result = add_ints(10, 20)\nexcept:\n    result = -1\nassert result == 30\n\n# Multiple external calls in try body\ntry:\n    a = add_ints(1, 2)\n    b = add_ints(3, 4)\n    c = add_ints(a, b)\nexcept:\n    c = -1\nassert c == 10\n\n# Nested external calls in try body\ntry:\n    nested = add_ints(add_ints(1, 2), add_ints(3, 4))\nexcept:\n    nested = -1\nassert nested == 10\n\n# === External calls in except blocks ===\n\n# External call in except handler\nhandler_result = None\ntry:\n    raise ValueError('error')\nexcept ValueError:\n    handler_result = add_ints(100, 200)\nassert handler_result == 300\n\n# Multiple external calls in except handler\ntry:\n    raise TypeError('error')\nexcept TypeError:\n    x = add_ints(5, 5)\n    y = add_ints(10, 10)\n    handler_sum = add_ints(x, y)\nassert handler_sum == 30\n\n# External call with exception variable\nexc_with_ext = None\ntry:\n    raise ValueError('test')\nexcept ValueError as e:\n    prefix = concat_strings('caught: ', repr(e))\n    exc_with_ext = prefix\nassert exc_with_ext == \"caught: ValueError('test')\"\n\n# === External calls in else blocks ===\n\n# External call in else block\nelse_result = None\ntry:\n    x = 1  # No exception\nexcept:\n    else_result = -1\nelse:\n    else_result = add_ints(50, 50)\nassert else_result == 100\n\n# Multiple external calls in else block\ntry:\n    pass\nexcept:\n    else_multi = -1\nelse:\n    p = add_ints(1, 2)\n    q = add_ints(3, 4)\n    else_multi = add_ints(p, q)\nassert else_multi == 10\n\n# === External calls in finally blocks ===\n\n# External call in finally block\nfinally_result = None\ntry:\n    x = 1\nfinally:\n    finally_result = add_ints(25, 75)\nassert finally_result == 100\n\n# Finally with external call after exception caught\nfinally_after_exc = None\ntry:\n    raise ValueError('error')\nexcept ValueError:\n    pass\nfinally:\n    finally_after_exc = add_ints(1, 99)\nassert finally_after_exc == 100\n\n# Multiple external calls in finally\ntry:\n    pass\nfinally:\n    f1 = add_ints(10, 20)\n    f2 = add_ints(30, 40)\n    finally_multi = add_ints(f1, f2)\nassert finally_multi == 100\n\n# === External calls across multiple phases ===\n\n# External calls in try, except, and finally\nall_phases = []\ntry:\n    all_phases.append(add_ints(1, 0))  # 1\n    raise ValueError('error')\nexcept ValueError:\n    all_phases.append(add_ints(2, 0))  # 2\nfinally:\n    all_phases.append(add_ints(3, 0))  # 3\nassert all_phases == [1, 2, 3]\n\n# External calls in try, else, and finally (no exception)\nno_exc_phases = []\ntry:\n    no_exc_phases.append(add_ints(10, 0))  # 10\nexcept:\n    no_exc_phases.append(-1)\nelse:\n    no_exc_phases.append(add_ints(20, 0))  # 20\nfinally:\n    no_exc_phases.append(add_ints(30, 0))  # 30\nassert no_exc_phases == [10, 20, 30]\n\n# === External calls in nested try blocks ===\n\n# Nested try with external calls at each level\nouter_val = None\ninner_val = None\ntry:\n    outer_val = add_ints(100, 0)\n    try:\n        inner_val = add_ints(200, 0)\n        raise ValueError('inner')\n    except ValueError:\n        inner_val = add_ints(inner_val, 50)\nexcept:\n    outer_val = -1\nassert outer_val == 100\nassert inner_val == 250\n\n# === External calls in exception type expression ===\n# (Exception type is evaluated at handler matching time)\n\n# External call producing value used after try\npost_try = None\ntry:\n    pre = add_ints(5, 5)\nexcept:\n    pre = -1\npost_try = add_ints(pre, 10)\nassert post_try == 20\n\n# === External call in finally with unhandled exception ===\n# Finally should still run even when exception propagates\nfinally_with_propagate = None\ntry:\n    try:\n        finally_with_propagate = add_ints(0, 0)  # Initialize\n        raise KeyError('unhandled')\n    except ValueError:\n        pass  # Won't catch KeyError\n    finally:\n        finally_with_propagate = add_ints(42, 0)  # Should still run\nexcept KeyError:\n    pass  # Catch propagated exception\nassert finally_with_propagate == 42\n\n# === External call in except handler that then raises ===\nhandler_before_raise = None\ntry:\n    try:\n        raise ValueError('original')\n    except ValueError:\n        handler_before_raise = add_ints(10, 0)  # External call before raising\n        raise TypeError('from handler')\nexcept TypeError:\n    pass\nassert handler_before_raise == 10\n\n# === External call in else block that then raises ===\nelse_before_raise = None\ntry:\n    try:\n        pass  # No exception\n    except:\n        pass\n    else:\n        else_before_raise = add_ints(20, 0)  # External call before raising\n        raise ValueError('from else')\nexcept ValueError:\n    pass\nassert else_before_raise == 20\n\n# === External call preserves state across try/except ===\nstate_before = add_ints(1000, 0)\nstate_after = None\ntry:\n    state_after = add_ints(state_before, 1)\n    raise ValueError('test')\nexcept ValueError:\n    state_after = add_ints(state_after, 10)\nfinally:\n    state_after = add_ints(state_after, 100)\nassert state_after == 1111\n\n# === Multiple except handlers with external calls ===\nwhich_handler = None\ntry:\n    raise TypeError('test')\nexcept ValueError:\n    which_handler = add_ints(1, 0)\nexcept TypeError:\n    which_handler = add_ints(2, 0)\nexcept KeyError:\n    which_handler = add_ints(3, 0)\nassert which_handler == 2\n\n# === External call in finally with pending exception (after handler raises) ===\nfinally_after_handler_raise = None\ntry:\n    try:\n        raise ValueError('original')\n    except ValueError:\n        finally_after_handler_raise = add_ints(10, 0)  # External call before raising\n        raise TypeError('from handler')\n    finally:\n        # This external call should work even though there's a pending exception\n        finally_after_handler_raise = add_ints(finally_after_handler_raise, 5)\nexcept TypeError:\n    pass\nassert finally_after_handler_raise == 15\n\n# === External call in finally with pending exception (no matching handler) ===\nfinally_with_pending_exc = None\ntry:\n    try:\n        finally_with_pending_exc = add_ints(0, 0)\n        raise KeyError('no handler')\n    except ValueError:\n        pass  # Won't catch KeyError\n    finally:\n        # This external call should work even though KeyError is pending\n        finally_with_pending_exc = add_ints(100, 0)\nexcept KeyError:\n    pass  # Catch it here\nassert finally_with_pending_exc == 100\n\n# === External call in finally with return (uses simple values) ===\n# Note: External calls in user-defined functions are not supported,\n# so we test pending return with built-in operations only\nfinally_return_result = None\ntry:\n    finally_return_result = 'in_try'\nfinally:\n    pass  # finally runs but doesn't override\nassert finally_return_result == 'in_try'\n\n# === Multiple external calls in finally with pending exception ===\nmulti_finally = None\ntry:\n    try:\n        raise ValueError('test')\n    except TypeError:\n        pass  # Won't match\n    finally:\n        a = add_ints(1, 2)\n        b = add_ints(3, 4)\n        multi_finally = add_ints(a, b)\nexcept ValueError:\n    pass\nassert multi_finally == 10\n",
  'ext_call__try_simple.py': "# call-external\n# Test external call with exception variable\n\nexc_with_ext = None\ntry:\n    raise ValueError('test')\nexcept ValueError as e:\n    prefix = concat_strings('caught: ', repr(e))\n    exc_with_ext = prefix\nassert exc_with_ext == \"caught: ValueError('test')\"\n",
  'ext_call__unary.py': "# call-external\n# External calls in unary expressions\n\n# Negation of external call result\nresult = -add_ints(3, 4)\nassert result == -7\n\n# Not of external call\nresult = not return_value(False)\nassert result == True\n\nresult = not return_value(True)\nassert result == False\n",
  'float__mod.py': "# === float modulo: result takes the divisor's sign ===\nassert 7.5 % 2 == 1.5\nassert -7.0 % 3.0 == 2.0\nassert 7.0 % -3.0 == -2.0\nassert -7.0 % -3.0 == -1.0\nassert -7 % 3.0 == 2.0\nassert -7.0 % 3 == 2.0\nassert str(-6.0 % 3.0) == '0.0'\nassert str(6.0 % -3.0) == '-0.0'\n\n# === infinite divisor ===\nassert 5.0 % float('inf') == 5.0\nassert -5.0 % float('inf') == float('inf')\nassert 5.0 % -float('inf') == -float('inf')\n\n# === `%` agrees with divmod's remainder ===\nassert divmod(-7.0, 3.0)[1] == -7.0 % 3.0\nassert divmod(7.0, -3.0)[1] == 7.0 % -3.0\n\n# === `%` inside a comparison ===\nassert (-7.0 % 3.0 == 2) is True\nassert (7.0 % -3.0 == -2) is True\nassert (5.0 % 3.0 == 2) is True\n\n# === unsupported operands ===\ntry:\n    [1] % 2\n    assert False, 'expected TypeError from %'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for %: 'list' and 'int'\"\n\n# === zero divisor raises for every numeric combination ===\nfor a, b in [(5.0, 0.0), (5.0, 0), (5, 0.0), (5, 0)]:\n    try:\n        a % b\n        assert False, 'expected ZeroDivisionError from %'\n    except ZeroDivisionError as e:\n        assert str(e) == 'division by zero'\n",
  'frozenset__ops.py': "# === Construction ===\nfs = frozenset()\nassert len(fs) == 0\nassert fs == frozenset()\n\nfs = frozenset([1, 2, 3])\nassert len(fs) == 3\n\n# === Copy ===\nfs = frozenset([1, 2, 3])\nfs2 = fs.copy()\nassert fs == fs2\n\n# === Union ===\nfs1 = frozenset([1, 2])\nfs2 = frozenset([2, 3])\nu = fs1.union(fs2)\nassert len(u) == 3\n\n# === Intersection ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([2, 3, 4])\ni = fs1.intersection(fs2)\nassert len(i) == 2\n\n# === Difference ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([2, 3, 4])\nd = fs1.difference(fs2)\nassert len(d) == 1\n\n# === Symmetric Difference ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([2, 3, 4])\nsd = fs1.symmetric_difference(fs2)\nassert len(sd) == 2\n\n# === Binary operators ===\nfs = frozenset([1, 2])\nother_fs = frozenset([2, 3])\ns = {2, 3}\n\nassert fs & other_fs == frozenset([2])\nassert fs | other_fs == frozenset([1, 2, 3])\nassert fs ^ other_fs == frozenset([1, 3])\nassert fs - other_fs == frozenset([1])\n\nassert fs & s == frozenset([2])\nassert fs | s == frozenset([1, 2, 3])\nassert fs ^ s == frozenset([1, 3])\nassert fs - s == frozenset([1])\n\nkeys = {'a': 1, 'b': 2}.keys()\nitems = {'a': 1, 'b': 2}.items()\nassert frozenset({'a'}) & keys == frozenset({'a'})\nassert frozenset({'a'}) | keys == frozenset({'a', 'b'})\nassert frozenset({('a', 1)}) ^ items == frozenset({('b', 2)})\nassert frozenset({('a', 1), ('b', 2)}) - items == frozenset()\n\nassert type(fs | s).__name__ == 'frozenset'\n\ntry:\n    fs & [1, 2]\n    assert False, 'frozenset operators reject non-set rhs'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for &: 'frozenset' and 'list'\"\n\n# === Issubset ===\nfs1 = frozenset([1, 2])\nfs2 = frozenset([1, 2, 3])\nassert fs1.issubset(fs2) is True\nassert fs2.issubset(fs1) is False\n\n# === Issuperset ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([1, 2])\nassert fs1.issuperset(fs2) is True\nassert fs2.issuperset(fs1) is False\n\n# === Isdisjoint ===\nfs1 = frozenset([1, 2])\nfs2 = frozenset([3, 4])\nfs3 = frozenset([2, 3])\nassert fs1.isdisjoint(fs2) is True\nassert fs1.isdisjoint(fs3) is False\n\n# === Bool ===\nassert bool(frozenset()) == False\nassert bool(frozenset([1])) == True\n\n# === repr ===\nassert repr(frozenset()) == 'frozenset()'\n\n# === Hashing ===\nfs = frozenset([1, 2, 3])\nh = hash(fs)\nassert isinstance(h, int)\n\n# Same elements should have same hash\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([3, 2, 1])  # Different order\nassert hash(fs1) == hash(fs2)\n\n# === As dict key ===\nd = {}\nfs = frozenset([1, 2])\nd[fs] = 'value'\nassert d[fs] == 'value'\nassert d[frozenset([2, 1])] == 'value'\n\n# === Construction from various iterables ===\nfs = frozenset('abc')\nassert len(fs) == 3\nassert 'a' in fs and 'b' in fs and 'c' in fs, 'frozenset from string elements'\n\nfs = frozenset((1, 2, 3))\nassert fs == frozenset({1, 2, 3})\n\nfs = frozenset(range(5))\nassert fs == frozenset({0, 1, 2, 3, 4})\n\nfs = frozenset({1, 2, 3})\nassert len(fs) == 3\n\n# === Containment (in / not in) ===\nfs = frozenset({1, 2, 3})\nassert 1 in fs\nassert 4 not in fs\nassert 'x' not in frozenset({'a', 'b'})\n\n# === Iteration ===\nresult = []\nfor x in frozenset({1, 2, 3}):\n    result.append(x)\nassert len(result) == 3\nassert set(result) == {1, 2, 3}\n\nresult = []\nfor x in frozenset():\n    result.append(x)\nassert result == []\n\n# === Inequality (!=) ===\nassert frozenset({1, 2}) != frozenset({1, 3})\nassert not (frozenset({1, 2}) != frozenset({1, 2})), 'frozenset ne same'\n\n# === Methods accepting iterables ===\nassert frozenset({1, 2}).union([3, 4]) == frozenset({1, 2, 3, 4})\nassert frozenset({1, 2, 3}).intersection([2, 3, 4]) == frozenset({2, 3})\nassert frozenset({1, 2, 3}).difference([2]) == frozenset({1, 3})\nassert frozenset({1, 2}).symmetric_difference([2, 3]) == frozenset({1, 3})\nassert frozenset({1}).union(range(3)) == frozenset({0, 1, 2})\nassert frozenset({1}).union((2, 3)) == frozenset({1, 2, 3})\n\n# === issubset/issuperset/isdisjoint with non-set iterables ===\nfs = frozenset({1, 2, 3})\nassert fs.issubset(range(10))\nassert fs.issuperset([1, 2])\nassert fs.isdisjoint([4, 5, 6])\nassert not fs.isdisjoint([3, 4]), 'not isdisjoint with list'\n\n# === Different hashes for different frozensets ===\nfs1 = frozenset({1, 2})\nfs2 = frozenset({3, 4})\n# Not guaranteed to be different, but very likely\n# Instead just verify they're integers and stable\nassert hash(fs1) == hash(frozenset({2, 1}))\nassert hash(frozenset()) == hash(frozenset())\n\n# === Frozenset as set element ===\ns = {frozenset({1, 2}), frozenset({3, 4})}\nassert len(s) == 2\nassert frozenset({1, 2}) in s\n# Duplicate frozenset should dedup\ns2 = {frozenset({1}), frozenset({1})}\nassert len(s2) == 1\n\n# === set <-> frozenset cross-type equality (compare by members) ===\nassert frozenset({1, 2, 3}) == {1, 2, 3}\nassert {1, 2, 3} == frozenset({1, 2, 3})\nassert frozenset({1, 2}) != {1, 2, 3}\nassert {1, 2, 3} != frozenset({1, 2})\nassert frozenset() == set()\nassert set() == frozenset()\nassert {1: 'a', 2: 'b'}.keys() == frozenset({1, 2})\n",
  'fstring__all.py': "# === Basic f-strings ===\nassert f'hello' == 'hello'\nassert f'' == ''\n\n# === Simple interpolation ===\nx = 'world'\nassert f'hello {x}' == 'hello world'\n\n# multiple interpolations\na = 1\nb = 2\nassert f'{a} + {b} = {a + b}' == '1 + 2 = 3'\n\n# expression in f-string\nassert f'{1 + 2 + 3}' == '6'\n\n# === Value types ===\n# list value\nx = [1, 2, 3]\nassert f'list: {x}' == 'list: [1, 2, 3]'\n\n# bool value\nx = True\nassert f'value: {x}' == 'value: True'\n\n# int value\nassert f'{42}' == '42'\n\n# float value\nassert f'{3.14}' == '3.14'\n\n# None value\nassert f'{None}' == 'None'\n\n# === Conversion flags (!s, !r, !a) ===\n# conversion !s (str)\nassert f'{42!s}' == '42'\n\n# conversion !r (repr)\nassert f'{\"hello\"!r}' == \"'hello'\"\n\n# conversion !r on int (should be same as str for int)\nassert f'{42!r}' == '42'\n\n# conversion !r on list\nassert f'{[1, 2]!r}' == '[1, 2]'\n\n# conversion !s on string (no quotes)\nassert f'{\"hello\"!s}' == 'hello'\n\n# conversion !a (ascii) - escapes non-ASCII characters\nassert f'{\"café\"!a}' == \"'caf\\\\xe9'\"\nassert f'{\"hello\"!a}' == \"'hello'\"\nassert f'{\"日本\"!a}' == \"'\\\\u65e5\\\\u672c'\"\n\n# === String padding and alignment ===\n# format spec: width (left-aligned by default for strings)\nassert f'{\"hi\":10}' == 'hi        '\n\n# format spec: left align\nassert f'{\"hi\":<10}' == 'hi        '\n\n# format spec: right align\nassert f'{\"hi\":>10}' == '        hi'\n\n# format spec: center align\nassert f'{\"hi\":^10}' == '    hi    '\n\n# center align with odd padding\nassert f'{\"zip\":^6}' == ' zip  '\n\n# format spec: fill character\nassert f'{\"hi\":*>10}' == '********hi'\nassert f'{\"hi\":_<10}' == 'hi________'\nassert f'{\"hi\":*^10}' == '****hi****'\n\n# string truncation with precision\nassert f'{\"xylophone\":.5}' == 'xylop'\nassert f'{\"xylophone\":10.5}' == 'xylop     '\n\n# === Integer formatting ===\n# basic integer\nassert f'{42}' == '42'\n\n# integer with :d type\nassert f'{42:d}' == '42'\n\n# integer padding\nassert f'{42:4d}' == '  42'\nassert f'{42:04d}' == '0042'\n\n# integer with sign\nassert f'{42:+d}' == '+42'\nassert f'{42: d}' == ' 42'\nassert f'{-42:+d}' == '-42'\nassert f'{-42: d}' == '-42'\n\n# sign-aware padding\nassert f'{-23:=5d}' == '-  23'\n\n# i64::MIN: formatting must not overflow when taking abs of the minimum int\nassert f'{-9223372036854775808:d}' == '-9223372036854775808'\nassert f'{-9223372036854775808:+d}' == '-9223372036854775808'\nassert f'{-9223372036854775808:=22d}' == '-  9223372036854775808'\n\n# integer fill character with alignment\nassert f'{42:*>10d}' == '********42'\nassert f'{42:*<10d}' == '42********'\nassert f'{42:*^10d}' == '****42****'\n\n# === Integer non-decimal bases ===\n# binary\nassert f'{10:b}' == '1010'\nassert f'{-10:b}' == '-1010'\nassert f'{0:b}' == '0'\n\n# octal\nassert f'{8:o}' == '10'\nassert f'{-8:o}' == '-10'\n\n# hexadecimal (lower and upper)\nassert f'{255:x}' == 'ff'\nassert f'{-255:x}' == '-ff'\nassert f'{255:X}' == 'FF'\n\n# Uppercase `X` uppercases only the hex digits and the `0x` prefix (`0X`), NOT an\n# alphabetic fill char — the fill must stay as written.\nassert f'{180:a>8X}' == 'aaaaaaB4'\nassert f'{0xABC:f>8X}' == 'fffffABC'\nassert f'{255:#X}' == '0XFF'\nassert f'{255:b>#8X}' == 'bbbb0XFF'\n# Same rules for big integers (LongInt path).\nassert f'{2**70:a>25X}' == 'aaaaaaa400000000000000000'\nassert f'{2**68 + 0xAB:#X}' == '0X1000000000000000AB'\nassert f'{2**68 + 0xAB:#x}' == '0x1000000000000000ab'\n\n# === Sign-aware (`=`) padding applies to every numeric format, not just :d/:f ===\n# Previously pad_string's SignAware arm fell through, so width was silently\n# dropped for hex/oct/bin/exponential/general/percent.\nassert f'{255:=10x}' == '        ff'\nassert f'{-255:=10x}' == '-       ff'\nassert f'{8:=8b}' == '    1000'\nassert f'{8:=8o}' == '      10'\nassert f'{3.14:=10g}' == '      3.14'\nassert f'{-3.14:=10g}' == '-     3.14'\nassert f'{0.5:=12.2%}' == '      50.00%'\n# format_char has no sign; CPython accepts `=` here and degrades to right-align.\nassert f'{65:=10c}' == '         A'\n\n# === Sign prefix (`+`, ` `) applies to non-decimal integer bases too ===\n# format_int_base previously ignored spec.sign and only emitted '-' for negatives.\nassert f'{255:+x}' == '+ff'\nassert f'{255: x}' == ' ff'\nassert f'{8:+b}' == '+1000'\nassert f'{-255:X}' == '-FF'\n\n# === Integer as Unicode character (:c) ===\nassert f'{65:c}' == 'A'\nassert f'{0x4E2D:c}' == '中'\n\n# === Bool with format spec ===\n# bool is a subclass of int, so :d works\nassert f'{True:d}' == '1'\nassert f'{False:d}' == '0'\nassert f'{True:04d}' == '0001'\n\n# === Float formatting ===\n# basic float\nassert f'{3.14159}' == '3.14159'\n\n# float with :f type\nassert f'{3.141592653589793:f}' == '3.141593'\n\n# float precision\nassert f'{3.141592653589793:.2f}' == '3.14'\nassert f'{3.141592653589793:.4f}' == '3.1416'\n\n# float width and precision\nassert f'{3.141592653589793:06.2f}' == '003.14'\nassert f'{3.141592653589793:10.2f}' == '      3.14'\n\n# float with sign\nassert f'{3.14:+.2f}' == '+3.14'\nassert f'{-3.14:+.2f}' == '-3.14'\nassert f'{3.14:-.2f}' == '3.14'\nassert f'{-3.14:-.2f}' == '-3.14'\n\n# exponential notation\nassert f'{1234.5678:e}' == '1.234568e+03'\nassert f'{1234.5678:E}' == '1.234568E+03'\nassert f'{1234.5678:.2e}' == '1.23e+03'\nassert f'{0.00012345:.2e}' == '1.23e-04'\n\n# general format (g/G) - uses exponential for very large/small numbers\nassert f'{1.5:g}' == '1.5'\nassert f'{1.500:g}' == '1.5'\nassert f'{1234567890:g}' == '1.23457e+09'\n\n# percentage\nassert f'{0.25:%}' == '25.000000%'\nassert f'{0.25:.1%}' == '25.0%'\nassert f'{0.125:.0%}' == '12%'\n\n# zero precision rounds (banker's/half-even style per Python)\nassert f'{3.7:.0f}' == '4'\nassert f'{3.4:.0f}' == '3'\nassert f'{1234.5:.0e}' == '1e+03'\n\n# uppercase exponential\nassert f'{1234.5:E}' == '1.234500E+03'\n\n# float fill character with alignment + precision\nassert f'{3.14:*>10.2f}' == '******3.14'\nassert f'{3.14:*<10.2f}' == '3.14******'\nassert f'{3.14:*^10.2f}' == '***3.14***'\n\n# large and small magnitude exponents\nassert f'{1e100:.3e}' == '1.000e+100'\nassert f'{1e-100:.3e}' == '1.000e-100'\n\n# high precision reveals f64 representation\nassert f'{0.1:.20f}' == '0.10000000000000000555'\n\n# === Large dynamic precision ===\n# Precision > u16::MAX (65535) must not overflow Rust's `format!` precision\n# argument. Each of these exercises a different internal format code path.\nassert f'{1:.{10**6}f}' == '1.' + '0' * 10**6\nassert f'{1:.{10**6}e}' == '1.' + '0' * 10**6 + 'e+00'\nassert f'{1:.{10**6}E}' == '1.' + '0' * 10**6 + 'E+00'\nassert f'{0.5:.{10**6}%}' == '50.' + '0' * 10**6 + '%'\n# :g strips trailing zeros, so the visible result is short, but the\n# underlying format call still uses the full precision internally.\nassert f'{1.5:.{10**6}g}' == '1.5'\nassert f'{1e-10:.{10**6}g}' == '1.0000000000000000364321973154977415791655470655996396089904010295867919921875e-10'\nassert f'{0.0001:.{2**31 - 1}g}' == ('0.000100000000000000004792173602385929598312941379845142364501953125')\n\n# === Large static width/precision ===\n# Static format specs are parsed at parse time and packed into a compact\n# bytecode constant; values around the previous u16 boundary must still\n# round-trip correctly.\nassert len(f'{1.5:.65535f}') == 65537\nassert len(f'{1.5:.65536f}') == 65538\nassert len(f'{42:65536d}') == 65536\n\n# Specs whose width or precision exceed the compact bytecode encoding\n# (MAX_ENCODED_WIDTH = 2**20 - 1, MAX_ENCODED_PRECISION = 2**21 - 2)\n# must still compile — the parser falls back to a dynamic spec so the\n# VM re-parses at runtime.\nassert len(f'{42:1048576d}') == 1048576\nassert len(f'{1.5:.2097151f}') == 2097153\n\n# Fill characters above Latin-1 (codepoint > 0xFF) don't fit the 8-bit\n# fill slot of the compact encoding either — they must also round-trip\n# through the dynamic-spec fallback rather than corrupting the encoded form.\nassert f'{\"hi\":日^10}' == '日日日日hi日日日日'\nassert f'{42:🐍>5d}' == '🐍🐍🐍42'\n\n# === Integer with float format types ===\n# Python allows formatting integers with float types\nassert f'{42:f}' == '42.000000'\nassert f'{42:.2f}' == '42.00'\nassert f'{42:.2e}' == '4.20e+01'\nassert f'{1234:g}' == '1234'\nassert f'{5:%}' == '500.000000%'\n\n# === Negative zero preserves sign ===\nassert f'{-0.0}' == '-0.0'\nassert f'{-0.0:f}' == '-0.000000'\nassert f'{-0.0:+.2f}' == '-0.00'\n\n# === The `z` flag coerces negative zero to positive zero ===\n# Coercion happens AFTER rounding to the target precision: a negative value that\n# rounds to zero becomes +0, but one that rounds to a nonzero value keeps its sign.\nassert f'{-0.0:z}' == '0.0'\nassert f'{-0.0:z.2f}' == '0.00'\nassert f'{-0.001:z.1f}' == '0.0'\nassert f'{-0.001:z.3f}' == '-0.001'\nassert f'{-0.04:z.1f}' == '0.0'\nassert f'{-0.05:z.1f}' == '-0.1'\nassert f'{-0.49:z.0f}' == '0'\nassert f'{-0.5:z.0f}' == '0'\nassert f'{-0.0:ze}' == '0.000000e+00'\nassert f'{-0.0:zg}' == '0'\nassert f'{-0.0:z%}' == '0.000000%'\nassert f'{0.0:z.2f}' == '0.00'\nassert f'{3.14:z.1f}' == '3.1'\nassert f'{-3.14:z.1f}' == '-3.1'\nassert f'{-0.0:+z.1f}' == '+0.0'\nassert f'{-0.0:z010.1f}' == '00000000.0'\nassert f'{0:zf}' == '0.000000'\nassert f'{True:zf}' == '1.000000'\n# `z` in fill position (followed by an align char) is a fill char, not the flag.\nassert f'{-0.0:z>8.1f}' == 'zzzz-0.0'\n\n\n# `z` is only valid for floating-point presentations.\ndef _z_err(fn):\n    try:\n        fn()\n        assert False, 'expected ValueError'\n    except ValueError as exc:\n        return str(exc)\n\n\nassert _z_err(lambda: f'{-5:z}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{-5:zx}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{True:z}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{\"x\":z}') == 'Negative zero coercion (z) not allowed in string format specifier'\nassert _z_err(lambda: f'{5:z#}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{\"x\":z#}') == 'Negative zero coercion (z) not allowed in string format specifier'\n# Precedence: a bad type code or grouping error still wins over the z error.\nassert _z_err(lambda: f'{5:z.2}') == 'Precision not allowed in integer format specifier'\n\n# === Infinity formatting across format codes ===\n# inf bypasses precision/width-pad zero rules and renders as 'inf'\nassert f'{float(\"inf\"):f}' == 'inf'\nassert f'{float(\"inf\"):e}' == 'inf'\nassert f'{float(\"inf\"):.3f}' == 'inf'\nassert f'{float(\"inf\"):+f}' == '+inf'\nassert f'{float(\"-inf\"):f}' == '-inf'\n\n# === Nested format specs ===\nwidth = 10\nassert f'{\"hi\":{width}}' == 'hi        '\n\n# nested alignment and width\nalign = '^'\nassert f'{\"test\":{align}{width}}' == '   test   '\n\nwidth, prec = 10, 3\nassert f'{3.14159:{width}.{prec}f}' == '     3.142'\n\n# nested precision\nprec = 3\nassert f'{\"xylophone\":.{prec}}' == 'xyl'\n\n\n# === f-string in function ===\ndef greet(name):\n    return f'Hello, {name}!'\n\n\nassert greet('World') == 'Hello, World!'\n\n\n# function returning formatted value\ndef format_num(n, w):\n    return f'{n:>{w}}'\n\n\nassert format_num('x', 5) == '    x'\n\n# === Escaping ===\n# double braces to escape\nassert f'{{}}' == '{}'\nassert f'{{x}}' == '{x}'\nassert f'{{{42}}}' == '{42}'\n\n# === Complex expressions ===\n# TODO: method call on literal - parser doesn't support this yet\n# assert f'{\"hello\".upper()}' == 'HELLO', 'method call on literal'\n\n# TODO: method call on variable - str.upper() not implemented yet\n# s = 'hello'\n# assert f'{s.upper()}' == 'HELLO', 'method call on variable'\n\n# subscript in f-string\nlst = [10, 20, 30]\nassert f'{lst[1]}' == '20'\n\n# dict lookup\nd = {'a': 1, 'b': 2}\nassert f'{d[\"a\"]}' == '1'\n\n# TODO: conditional expression - parser doesn't support IfExp yet\n# x = 5\n# assert f'{x if x > 0 else -x}' == '5', 'conditional positive'\n# x = -5\n# assert f'{-x if x < 0 else x}' == '5', 'conditional negative'\n\n# === String concatenation ===\nname = 'world'\n# regular string + f-string (implicit concatenation)\nassert f'hello {name}' == 'hello world'\n\n# === Empty interpolation expression ===\n# (this should be a syntax error, but test current behavior)\n# assert f'{}' would be syntax error\n\n# === Whitespace in format spec ===\n# no extra whitespace handling needed, width handles it\nassert f'{\"x\":5}' == 'x    '\n\n# === Empty format spec with various types ===\n# trailing `:` with no spec behaves like no spec\nassert f'{42:}' == '42'\nassert f'{3.14:}' == '3.14'\nassert f'{\"hi\":}' == 'hi'\n\n# === Unicode character counting in padding ===\nx = 'café'\nassert f'{x:_<10}' == 'café______'\nassert f'{x:_>10}' == '______café'\nassert f'{x:_^10}' == '___café___'\nassert f'{x:_^11}' == '___café____'\nassert f'{x:é<10}' == 'cafééééééé'\nassert f'{x:é>10}' == 'éééééécafé'\nassert f'{x:é^10}' == 'ééécaféééé'\nassert f'{x:é^11}' == 'ééécafééééé'\n\n# === Conversion flag with type spec ===\n# conversion flag produces string, so 's' format should work\nassert f'{42!r:s}' == '42'\n\n# === Conversion flag + spec: the spec is validated as a *string* spec ===\n# `!s`/`!r`/`!a` convert to a string first, so flags that are illegal for text\n# must be rejected exactly as they are for a real string value — and the value\n# and its converted form must raise the *same* error. Valid string flags work:\nassert f'{123!s:05}' == '12300'\nassert f'{123!r:>6}' == '   123'\nwidth = 6\nassert f'{123!r:>{width}}' == '   123'\nassert f'{3.14159!r:.4}' == '3.14'\n\n\n# Illegal-for-text flags raise the same ValueError as on a bare string.\ndef _conv_err(fn):\n    try:\n        fn()\n        assert False, 'expected ValueError'\n    except ValueError as exc:\n        return str(exc)\n\n\nassert _conv_err(lambda: f'{123!s:#}') == 'Alternate form (#) not allowed in string format specifier'\nassert _conv_err(lambda: f'{123!r:,}') == \"Cannot specify ',' with 's'.\"\nassert _conv_err(lambda: f'{123!r:_}') == \"Cannot specify '_' with 's'.\"\nassert _conv_err(lambda: f'{123!s:+}') == 'Sign not allowed in string format specifier'\nassert _conv_err(lambda: f'{123!s: }') == 'Space not allowed in string format specifier'\nassert _conv_err(lambda: f'{123!s:=}') == \"'=' alignment not allowed in string format specifier\"\nassert _conv_err(lambda: f'{123!r:#x}') == \"Unknown format code 'x' for object of type 'str'\"\nassert _conv_err(lambda: f'{123!s:.2f}') == \"Unknown format code 'f' for object of type 'str'\"\n\n# Precedence among multiple violations matches CPython (grouping > type > sign >\n# alternate > `=`), and a value formats identically with or without `!s`/`!r`.\nassert (\n    _conv_err(lambda: f'{\"x\":=#}')\n    == _conv_err(lambda: f'{1!r:=#}')\n    == 'Alternate form (#) not allowed in string format specifier'\n), 'alternate beats = align'\nassert (\n    _conv_err(lambda: f'{\"x\":+#}') == _conv_err(lambda: f'{1!s:+#}') == 'Sign not allowed in string format specifier'\n), 'sign beats alternate'\nassert _conv_err(lambda: f'{\"x\":,x}') == _conv_err(lambda: f'{1!r:,x}') == \"Cannot specify ',' with 'x'.\", (\n    'grouping beats type'\n)\n\n# === Zero-padding with negative numbers ===\n# zero-padding should use sign-aware alignment\nx = -42\nassert f'{x:05d}' == '-0042'\n\n# === Debug/self-documenting expressions (=) ===\na = 42\nassert f'{a=}' == 'a=42'\nassert f'{a = }' == 'a = 42'\nname = 'test'\nassert f'{name=}' == \"name='test'\"\nassert f'{name = }' == \"name = 'test'\"\nassert f'{name=!s}' == 'name=test'\nassert f'{name=!r}' == \"name='test'\"\nassert f'{1+1=}' == '1+1=2'\n# a format spec applies to the *value*, not the (default-repr) string — the\n# implicit repr only kicks in when there is no spec and no conversion\n_v = 6.28318\nassert f'{_v=:.3f}' == '_v=6.283'\nassert f'{_v=:>10.2f}' == '_v=      6.28'\nassert f'{_v=!r:>12}' == '_v=     6.28318'\nassert f'{_v=}' == '_v=6.28318'\n# an *explicit empty* spec (`{x=:}`) formats with str, NOT the repr default —\n# `format(x, \"\")` equals `str(x)`, so the colon disables the debug repr default\nassert f'{name=:}' == 'name=test'\nassert f'{a=:}' == 'a=42'\n_b = True\nassert f'{_b=:}' == '_b=True'\nassert f'{name = :}' == 'name = test'\nassert f'{name=!r:}' == \"name='test'\"\n\n# === Comma thousands separator ===\nassert f'{1234567:,}' == '1,234,567'\nassert f'{1234:,}' == '1,234'\nassert f'{12:,}' == '12'\nassert f'{0:,}' == '0'\nassert f'{-1234567:,}' == '-1,234,567'\nassert f'{1234567:,d}' == '1,234,567'\nassert f'{1234567.891:,f}' == '1,234,567.891000'\nassert f'{1234567.891:,.2f}' == '1,234,567.89'\nassert f'{-1234567.891:,.2f}' == '-1,234,567.89'\nassert f'{1234567.891:,e}' == '1.234568e+06'\nassert f'{1234.5:,g}' == '1,234.5'\nassert f'{12.3456:,%}' == '1,234.560000%'\nassert f'{1234:+,}' == '+1,234'\nassert f'{-1234:+,}' == '-1,234'\nassert f'{1234: ,}' == ' 1,234'\n\n# === Underscore thousands separator ===\nassert f'{1234567:_}' == '1_234_567'\nassert f'{1234567:_d}' == '1_234_567'\nassert f'{1234567.891:_.2f}' == '1_234_567.89'\n# Underscore groups binary/octal/hex in fours\nassert f'{255:_b}' == '1111_1111'\nassert f'{0xABCDEF:_x}' == 'ab_cdef'\nassert f'{0xABCDEF:_X}' == 'AB_CDEF'\nassert f'{0o12345670:_o}' == '1234_5670'\n\n# === Grouping with zero-padding (padding is itself grouped) ===\nassert f'{1234567:012,d}' == '0,001,234,567'\nassert f'{1234:010,}' == '00,001,234'\nassert f'{-1234:010,}' == '-0,001,234'\nassert f'{1234:08,}' == '0,001,234'\nassert f'{1234:07,}' == '001,234'\nassert f'{1234:05,}' == '1,234'\nassert f'{1234567.891:020,.2f}' == '0,000,001,234,567.89'\nassert f'{255:010_b}' == '0_1111_1111'\nassert f'{1234:0=10,}' == '00,001,234'\nassert f'{1:0=+9_g}' == '+0_000_001'\n\n# === Grouping with explicit alignment (fill is not grouped) ===\nassert f'{1234:=10,}' == '     1,234'\nassert f'{1234:=+10,}' == '+    1,234'\nassert f'{1234:>12,}' == '       1,234'\nassert f'{1234:*>12,}' == '*******1,234'\n\n# === Alternate form (#) on integer bases adds the 0b/0o/0x prefix ===\nassert f'{255:#x}' == '0xff'\nassert f'{255:#X}' == '0XFF'\nassert f'{5:#b}' == '0b101'\nassert f'{8:#o}' == '0o10'\nassert f'{-255:#x}' == '-0xff'\nassert f'{0:#x}' == '0x0'\nassert f'{255:#d}' == '255'\n# prefix counts toward width and sits before zero padding\nassert f'{255:#10x}' == '      0xff'\nassert f'{255:#010x}' == '0x000000ff'\nassert f'{-255:#010x}' == '-0x00000ff'\nassert f'{255:+#x}' == '+0xff'\n# prefix with alignment / grouping\nassert f'{255:<#10x}' == '0xff      '\nassert f'{255:^#10x}' == '   0xff   '\nassert f'{255:=#10x}' == '0x      ff'\nassert f'{255:*=#10x}' == '0x******ff'\nassert f'{0xABCDEF:#_x}' == '0xab_cdef'\nassert f'{0xABCDEF:#010_x}' == '0x0ab_cdef'\n\n# === Alternate form (#) on floats forces a decimal point ===\nassert f'{1.0:#.0f}' == '1.'\nassert f'{0.0:#.0f}' == '0.'\nassert f'{1.0:#.0e}' == '1.e+00'\nassert f'{3.14:+#.2f}' == '+3.14'\nassert f'{0.5:#.0%}' == '50.%'\n# explicit g/G keeps trailing zeros under #\nassert f'{1.0:#g}' == '1.00000'\nassert f'{100.0:#g}' == '100.000'\nassert f'{1.5:#.3g}' == '1.50'\nassert f'{1234.0:#.4g}' == '1234.'\n# default float presentation: # is a no-op (shortest repr already has a point)\nassert f'{3.14:#}' == '3.14'\n# `#g`/`#G`/type-less keep every trailing zero, so the digit count scales with\n# precision past Rust's formatter cap (regression: it used to silently truncate\n# to ~65k digits). Verify the count is exact, not clamped.\nassert f'{1.0:#.10g}' == '1.000000000'\nassert f'{1.0:#.10G}' == '1.000000000'\nassert f'{123456.0:#.10}' == '123456.0000'\nassert len(f'{1.0:#.70000g}') == 70001\nassert len(f'{1.0:#.70000}') == 70001\n\n# === inf / nan: case follows the presentation, never `.0` ===\n_inf = float('inf')\n_nan = float('nan')\nassert f'{_inf}' == 'inf'\nassert f'{-_inf}' == '-inf'\nassert f'{_nan}' == 'nan'\nassert str(_inf) == 'inf' and repr(_nan) == 'nan', 'inf/nan str/repr'\nassert f'{_inf:f}' == 'inf' and f'{_inf:F}' == 'INF', 'inf f vs F case'\nassert f'{_nan:e}' == 'nan' and f'{_nan:E}' == 'NAN', 'nan e vs E case'\nassert f'{_inf:g}' == 'inf' and f'{_inf:G}' == 'INF', 'inf g vs G case'\nassert f'{_nan:%}' == 'nan%'\nassert f'{_inf:+.2f}' == '+inf'\n# grouping/zero-pad on a non-finite value must not panic and ignores the comma\nassert f'{_inf:08,}' == '00000inf'\nassert f'{-_inf:+020,}' == '-0000000000000000inf'\nassert f'{_nan:,}' == 'nan'\n\n# === float repr uses scientific notation past CPython's thresholds ===\nassert f'{1e16}' == '1e+16'\nassert f'{1e15}' == '1000000000000000.0'\nassert f'{1e-5}' == '1e-05'\nassert f'{1e-4}' == '0.0001'\nassert f'{1.2345678901234568e16}' == '1.2345678901234568e+16'\nassert f'{1e100}' == '1e+100'\n\n# === type-less float spec uses repr digits, not g (precision-6) ===\nassert f'{1234567.0:}' == '1234567.0'\nassert f'{1234567.0:>12}' == '   1234567.0'\nassert f'{1234.5678:+,}' == '+1,234.5678'\n\n# === bool is an int subclass under a (non-empty) format spec ===\nassert f'{True}' == 'True' and f'{True:}' == 'True', 'bare bool is the word'\nassert f'{True: }' == ' 1'\nassert f'{False:05}' == '00000'\nassert f'{True:#06x}' == '0x0001'\nassert f'{True:.2f}' == '1.00'\n\n# === big integers honour the full mini-language ===\n_big = 2**70\nassert f'{_big:,}' == '1,180,591,620,717,411,303,424'\nassert f'{_big:+}' == '+1180591620717411303424'\nassert f'{_big:#x}' == '0x400000000000000000'\nassert f'{_big:#o}' == '0o200000000000000000000000'\nassert f'{-(2**63):>25}' == '     -9223372036854775808'\nassert f'{2**63:.3e}' == '9.223e+18'\n\n# === precision is rejected on integer presentations ===\nfor _spec in ('.2d', '.2', '.2x', '.2b', '.0c'):\n    try:\n        f'{42:{_spec}}'\n        assert False, f'expected precision on int spec {_spec!r} to fail'\n    except ValueError as _e:\n        assert str(_e) == 'Precision not allowed in integer format specifier', f'{_spec}: {_e}'\n\n# === c rejects a sign; strings reject signs and `=` alignment ===\ntry:\n    f'{65:+c}'\n    assert False, 'expected sign with c to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Sign not allowed with integer format specifier 'c'\", f'sign+c: {_e}'\ntry:\n    f'{\"x\":+}'\n    assert False, 'expected sign on string to fail'\nexcept ValueError as _e:\n    assert str(_e) == 'Sign not allowed in string format specifier', f'sign+str: {_e}'\ntry:\n    f'{\"x\": }'\n    assert False, 'expected space on string to fail'\nexcept ValueError as _e:\n    assert str(_e) == 'Space not allowed in string format specifier', f'space+str: {_e}'\ntry:\n    f'{\"x\":=5}'\n    assert False, 'expected = alignment on string to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"'=' alignment not allowed in string format specifier\", f'=+str: {_e}'\n\n# === `0` flag with an explicit alignment is just a `0` fill, not sign-aware ===\nassert f'{-42:<05}' == '-4200'\nassert f'{42:^05}' == '04200'\nassert f'{42:>05}' == '00042'\nassert f'{42:*<05}' == '42***'\nassert f'{-42:05}' == '-0042'\nassert f'{\"hi\":05}' == 'hi000'\n\n# === `c` is a numeric presentation: right-aligned by default ===\nassert f'{65:5c}' == '    A'\nassert f'{65:<5c}' == 'A    '\nassert f'{65:05c}' == '0000A'\n\n# === `n` (locale number): like `d` for int, `g` for float (C locale here) ===\nassert f'{1234567:n}' == '1234567'\nassert f'{1234567.0:n}' == '1.23457e+06'\nassert f'{-42:+n}' == '-42'\nassert f'{2**70:n}' == '1180591620717411303424'\nassert f'{True:n}' == '1'\n# n forbids an explicit grouping and (for ints) a precision\ntry:\n    f'{1234:,n}'\n    assert False, 'expected , with n to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Cannot specify ',' with 'n'.\", f',n: {_e}'\ntry:\n    f'{42:.2n}'\n    assert False, 'expected precision with int n to fail'\nexcept ValueError as _e:\n    assert str(_e) == 'Precision not allowed in integer format specifier', f'.2n: {_e}'\n\n# === Fractional grouping (Python 3.14): [.precision][grouping] ===\nassert f'{1234.5678:.6_f}' == '1234.567_800'\nassert f'{1234567.89:,.4_f}' == '1,234,567.890_0'\nassert f'{12345.678:._f}' == '12345.678_000'\nassert f'{1234567.891:,._f}' == '1,234,567.891_000'\n\n# === Type-less float with an explicit precision (g-like, one exp earlier) ===\nassert f'{100.0:.3}' == '1e+02'\nassert f'{1.0:.0}' == '1e+00'\nassert f'{1234.5678:.6}' == '1234.57'\nassert f'{9.99:.1g}' == '1e+01'\n\n# === Error precedence: an invalid type code beats the #/sign checks ===\ntry:\n    f'{3.14:#c}'\n    assert False, 'expected #c on float to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Unknown format code 'c' for object of type 'float'\", f'#c float: {_e}'\ntry:\n    f'{42:#s}'\n    assert False, 'expected #s on int to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Unknown format code 's' for object of type 'int'\", f'#s int: {_e}'\n",
  'fstring__error_eq_align_on_str.py': "# '=' alignment on string raises ValueError\nf'{\"hello\":=10}'\n# Raise=ValueError(\"'=' alignment not allowed in string format specifier\")\n",
  'fstring__error_float_f_on_str.py': "# float format specifier ':f' on string raises ValueError\nf'{\"hello\":f}'\n# Raise=ValueError(\"Unknown format code 'f' for object of type 'str'\")\n",
  'fstring__error_int_d_on_float.py': "# integer format specifier ':d' on float raises ValueError\nf'{3.14:d}'\n# Raise=ValueError(\"Unknown format code 'd' for object of type 'float'\")\n",
  'fstring__error_int_d_on_str.py': "# integer format specifier ':d' on string raises ValueError\nf'{\"hello\":d}'\n# Raise=ValueError(\"Unknown format code 'd' for object of type 'str'\")\n",
  'fstring__error_invalid_flags.py': "# Format flags (`,`/`_` grouping and `#` alternate form) are only valid for\n# certain presentation types. Illegal combinations raise ValueError at format\n# time, matching CPython.\n\n# comma is not allowed with integer base presentations\ntry:\n    f'{255:,x}'\n    assert False, 'expected comma with x to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with 'x'.\", str(exc)\n\ntry:\n    f'{255:,b}'\n    assert False, 'expected comma with b to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with 'b'.\", str(exc)\n\ntry:\n    f'{255:,o}'\n    assert False, 'expected comma with o to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with 'o'.\", str(exc)\n\n# neither separator is allowed with the character presentation\ntry:\n    f'{65:,c}'\n    assert False, 'expected comma with c to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with 'c'.\", str(exc)\n\ntry:\n    f'{65:_c}'\n    assert False, 'expected underscore with c to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify '_' with 'c'.\", str(exc)\n\n# neither separator is allowed when formatting a string\ntry:\n    f'{\"hi\":,}'\n    assert False, 'expected comma with str to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with 's'.\", str(exc)\n\ntry:\n    f'{\"hi\":_s}'\n    assert False, 'expected underscore with s to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify '_' with 's'.\", str(exc)\n\n# the alternate form (`#`) is not allowed with the character presentation\ntry:\n    f'{65:#c}'\n    assert False, 'expected # with c to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Alternate form (#) not allowed with integer format specifier 'c'\", str(exc)\n\n# the alternate form is not allowed when formatting a string\ntry:\n    f'{\"hi\":#}'\n    assert False, 'expected # with str to fail'\nexcept ValueError as exc:\n    assert str(exc) == 'Alternate form (#) not allowed in string format specifier', str(exc)\n\ntry:\n    f'{\"hi\":#s}'\n    assert False, 'expected # with s to fail'\nexcept ValueError as exc:\n    assert str(exc) == 'Alternate form (#) not allowed in string format specifier', str(exc)\n\n# === Unknown format code ===\n# A single unrecognised trailing char is reported as an unknown code (with the\n# value's type), not the generic \"Invalid format specifier\". Other valid spec\n# fields before it (width, sign, `#`, `0`, precision) don't change the message.\ntry:\n    f'{1:k}'\n    assert False, 'expected unknown code k to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Unknown format code 'k' for object of type 'int'\", str(exc)\n\ntry:\n    f'{1:5k}'\n    assert False, 'expected unknown code with width to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Unknown format code 'k' for object of type 'int'\", str(exc)\n\ntry:\n    f'{\"hi\":k}'\n    assert False, 'expected unknown code k on str to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Unknown format code 'k' for object of type 'str'\", str(exc)\n\ntry:\n    f'{1.5:k}'\n    assert False, 'expected unknown code k on float to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Unknown format code 'k' for object of type 'float'\", str(exc)\n\n# A dynamic (runtime-built) spec reports the same unknown-code message.\ntry:\n    f'{1:{\"k\"}}'\n    assert False, 'expected dynamic unknown code to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Unknown format code 'k' for object of type 'int'\", str(exc)\n\n# Two or more trailing chars are genuinely malformed (kept distinct from the\n# single-char unknown-code case); a runtime spec surfaces it as a ValueError.\ntry:\n    f'{1:{\"kk\"}}'\n    assert False, 'expected malformed spec to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Invalid format specifier 'kk' for object of type 'int'\", str(exc)\n\n# === Missing precision ===\n# A `.` must be followed by precision digits or a fractional grouping option;\n# `.f`/`.`/`.d` are \"missing precision\" (CPython raises this, not silent format).\ntry:\n    f'{1.5:.f}'\n    assert False, 'expected missing precision to fail'\nexcept ValueError as exc:\n    assert str(exc) == 'Format specifier missing precision', str(exc)\n\ntry:\n    f'{1:.}'\n    assert False, 'expected bare dot to fail'\nexcept ValueError as exc:\n    assert str(exc) == 'Format specifier missing precision', str(exc)\n\n# A `.` followed by a grouping option is valid (not missing precision).\nassert f'{1.5:._f}' == '1.500_000'\nassert f'{1.5:.,f}' == '1.500,000'\n\n# === Grouping conflicts with an unknown trailing char ===\n# A grouping option next to an unrecognised char reports the grouping conflict\n# (which takes precedence over the unknown-code error), matching CPython.\ntry:\n    f'{1:,k}'\n    assert False, 'expected comma+unknown to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with 'k'.\", str(exc)\n\n# Doubled separators and mixed separators each have their own wording.\ntry:\n    f'{1:,,}'\n    assert False, 'expected doubled comma to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify ',' with ','.\", str(exc)\n\ntry:\n    f'{1:__}'\n    assert False, 'expected doubled underscore to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify '_' with '_'.\", str(exc)\n\ntry:\n    f'{1:,_}'\n    assert False, 'expected mixed separators to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify both ',' and '_'.\", str(exc)\n\ntry:\n    f'{1:_,}'\n    assert False, 'expected mixed separators to fail'\nexcept ValueError as exc:\n    assert str(exc) == \"Cannot specify both ',' and '_'.\", str(exc)\n",
  'fstring__error_invalid_spec.py': "# xfail=cpython\n# invalid format specifier with trailing characters (detected at parse time)\nf'{1:10xyz}'\n# Raise=SyntaxError(\"Invalid format specifier '10xyz'\")\n",
  'fstring__error_invalid_spec_dynamic.py': "# invalid format specifier with dynamic spec\nspec = 'xyz'\nf'{1:{spec}}'\n# Raise=ValueError(\"Invalid format specifier 'xyz' for object of type 'int'\")\n",
  'fstring__error_invalid_spec_str.py': "# xfail=cpython\n# invalid format specifier for string (detected at parse time)\nf'{\"hello\":abc}'\n# Raise=SyntaxError(\"Invalid format specifier 'abc'\")\n",
  'fstring__error_str_s_on_int.py': "# string format specifier ':s' on integer raises ValueError\nf'{42:s}'\n# Raise=ValueError(\"Unknown format code 's' for object of type 'int'\")\n",
  'fstring__pyformat.py': "# Every example from https://pyformat.info/ , converted to f-strings.\n\nfrom datetime import datetime\n\n# === Basic formatting ===\n# '{} {}'.format('one', 'two') / '{} {}'.format(1, 2) / '{1} {0}'.format(...)\nassert f'{\"one\"} {\"two\"}' == 'one two'\nassert f'{1} {2}' == '1 2'\n# `{1} {0}` reorders args; f-strings inline the values in the wanted order.\nassert f'{\"two\"} {\"one\"}' == 'two one'\n\n# === Value conversion (!s / !r / !a) ===\n# Original uses a Data() class whose __str__/__repr__ differ. A plain string\n# shows the same distinction: !s -> str(), !r -> repr() (adds quotes).\nassert f'{\"text\"!s} {\"text\"!r}' == \"text 'text'\"\n# '{0!r} {0!a}' on a non-ASCII value: !r keeps it, !a escapes to ASCII.\nassert f'{\"räpr\"!r} {\"räpr\"!a}' == \"'räpr' 'r\\\\xe4pr'\"\n\n# === Padding and aligning strings ===\nassert f'{\"test\":>10}' == '      test'\nassert f'{\"test\":10}' == 'test      '\nassert f'{\"test\":_<10}' == 'test______'\nassert f'{\"test\":^10}' == '   test   '\nassert f'{\"zip\":^6}' == ' zip  '\n\n# === Truncating long strings ===\nassert f'{\"xylophone\":.5}' == 'xylop'\n\n# === Combining truncating and padding ===\nassert f'{\"xylophone\":10.5}' == 'xylop     '\n\n# === Numbers ===\nassert f'{42:d}' == '42'\nassert f'{3.141592653589793:f}' == '3.141593'\n\n# === Padding numbers ===\nassert f'{42:4d}' == '  42'\nassert f'{3.141592653589793:06.2f}' == '003.14'\nassert f'{42:04d}' == '0042'\n\n# === Signed numbers ===\nassert f'{42:+d}' == '+42'\nassert f'{-23: d}' == '-23'\nassert f'{42: d}' == ' 42'\nassert f'{-23:=5d}' == '-  23'\nassert f'{23:=+5d}' == '+  23'\n\n# === Named placeholders ===\n# '{first} {last}'.format(first='Hodor', last='Hodor!') -> just reference vars.\nfirst = 'Hodor'\nlast = 'Hodor!'\nassert f'{first} {last}' == 'Hodor Hodor!'\n\n# === Getitem and getattr ===\n# '{p[first]} {p[last]}'.format(p=person) — dict subscript in the expression.\nperson = {'first': 'Jean-Luc', 'last': 'Picard'}\nassert f'{person[\"first\"]} {person[\"last\"]}' == 'Jean-Luc Picard'\n# '{d[4]} {d[5]}'.format(d=data) — list indexing.\ndata = [0, 1, 2, 3, 23, 42]\nassert f'{data[4]} {data[5]}' == '23 42'\n# '{p.type}: {p.kinds[0][name]}' uses a custom class; demonstrate the same\n# attribute-access + chained-getitem capability with built-in values.\ndt = datetime(2001, 2, 3, 4, 5)\nassert f'{dt.year}' == '2001'\nplant = {'kinds': [{'name': 'oak'}]}\nassert f'tree: {plant[\"kinds\"][0][\"name\"]}' == 'tree: oak'\n\n# === Datetime ===\nassert f'{dt:%Y-%m-%d %H:%M}' == '2001-02-03 04:05'\n\n# === Parametrized (nested) formats ===\n# '{:{align}{width}}'.format('test', align='^', width='10')\nalign = '^'\nwidth = 10\nassert f'{\"test\":{align}{width}}' == '   test   '\n# '{:.{prec}} = {:.{prec}f}'.format('Gibberish', 2.7182, prec=3)\nprec = 3\nassert f'{\"Gibberish\":.{prec}} = {2.7182:.{prec}f}' == 'Gib = 2.718'\n# '{:{width}.{prec}f}'.format(2.7182, width=5, prec=2)\nw = 5\np = 2\nassert f'{2.7182:{w}.{p}f}' == ' 2.72'\n# '{:{prec}} = {:{prec}}'.format('Gibberish', 2.7182, prec='.3')\nprec_str = '.3'\nassert f'{\"Gibberish\":{prec_str}} = {2.7182:{prec_str}}' == 'Gib = 2.72'\n# '{:{dfmt} {tfmt}}'.format(dt, dfmt='%Y-%m-%d', tfmt='%H:%M') — nested strftime.\ndfmt = '%Y-%m-%d'\ntfmt = '%H:%M'\nassert f'{dt:{dfmt} {tfmt}}' == '2001-02-03 04:05'\n# '{:{}{}{}.{}}'.format(2.7182818284, '>', '+', 10, 3) — all parts parametrized.\nassert f'{2.7182818284:{\">\"}{\"+\"}{10}.{3}}' == '     +2.72'\n# '{:{}{sign}{}.{}}'.format(2.7182818284, '>', 10, 3, sign='+') — mixed.\nsign = '+'\nassert f'{2.7182818284:{\">\"}{sign}{10}.{3}}' == '     +2.72'\n\n# === Escaping braces ===\n# '{{}}'.format() -> literal braces; '{{{}}}'.format('x') -> '{x}'.\nassert f'{{}}' == '{}'\nassert f'{{{\"x\"}}}' == '{x}'\n\n# === Custom objects (not representable in Monty) ===\n# pyformat.info also shows '{:%Y}'.format(custom) and\n# '{:open-the-pod-bay-doors}'.format(HAL9000()), which dispatch to a\n# user-defined __format__. Monty has no `class` statement and no general\n# __format__ protocol (only date/datetime get strftime handling — covered\n# above), so these have no f-string equivalent and are intentionally omitted.\n",
  'function__arity_defaults.py': "# Arity errors for functions whose positional params have defaults: CPython\n# reports the range form for too-many ('takes from X to Y positional\n# arguments') and counts only *required* params as missing.\n\n\ndef f(a, b=1):\n    return a + b\n\n\ndef g(a, b, c=1, d=2):\n    return a + b + c + d\n\n\ntry:\n    f(1, 2, 3)\n    assert False, 'f(1, 2, 3) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'f() takes from 1 to 2 positional arguments but 3 were given', f'range too-many: {e}'\n\ntry:\n    f()\n    assert False, 'f() should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"f() missing 1 required positional argument: 'a'\", f'defaults not missing: {e}'\n\ntry:\n    g(1)\n    assert False, 'g(1) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"g() missing 1 required positional argument: 'b'\", f'only required missing: {e}'\n\ntry:\n    g()\n    assert False, 'g() should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"g() missing 2 required positional arguments: 'a' and 'b'\", f'two missing joined: {e}'\n\ntry:\n    g(1, 2, 3, 4, 5)\n    assert False, 'g(1, 2, 3, 4, 5) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'g() takes from 2 to 4 positional arguments but 5 were given', f'range too-many g: {e}'\n\n\ndef h(a, b, c):\n    return a\n\n\ntry:\n    h()\n    assert False, 'h() should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"h() missing 3 required positional arguments: 'a', 'b', and 'c'\", f'oxford comma: {e}'\n\n\n# === keyword errors beat too-many-positional (CPython binds kwargs first) ===\ndef k1(a):\n    return a\n\n\ntry:\n    k1(1, 2, bad=3)\n    assert False, 'k1(1, 2, bad=3) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"k1() got an unexpected keyword argument 'bad'\", f'unknown kwarg beats overflow: {e}'\n\ntry:\n    k1(1, 2, a=3)\n    assert False, 'k1(1, 2, a=3) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"k1() got multiple values for argument 'a'\", f'duplicate beats overflow: {e}'\n\n\ndef k2(a, *, c=1):\n    return a\n\n\n# A kwarg that binds cleanly to a keyword-only param leaves the overflow to\n# fire, counted in the `(and N keyword-only argument(s))` suffix — only\n# *bound* kw-only params count, defaults and unknown names do not.\ntry:\n    k2(1, 2, c=3)\n    assert False, 'k2(1, 2, c=3) should raise TypeError'\nexcept TypeError as e:\n    assert (\n        str(e) == 'k2() takes 1 positional argument but 2 positional arguments (and 1 keyword-only argument) were given'\n    ), f'kwonly suffix counts bound params: {e}'\n\ntry:\n    k2(1, 2, c=3, bad=4)\n    assert False, 'k2(1, 2, c=3, bad=4) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"k2() got an unexpected keyword argument 'bad'\", f'unknown kwarg beats overflow with kwonly: {e}'\n\ntry:\n    k2(1, 2)\n    assert False, 'k2(1, 2) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'k2() takes 1 positional argument but 2 were given', f'no suffix when no kwonly bound: {e}'\n\n\ndef k3(a, b=1, *, c, d=2):\n    return a\n\n\ntry:\n    k3(1, 2, 3, c=5, d=6)\n    assert False, 'k3(1, 2, 3, c=5, d=6) should raise TypeError'\nexcept TypeError as e:\n    assert (\n        str(e)\n        == 'k3() takes from 1 to 2 positional arguments but 3 positional arguments (and 2 keyword-only arguments) were given'\n    ), f'plural kwonly suffix: {e}'\n\n\n# === More than 64 named parameters ===\ndef many_params(\n    p00,\n    p01,\n    p02,\n    p03,\n    p04,\n    p05,\n    p06,\n    p07,\n    p08,\n    p09,\n    p10,\n    p11,\n    p12,\n    p13,\n    p14,\n    p15,\n    p16,\n    p17,\n    p18,\n    p19,\n    p20,\n    p21,\n    p22,\n    p23,\n    p24,\n    p25,\n    p26,\n    p27,\n    p28,\n    p29,\n    p30,\n    p31,\n    p32,\n    p33,\n    p34,\n    p35,\n    p36,\n    p37,\n    p38,\n    p39,\n    p40,\n    p41,\n    p42,\n    p43,\n    p44,\n    p45,\n    p46,\n    p47,\n    p48,\n    p49,\n    p50,\n    p51,\n    p52,\n    p53,\n    p54,\n    p55,\n    p56,\n    p57,\n    p58,\n    p59,\n    p60,\n    p61,\n    p62,\n    p63,\n    p64=640,\n    *,\n    flag,\n):\n    return p00, p63, p64, flag\n\n\nassert many_params(*range(64), flag=True) == (0, 63, 640, True)\nassert many_params(*range(64), p64=64, flag=False) == (0, 63, 64, False)\nassert many_params(*range(65), flag=True) == (0, 63, 64, True)\n\ntry:\n    many_params(*range(65), p64=65, flag=True)\n    assert False, 'expected duplicate argument error'\nexcept TypeError as e:\n    assert str(e) == \"many_params() got multiple values for argument 'p64'\"\n\ntry:\n    many_params(*range(65))\n    assert False, 'expected missing keyword-only argument error'\nexcept TypeError as e:\n    assert str(e) == \"many_params() missing 1 required keyword-only argument: 'flag'\"\n",
  'function__call_duplicate_kwargs.py': "def f(**kwargs):\n    pass\n\n\nf(**{'x': 1}, **{'x': 2})\n# Raise=TypeError(\"f() got multiple values for keyword argument 'x'\")\n",
  'function__call_unpack.py': "def f(*args, **kwargs):\n    return args, kwargs\n\n\n# === Multiple *args ===\nassert f(*[1, 2], *[3, 4]) == ((1, 2, 3, 4), {})\nassert f(0, *[1, 2], 3) == ((0, 1, 2, 3), {})\nassert f(*[], *[1]) == ((1,), {})\n\n# === Multiple **kwargs ===\nassert f(**{'a': 1}, **{'b': 2}) == ((), {'a': 1, 'b': 2})\nassert f(**{'a': 1}, b=2) == ((), {'a': 1, 'b': 2})\nassert f(key='before', **{'a': 1}) == ((), {'key': 'before', 'a': 1})\n\n# === Mixed ===\nassert f(1, *[2, 3], **{'x': 4}) == ((1, 2, 3), {'x': 4})\n\n# === Builtin callable with GeneralizedCall (Callable::Builtin path) ===\n# max(*[1,2], *[3,4]) exercises the Callable::Builtin branch in compile_call GeneralizedCall\nresult = max(*[1, 2], *[3, 4])\nassert result == 4\n\nresult = min(*[5, 3], *[7, 1])\nassert result == 1\n\n# Builtin type and exception constructors should keep their public names in\n# **kwargs merge errors, not fall back to '<unknown>'.\ntry:\n    list(**1)\n    assert False, 'list with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('list() argument after ** must be a mapping, not int',)\n\ntry:\n    ValueError(**1)\n    assert False, 'ValueError with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('ValueError() argument after ** must be a mapping, not int',)\n\ntry:\n    list(a=1, **{'a': 2})\n    assert False, 'list with duplicate **kwargs should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"list() got multiple values for keyword argument 'a'\",)\n\n# Builtin type constructors should also keep their public names in\n# non-mapping **kwargs errors so compiler call metadata matches CPython.\ntry:\n    bool(**1)\n    assert False, 'bool with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('bool() argument after ** must be a mapping, not int',)\n\ntry:\n    int(**1)\n    assert False, 'int with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('int() argument after ** must be a mapping, not int',)\n\ntry:\n    float(**1)\n    assert False, 'float with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('float() argument after ** must be a mapping, not int',)\n\ntry:\n    str(**1)\n    assert False, 'str with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('str() argument after ** must be a mapping, not int',)\n\ntry:\n    bytes(**1)\n    assert False, 'bytes with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('bytes() argument after ** must be a mapping, not int',)\n\ntry:\n    tuple(**1)\n    assert False, 'tuple with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('tuple() argument after ** must be a mapping, not int',)\n\ntry:\n    dict(**1)\n    assert False, 'dict with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('dict() argument after ** must be a mapping, not int',)\n\ntry:\n    set(**1)\n    assert False, 'set with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('set() argument after ** must be a mapping, not int',)\n\ntry:\n    frozenset(**1)\n    assert False, 'frozenset with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('frozenset() argument after ** must be a mapping, not int',)\n\ntry:\n    range(**1)\n    assert False, 'range with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('range() argument after ** must be a mapping, not int',)\n\ntry:\n    slice(**1)\n    assert False, 'slice with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('slice() argument after ** must be a mapping, not int',)\n\ntry:\n    type(**1)\n    assert False, 'type with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('type() argument after ** must be a mapping, not int',)\n\ntry:\n    property(**1)\n    assert False, 'property with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('property() argument after ** must be a mapping, not int',)\n\ntry:\n    ValueError(a=1, **{'a': 2})\n    assert False, 'ValueError with duplicate **kwargs should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"ValueError() got multiple values for keyword argument 'a'\",)\n\n# === Expression-based callable with GeneralizedCall (compile_call_args path) ===\n# funcs[0](*[1,2], *[3,4]) exercises the GeneralizedCall branch in compile_call_args\nfuncs = [f]\nresult = funcs[0](*[1, 2], *[3, 4])\nassert result == ((1, 2, 3, 4), {})\n\nresult = funcs[0](**{'a': 1}, **{'b': 2})\nassert result == ((), {'a': 1, 'b': 2})\n\n# === Named kwarg in GeneralizedCall (compile_generalized_call_body Named path) ===\n# f(*[1,2], *[3], x=5): two *unpacks → GeneralizedCall; x=5 is a Named kwarg.\n# This exercises the CallKwarg::Named arm in compile_generalized_call_body.\nresult = f(*[1, 2], *[3], x=5)\nassert result == ((1, 2, 3), {'x': 5})\n\nresult = funcs[0](*[1, 2], *[3], x=5)\nassert result == ((1, 2, 3), {'x': 5})\n",
  'function__defaults.py': "# Tests for default parameter values in function definitions\n\n# === Basic default values ===\ndef f_basic(a, b=10):\n    return a + b\n\n\nassert f_basic(1) == 11\nassert f_basic(1, 2) == 3\nassert f_basic(5) == 15\n\n\n# === Multiple defaults ===\ndef f_multi(a=1, b=2):\n    return a + b\n\n\nassert f_multi() == 3\nassert f_multi(10) == 12\nassert f_multi(10, 20) == 30\n\n\n# === Mixed required and default ===\ndef f_mixed(a, b, c=3, d=4):\n    return a + b + c + d\n\n\nassert f_mixed(1, 2) == 10\nassert f_mixed(1, 2, 30) == 37\nassert f_mixed(1, 2, 30, 40) == 73\n\n\n# === Default with keyword args ===\ndef f_kw(a, b=10):\n    return a + b\n\n\nassert f_kw(1, b=20) == 21\nassert f_kw(a=5) == 15\nassert f_kw(a=5, b=3) == 8\n\n\n# === Default expressions evaluated at definition ===\n# Test that default is evaluated once at definition time\ndef value_maker():\n    return 42\n\n\ndef f_eval(x=value_maker()):\n    return x\n\n\n# value_maker was called once at function definition time\nassert f_eval() == 42\nassert f_eval() == 42\n\n\n# === Mutable default (Python gotcha - shared across calls) ===\ndef f_mutable(lst=[]):\n    lst.append(1)\n    return lst\n\n\nfirst_result = f_mutable()\nassert first_result == [1]\nsecond_result = f_mutable()\nassert second_result == [1, 1]\nassert first_result is second_result\n\n\n# === Multiple functions with separate defaults ===\ndef f_sep1(x=[]):\n    x.append('a')\n    return x\n\n\ndef f_sep2(x=[]):\n    x.append('b')\n    return x\n\n\nr1 = f_sep1()\nr2 = f_sep2()\nassert r1 == ['a']\nassert r2 == ['b']\nassert r1 is not r2\n\n\n# === Default referencing earlier param (not supported, different test) ===\n\n\n# === Closure with defaults ===\ndef make_adder(n):\n    def add(x, y=n):\n        return x + y\n\n    return add\n\n\nadd5 = make_adder(5)\nassert add5(10) == 15\nassert add5(10, 3) == 13\n\nadd10 = make_adder(10)\nassert add10(1) == 11\n\n# Verify the two closures have independent defaults\nassert add5(1) == 6\n\n\n# === Keyword-only defaults interleaved ===\ndef kwonly_mix(*, head=1, mid, tail=3):\n    return head, mid, tail\n\n\nassert kwonly_mix(mid=2) == (1, 2, 3)\nassert kwonly_mix(head=5, mid=7) == (5, 7, 3)\n",
  'function__err_duplicate_arg.py': "# Test: same argument passed both positionally and by keyword\ndef f(a, b, c):\n    return a + b + c\n\n\nf(1, 2, b=3)\n# Raise=TypeError(\"f() got multiple values for argument 'b'\")\n",
  'function__err_duplicate_first_arg.py': "# Test: first argument passed both positionally and by keyword\ndef f(a, b):\n    return a + b\n\n\nf(1, a=2)\n# Raise=TypeError(\"f() got multiple values for argument 'a'\")\n",
  'function__err_duplicate_kwarg_cleanup.py': "# Test that heap values are properly cleaned up when duplicate kwarg error occurs\ndef f(a, b):\n    return a\n\n\n# The list [1, 2, 3] should be cleaned up when the error occurs\n# because 'a' is passed both positionally and by keyword\nf([1, 2, 3], a=[4, 5])\n# Raise=TypeError(\"f() got multiple values for argument 'a'\")\n",
  'function__err_duplicate_param.py': "# Duplicate parameter names in a function definition are a SyntaxError.\n# Previously this panicked the VM at call time because `prepare.rs` sized\n# the frame's namespace from the unique name count (HashMap::len) but\n# resolved the duplicate to a NamespaceId from the positional index,\n# so `load_local` indexed past the allocated stack slots.\ndef f(x, x):\n    return x\n# Raise=SyntaxError(\"duplicate argument 'x' in function definition\")\n",
  'function__err_kwonly_as_positional.py': "# Test: keyword-only argument passed positionally\ndef f(*, a, b):\n    return a + b\n\n\nf(1, 2)\n# Raise=TypeError('f() takes 0 positional arguments but 2 were given')\n",
  'function__err_missing_all_posonly.py': "# Test: missing all positional-only arguments\ndef f(a, b, /):\n    return a + b\n\n\nf()\n# Raise=TypeError(\"f() missing 2 required positional arguments: 'a' and 'b'\")\n",
  'function__err_missing_heap_cleanup.py': "# Test that heap values are properly cleaned up when missing required arg error occurs\ndef f(a, b, c):\n    return a\n\n\n# The list [1, 2, 3] should be cleaned up when the error occurs\n# because 'c' is missing\nf([1, 2, 3], [4, 5])\n# Raise=TypeError(\"f() missing 1 required positional argument: 'c'\")\n",
  'function__err_missing_kwonly.py': "# Test: missing required keyword-only argument\ndef f(a, *, b):\n    return a + b\n\n\nf(1)\n# Raise=TypeError(\"f() missing 1 required keyword-only argument: 'b'\")\n",
  'function__err_missing_posonly_with_kwarg.py': "# Test: missing positional-only when keyword is provided for other param\ndef f(a, /, b):\n    return a + b\n\n\nf(b=2)\n# Raise=TypeError(\"f() missing 1 required positional argument: 'a'\")\n",
  'function__err_missing_with_posonly.py': "# Test: missing required argument with positional-only params\ndef f(a, b, /, c):\n    return a + b + c\n\n\nf(1, 2)\n# Raise=TypeError(\"f() missing 1 required positional argument: 'c'\")\n",
  'function__err_posonly_as_kwarg.py': "# Test: positional-only parameter passed as keyword argument\ndef f(a, b, /, c):\n    return a + b + c\n\n\nf(1, b=2, c=3)\n# Raise=TypeError(\"f() got some positional-only arguments passed as keyword arguments: 'b'\")\n",
  'function__err_posonly_first_as_kwarg.py': "# Test: first positional-only parameter passed as keyword argument\ndef f(a, /, b):\n    return a + b\n\n\nf(a=1, b=2)\n# Raise=TypeError(\"f() got some positional-only arguments passed as keyword arguments: 'a'\")\n",
  'function__err_too_many_posonly.py': "# Test: too many positional arguments with positional-only params\ndef f(a, b, /):\n    return a + b\n\n\nf(1, 2, 3)\n# Raise=TypeError('f() takes 2 positional arguments but 3 were given')\n",
  'function__err_too_many_with_kwonly.py': "# Test: too many positional arguments with keyword-only params\ndef f(a, *, b):\n    return a + b\n\n\nf(1, 2, b=3)\n# Raise=TypeError('f() takes 1 positional argument but 2 positional arguments (and 1 keyword-only argument) were given')\n",
  'function__err_unexpected_kwarg.py': "# Test: unexpected keyword argument\ndef f(a, b):\n    return a + b\n\n\nf(1, 2, c=3)\n# Raise=TypeError(\"f() got an unexpected keyword argument 'c'\")\n",
  'function__err_unexpected_kwarg_cleanup.py': "# Test that heap values are properly cleaned up when unexpected kwarg error occurs\ndef f(a, b):\n    return a\n\n\n# The list [1, 2, 3] should be cleaned up when the error occurs\n# because 'c' is an unexpected keyword argument\nf([1, 2, 3], [4, 5], c=[6, 7])\n# Raise=TypeError(\"f() got an unexpected keyword argument 'c'\")\n",
  'function__err_unexpected_kwarg_quote.py': "def f(a):\n    pass\n\n\nf(1, **{\"foo'\": 2})\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"function__err_unexpected_kwarg_quote.py\", line 5, in <module>\n    f(1, **{\"foo'\": 2})\n    ~~~~~~~~~~~~~~~~~~~\nTypeError: f() got an unexpected keyword argument 'foo''\n\"\"\"\n",
  'function__err_unexpected_kwarg_simple.py': "# Test: unexpected keyword argument on single-param function\ndef f(a):\n    return a\n\n\nf(1, b=2)\n# Raise=TypeError(\"f() got an unexpected keyword argument 'b'\")\n",
  'function__err_unpack_duplicate_arg.py': "def f(a, b):\n    return a + b\n\n\nf(a=1, **{'a': 2})\n# Raise=TypeError(\"f() got multiple values for keyword argument 'a'\")\n",
  'function__err_unpack_duplicate_heap.py': "# Test that heap values are cleaned up when duplicate kwargs error occurs\ndef f(a, b):\n    return a\n\n\n# The list value in the dict should be cleaned up when the error occurs\nf(a=[1, 2, 3], **{'a': [4, 5, 6]})\n# Raise=TypeError(\"f() got multiple values for keyword argument 'a'\")\n",
  'function__err_unpack_int.py': "def f(a, b):\n    return a + b\n\n\nf(1, **42)\n# Raise=TypeError('f() argument after ** must be a mapping, not int')\n",
  'function__err_unpack_nonstring_key.py': "def foo(a):\n    return a\n\n\nfoo(**{1: 'value'})\n# Raise=TypeError('keywords must be strings')\n",
  'function__err_unpack_not_mapping.py': "def f(a, b):\n    return a + b\n\n\nf(1, **[2])\n# Raise=TypeError('f() argument after ** must be a mapping, not list')\n",
  'function__kwargs_unpacking.py': "# === Basic **kwargs unpacking ===\ndef greet(name, greeting):\n    return f'{greeting}, {name}!'\n\n\nopts = {'greeting': 'Hi'}\nassert greet('Alice', **opts) == 'Hi, Alice!'\n\n# === Dict literal unpacking ===\nassert greet('Charlie', **{'greeting': 'Hey'}) == 'Hey, Charlie!'\n\n\n# === Multiple kwargs in unpacked dict ===\ndef format_msg(msg, prefix, suffix):\n    return f'{prefix}{msg}{suffix}'\n\n\nassert format_msg('test', **{'prefix': '[', 'suffix': ']'}) == '[test]'\n\n# === Combining regular kwargs with **kwargs ===\nassert format_msg('hello', prefix='> ', **{'suffix': '!'}) == '> hello!'\n\n\n# === **kwargs with positional args ===\ndef add_all(a, b, c):\n    return a + b + c\n\n\nassert add_all(1, 2, **{'c': 3}) == 6\nassert add_all(1, **{'b': 2, 'c': 3}) == 6\n\n# === Variable dict unpacking ===\nsettings = {'prefix': '>>> ', 'suffix': ' <<<'}\nassert format_msg('output', **settings) == '>>> output <<<'\n\n\n# === Unpacking with keyword-only args ===\ndef kwonly_func(a, *, b, c):\n    return a + b + c\n\n\nassert kwonly_func(1, **{'b': 2, 'c': 3}) == 6\n\n\n# === Empty dict unpacking with all args provided ===\ndef simple(x, y):\n    return x + y\n\n\nassert simple(1, 2, **{}) == 3\n\n\n# === All kwargs from unpacking ===\ndef all_kwargs(a, b, c):\n    return a * 100 + b * 10 + c\n\n\nassert all_kwargs(**{'a': 1, 'b': 2, 'c': 3}) == 123\nassert all_kwargs(**{'c': 7, 'a': 4, 'b': 5}) == 457\n\n\n# === Dynamic **kwargs keys ===\ndef kwonly_echo(*, keyword):\n    return keyword\n\n\nkey_name = 'k' + 'e' + 'y' + 'w' + 'o' + 'r' + 'd'\nassert kwonly_echo(**{key_name: 'dynamic'}) == 'dynamic'\n\n\n# ============================================================\n# *args unpacking tests (function calls)\n# ============================================================\n\n\n# === *args with zero args ===\ndef no_args():\n    return 'ok'\n\n\nassert no_args(*[]) == 'ok'\nassert no_args(*()) == 'ok'\n\n\n# === *args with one arg ===\ndef one_arg(x):\n    return x * 2\n\n\nassert one_arg(*[5]) == 10\nassert one_arg(*(7,)) == 14\n\n\n# === *args with two args ===\ndef two_args(a, b):\n    return a + b\n\n\nassert two_args(*[1, 2]) == 3\nassert two_args(*(3, 4)) == 7\n\n\n# === *args with three+ args ===\ndef many_args(a, b, c, d):\n    return a + b + c + d\n\n\nassert many_args(*[1, 2, 3, 4]) == 10\nassert many_args(*(10, 20, 30, 40)) == 100\n\n\n# === Mixed positional and *args ===\nassert two_args(1, *[2]) == 3\nassert many_args(1, 2, *[3, 4]) == 10\n\n\n# === *args with heap-allocated values ===\ndef list_arg(lst):\n    return len(lst)\n\n\nmy_list = [1, 2, 3]\nassert list_arg(*[my_list]) == 3\n\n\n# ============================================================\n# Combined *args and **kwargs (function calls)\n# ============================================================\n\n\n# === *args and **kwargs together ===\ndef mixed_func(a, b, c):\n    return f'{a}-{b}-{c}'\n\n\nassert mixed_func(*[1], **{'b': 2, 'c': 3}) == '1-2-3'\nassert mixed_func(*[1, 2], **{'c': 3}) == '1-2-3'\n\n\n# === *args tuple with **kwargs ===\nargs_tuple = (10, 20)\nkwargs_dict = {'c': 30}\nassert many_args(*args_tuple, **kwargs_dict, d=40) == 100\n\n\n# === Empty *args with **kwargs ===\nassert mixed_func(*[], **{'a': 'x', 'b': 'y', 'c': 'z'}) == 'x-y-z'\n\n\n# === *args with empty **kwargs ===\nassert two_args(*[5, 6], **{}) == 11\n\n\n# === All combinations: pos, *args, kwargs, **kwargs ===\ndef full_func(a, b, c, d):\n    return a * 1000 + b * 100 + c * 10 + d\n\n\nassert full_func(1, *[2], c=3, **{'d': 4}) == 1234\n\n\n# === *args with heap values and **kwargs ===\ndef heap_func(lst, dct):\n    return len(lst) + len(dct)\n\n\nlist_val = [1, 2, 3]\ndict_val = {'a': 1}\nassert heap_func(*[list_val], **{'dct': dict_val}) == 4\n\n\n# === Both *args and **kwargs empty ===\nassert no_args(*[], **{}) == 'ok'\n",
  'function__ops.py': "# === Basic function calls ===\ndef f_no_args():\n    return 1\n\n\nassert f_no_args() == 1\n\n\ndef f_one_arg(x):\n    return x\n\n\nassert f_one_arg(42) == 42\n\n\ndef add(a, b):\n    return a + b\n\n\nassert add(1, 2) == 3\n\n\ndef sum3(a, b, c):\n    return a + b + c\n\n\nassert sum3(1, 2, 3) == 6\n\n\n# === Local variables ===\ndef f_local():\n    x = 42\n    return x\n\n\nassert f_local() == 42\n\n\ndef f_local_from_arg(x):\n    y = x + 1\n    return y\n\n\nassert f_local_from_arg(10) == 11\n\n\ndef f_local_list():\n    items = [1, 2, 3]\n    return items\n\n\nassert f_local_list() == [1, 2, 3]\n\n\ndef f_local_modify_list():\n    items = [1, 2]\n    items.append(3)\n    return items\n\n\nassert f_local_modify_list() == [1, 2, 3]\n\n\ndef f_local_multiple():\n    a = 1\n    b = 2\n    c = 3\n    return a + b + c\n\n\nassert f_local_multiple() == 6\n\n\ndef f_local_reassign():\n    x = 1\n    x = 2\n    x = 3\n    return x\n\n\nassert f_local_reassign() == 3\n\n\n# === Nested functions ===\ndef nested_basic():\n    def bar():\n        return 1\n\n    return bar() + 1\n\n\nassert nested_basic() == 2\n\n\ndef nested_deep():\n    def level2():\n        def level3():\n            return 42\n\n        return level3()\n\n    return level2()\n\n\nassert nested_deep() == 42\n\n\ndef nested_multiple_calls():\n    def inner():\n        return 10\n\n    return inner() + inner() + inner()\n\n\nassert nested_multiple_calls() == 30\n\n\ndef nested_two_inner():\n    def add():\n        return 1\n\n    def sub():\n        return 2\n\n    return add() + sub()\n\n\nassert nested_two_inner() == 3\n\n\ndef nested_with_args(x):\n    def inner(y):\n        return y + y\n\n    return inner(x) + 1\n\n\nassert nested_with_args(5) == 11\n\n\n# === Function equality ===\ndef eq_test():\n    return 1\n\n\ndef eq_test2():\n    return 1\n\n\n# Same function is equal to itself\nassert eq_test == eq_test\nassert not (eq_test != eq_test), 'function not-not-equals itself'\n\n# Different functions are not equal (even with same body)\nassert not (eq_test == eq_test2), 'different functions not equal'\nassert eq_test != eq_test2\n\n# Function assigned to variable is still equal\nf_alias = eq_test\nassert f_alias == eq_test\nassert eq_test == f_alias\n\n\n# === Builtin equality ===\n# Same builtin is equal to itself\nassert len == len\nassert print == print\nassert not (len != len), 'builtin not-not-equals itself'\n\n# Builtin identity (is)\nassert print is print\nassert len is len\nassert not (len is print), 'len is not print'\n\n# Different builtins are not equal\nassert not (len == print), 'different builtins not equal'\nassert len != print\n\n# Builtin assigned to variable is still equal\nlen_alias = len\nassert len_alias == len\nassert len_alias is len\n\n\n# === Exception type equality ===\n# Note: Using == instead of 'is' to explicitly test the __eq__ implementation\nassert ValueError == ValueError\nassert TypeError == TypeError\nassert not (ValueError != ValueError), 'exc type not-not-equals itself'\n\nassert not (ValueError == TypeError), 'different exc types not equal'\nassert ValueError != TypeError\n\nexc_alias = ValueError\nassert exc_alias == ValueError\n\n\n# === Closure equality ===\ndef make_adder(n):\n    def adder(x):\n        return x + n\n\n    return adder\n\n\nadd1 = make_adder(1)\nadd2 = make_adder(2)\nadd1_again = make_adder(1)\n\n# Same closure instance equals itself\nassert add1 == add1\nassert not (add1 != add1), 'closure not-not-equals itself'\n\n# Different closure instances are not equal (even with same captured value)\nassert not (add1 == add1_again), 'different closure instances not equal'\nassert add1 != add1_again\n\n# Different closure instances with different captured values\nassert not (add1 == add2), 'closures with diff captured values not equal'\nassert add1 != add2\n\n\n# === Cross-type inequality ===\ndef cross_test():\n    return 1\n\n\nassert not (cross_test == len), 'function not equal to builtin'\nassert not (len == cross_test), 'builtin not equal to function'\nassert not (cross_test == ValueError), 'function not equal to exc type'\nassert not (ValueError == cross_test), 'exc type not equal to function'\nassert not (len == ValueError), 'builtin not equal to exc type'\nassert not (ValueError == len), 'exc type not equal to builtin'\n\n# Callables not equal to other types\nassert not (len == 1), 'builtin not equal to int'\nassert not (len == 'len'), 'builtin not equal to string'\nassert not (cross_test == None), 'function not equal to None'\nassert not (ValueError == None), 'exc type not equal to None'\n\n\n# === Parameter shadowing global variables ===\n# Function parameters should shadow global variables with the same name\nx = 5\n\n\ndef shadow_single(x):\n    return x + 1\n\n\n# When called with 10, param x=10 should be used, not global x=5\nassert shadow_single(10) == 11\n\ny = 3\n\n\ndef shadow_multiple(x, y):\n    return x + y\n\n\n# When called with (20, 30), params should be used, not globals x=5, y=3\nassert shadow_multiple(20, 30) == 50\n\n\ndef shadow_uses_global_too(x):\n    # x is param, y is global\n    return x + y\n\n\n# x=100 (param), y=3 (global), so 100 + 3 = 103\nassert shadow_uses_global_too(100) == 103\n\n\ndef shadow_with_default(x=99):\n    return x + 1\n\n\n# When called with argument, param shadows global\nassert shadow_with_default(10) == 11\n# When called without argument, default is used (not global)\nassert shadow_with_default() == 100\n\n\n# Global is still accessible outside the function\nassert x == 5\nassert y == 3\n\n\n# Verify global can still be used as argument\ndef double(x):\n    return x * 2\n\n\nassert double(x) == 10\n\n\n# === Exact positional calls ===\ndef exact_heap_args(first, second, /):\n    local = [first, second]\n    return local\n\n\nfirst = [1]\nsecond = {'value': 2}\nexact_result = exact_heap_args(first, second)\nassert exact_result[0] is first\nassert exact_result[1] is second\n\ntry:\n    exact_heap_args(first)\n    assert False, 'expected TypeError for missing positional argument'\nexcept TypeError as exc:\n    assert str(exc) == \"exact_heap_args() missing 1 required positional argument: 'second'\"\n\n\n# A parameter captured by an inner function requires the regular cell setup path.\ndef exact_call_with_cell(value):\n    def read():\n        return value\n\n    return read()\n\n\nassert exact_call_with_cell(42) == 42\n",
  'function__return_none.py': "# === Bare return statement ===\n# Test functions with bare return (no value)\n\n\ndef early_exit():\n    return\n\n\nassert early_exit() is None\n\n\ndef conditional_early_exit(x):\n    if x < 0:\n        return\n    return x * 2\n\n\nassert conditional_early_exit(-5) is None\nassert conditional_early_exit(5) == 10\n\n\ndef multiple_bare_returns(x):\n    if x == 0:\n        return\n    if x == 1:\n        return\n    return x\n\n\nassert multiple_bare_returns(0) is None\nassert multiple_bare_returns(1) is None\nassert multiple_bare_returns(2) == 2\n\n\ndef nested_bare_return():\n    def inner():\n        return\n\n    return inner()\n\n\nassert nested_bare_return() is None\n",
  'function__signatures.py': "# === Basic functions ===\ndef simple(a, b, c):\n    return a + b + c\n\n\nassert simple(1, 2, 3) == 6\nassert simple(10, 20, 30) == 60\n\n\n# === Positional-only parameters ===\ndef pos_only(a, b, /, c):\n    return a + b + c\n\n\nassert pos_only(1, 2, 3) == 6\nassert pos_only(5, 5, 5) == 15\nassert pos_only(5, 5, c=5) == 15\n\n\n# === All positional-only ===\ndef all_pos_only(a, b, c, /):\n    return a + b + c\n\n\nassert all_pos_only(1, 2, 3) == 6\n\n\n# === Multiple parameter groups ===\ndef multi_group(a, /, b, c):\n    return f'a={a} b={b} c={c}'\n\n\nassert multi_group(1, 2, 3) == 'a=1 b=2 c=3'\nassert multi_group(1, b=2, c=3) == 'a=1 b=2 c=3'\nassert multi_group(1, c=3, b=2) == 'a=1 b=2 c=3'\n\n\n# === Call-site *args unpacking ===\ndef collect_all(*values):\n    return values\n\n\nsource_tuple = (1, 2, 3)\nassert collect_all(*source_tuple) == (1, 2, 3)\n\nsource_list = [4, 5]\nassert collect_all(0, *source_list) == (0, 4, 5)\n",
  'function__too_few_args_all.py': "def f(a, b, c):\n    return a + b + c\n\n\nf()\n# Raise=TypeError(\"f() missing 3 required positional arguments: 'a', 'b', and 'c'\")\n",
  'function__too_few_args_one.py': "def f(x):\n    return x\n\n\nf()\n# Raise=TypeError(\"f() missing 1 required positional argument: 'x'\")\n",
  'function__too_few_args_two.py': "def f(a, b):\n    return a + b\n\n\nf(1)\n# Raise=TypeError(\"f() missing 1 required positional argument: 'b'\")\n",
  'function__too_many_args_one.py': "def f(x):\n    return x\n\n\nf(1, 2)\n# Raise=TypeError('f() takes 1 positional argument but 2 were given')\n",
  'function__too_many_args_two.py': "def f(a, b):\n    return a + b\n\n\nf(1, 2, 3)\n# Raise=TypeError('f() takes 2 positional arguments but 3 were given')\n",
  'function__too_many_args_zero.py': "def f():\n    return 1\n\n\nf(42)\n# Raise=TypeError('f() takes 0 positional arguments but 1 was given')\n",
  'functools__gc.py': "# Cycle-collector interaction: a `partial` holds its arguments directly, so a\n# cycle through one is only collectable by tracing `for_each_child_id`. Smoke\n# coverage only — under-tracing leaks silently and nothing here notices;\n# `refcount__functools_partial.py` is what verifies the hooks.\n# `gc.collect()` returns different counts on CPython and Monty, so it isn't asserted.\nimport gc\n\nimport functools\n\n\ndef target(*args, **kwargs):\n    return (args, kwargs)\n\n\ndef arg_cycle():\n    # The partial holds the list, the list holds the partial: unreachable once\n    # this returns, and only collectable by tracing through the partial.\n    items = []\n    items.append(functools.partial(target, items))\n    return len(items)\n\n\ndef keyword_cycle():\n    # Same, through a bound keyword value rather than a positional.\n    items = []\n    items.append(functools.partial(target, k=items))\n    return len(items)\n\n\ndef func_cycle():\n    # The wrapped callable is traced too: here the partial's `func` is a closure\n    # over the list that holds the partial.\n    items = []\n\n    def closure():\n        return len(items)\n\n    items.append(functools.partial(closure))\n    return len(items)\n\n\nassert arg_cycle() == 1\nassert keyword_cycle() == 1\nassert func_cycle() == 1\ngc.collect()\n\n# Still reachable after the collection, so nothing above was condemned early.\nlive = []\nlive.append(functools.partial(target, live))\ngc.collect()\nassert live[0]()[0][0] is live\n",
  'functools__partial.py': "import functools\nimport sys\n\n\n# === partial ===\ndef target(a, b=1, *args, **kwargs):\n    return (a, b, args, kwargs)\n\n\nbound = functools.partial(target, 1)\nassert bound() == (1, 1, (), {})\nassert bound(2) == (1, 2, (), {})\nassert bound(2, 3, c=4) == (1, 2, (3,), {'c': 4})\n\n# bound positionals come before the call's own\nassert functools.partial(target, 1, 2, 3)(4) == (1, 2, (3, 4), {})\n\n# call keywords replace bound ones\nkw = functools.partial(target, 1, b=2)\nassert kw() == (1, 2, (), {})\nassert kw(b=9) == (1, 9, (), {})\nassert kw(c=3) == (1, 2, (), {'c': 3})\n\n# a bound keyword that the call also fills positionally is an error, as it\n# would be with the arguments written out\ntry:\n    kw(3)\n    assert False, 'expected the call to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"target() got multiple values for argument 'b'\"\n\n# === partial attributes ===\nassert bound.func is target\nassert bound.args == (1,)\nassert bound.keywords == {}\nassert kw.args == (1,)\nassert kw.keywords == {'b': 2}\nassert functools.partial(target, 1, 2, x=3, y=4).keywords == {'x': 3, 'y': 4}\n\ntry:\n    kw.bogus\n    assert False, 'expected the attribute lookup to fail'\nexcept AttributeError as exc:\n    assert str(exc) == \"'functools.partial' object has no attribute 'bogus'\"\n\n# === partial nesting ===\n# a partial wrapping a partial is flattened at construction\ninner = functools.partial(target, 1, b=2)\nouter = functools.partial(inner, 3, b=4)\nassert outer.func is target\nassert outer.args == (1, 3)\nassert outer.keywords == {'b': 4}\nassert functools.partial(functools.partial(target, 1)).args == (1,)\nassert functools.partial(functools.partial(target, 1), 2)() == (1, 2, (), {})\n\n# === partial identity and truthiness ===\nassert type(bound) is functools.partial\nassert isinstance(bound, functools.partial)\nassert bool(functools.partial(target, 1))\n# partials compare by identity, so two equivalent ones are not equal\nassert functools.partial(target, 1) != functools.partial(target, 1)\nassert bound == bound\n# ... and hash by identity too, so equivalent partials are distinct keys\nassert len({bound, kw, bound}) == 2\nassert {bound: 'a'}[bound] == 'a'\nassert len({functools.partial(target, 1), functools.partial(target, 1)}) == 2\n\n# === partial repr ===\nassert repr(functools.partial(int, '10')) == \"functools.partial(<class 'int'>, '10')\"\nassert repr(functools.partial(int)) == \"functools.partial(<class 'int'>)\"\nassert repr(functools.partial(int, '10', base=8)) == \"functools.partial(<class 'int'>, '10', base=8)\"\n\n# a bound argument holding the partial back reprs as `...` rather than recursing\nitems = []\nitems.append(functools.partial(int, items))\nassert repr(items[0]) == \"functools.partial(<class 'int'>, [...])\"\nassert repr(items) == \"[functools.partial(<class 'int'>, [...])]\"\nmapping = {}\nmapping['self'] = functools.partial(int, k=mapping)\nassert repr(mapping['self']) == \"functools.partial(<class 'int'>, k={'self': ...})\"\n\n# === partial as an ordinary callable ===\nassert list(map(functools.partial(pow, 2), [1, 2, 3])) == [2, 4, 8]\nassert sorted([(1, 'b'), (2, 'a')], key=functools.partial(lambda i, t: t[i], 1)) == [(2, 'a'), (1, 'b')]\nassert functools.reduce(functools.partial(lambda scale, a, b: scale * (a + b), 2), [1, 2, 3]) == 18\n\n\n# === partial as a descriptor ===\n# one stored on a class binds the instance after the arguments it already\n# carries, as it does in CPython 3.14\nclass Holder:\n    prefixed = functools.partial(target, 'p')\n\n    def __init__(self):\n        self.own = functools.partial(target, 'o')\n\n\nholder = Holder()\nassert holder.prefixed() == ('p', holder, (), {})\nassert holder.prefixed(9) == ('p', holder, (9,), {})\nassert getattr(holder, 'prefixed')() == ('p', holder, (), {})\n# reached through the class there is no instance to bind\nassert Holder.prefixed() == ('p', 1, (), {})\nassert Holder.prefixed.args == ('p',)\n# only a class attribute is a descriptor, so an instance one binds nothing\nassert holder.own() == ('o', 1, (), {})\n\n# === partial over builtins ===\n# builtins reached through a partial must see the same argument shapes as a\n# direct call does, whatever their arity\nassert functools.partial(len)([1, 2, 3]) == 3\nassert functools.partial(abs)(-4) == 4\nassert functools.partial(list)() == []\nassert functools.partial(list)('ab') == ['a', 'b']\nassert functools.partial(isinstance)(1, int)\nassert functools.partial(int, '10')() == 10\nassert functools.partial(max, 1)(2) == 2\nassert functools.partial(round)(1.234, 2) == 1.23\n\n# === partial construction errors ===\ntry:\n    functools.partial()\n    assert False, 'expected partial to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"type 'partial' takes at least one argument\"\n\ntry:\n    functools.partial(func=target)\n    assert False, 'expected partial to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"type 'partial' takes at least one argument\"\n\ntry:\n    functools.partial(5)\n    assert False, 'expected partial to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'the first argument must be callable'\n\n\n# === deep partial chains are bounded, not a stack overflow ===\n# A partial stored as a class attribute binds as a bound method whose `__func__`\n# is another partial, so calling the outermost one nests on the interpreter's own\n# call stack without pushing a Python frame. Monty caps that at a fixed native\n# re-entry depth; CPython runs until its C stack gives out (see\n# ./limitations/functools.md).\ndef chain(depth):\n    def count(*args):\n        return len(args)\n\n    cur = count\n    for _ in range(depth):\n\n        class Holder:\n            bound = functools.partial(cur)\n\n        cur = Holder().bound\n    return cur\n\n\nassert chain(5)() == 5\n\nif sys.platform == 'monty':\n    try:\n        chain(30)()\n        assert False, 'expected the deep partial chain to raise'\n    except RecursionError as exc:\n        assert str(exc) == 'maximum recursion depth exceeded'\nelse:\n    assert chain(30)() == 30\n",
  'functools__partial_external.py': "# call-external\n# Calling a `partial` goes through the ordinary call path, so a wrapped host\n# function still suspends to the host with the merged arguments — unlike\n# `reduce`, whose function runs in a context that cannot suspend (see\n# limitations/functools.md).\nimport functools\n\nadd_one = functools.partial(add_ints, 1)\nassert add_one(2) == 3\nassert add_one(10) == 11\n\n# The bound argument survives repeated calls and mixes with later positionals.\nassert functools.partial(add_ints, 20)(22) == 42\nassert functools.partial(concat_strings, 'a')('b') == 'ab'\n",
  'functools__reduce.py': "import functools\n\n# === reduce ===\nassert functools.reduce(lambda a, b: a + b, [1, 2, 3, 4]) == 10\nassert functools.reduce(lambda a, b: a + b, [1, 2, 3], 10) == 16\nassert functools.reduce(lambda a, b: a + b, [], 5) == 5\nassert functools.reduce(lambda a, b: a * b, range(1, 6)) == 120\nassert functools.reduce(lambda a, b: a + b, 'abc') == 'abc'\nassert functools.reduce(lambda a, b: a + b, {'x': 1, 'y': 2}) == 'xy'\n\n# a one-item iterable returns that item without calling the function\nassert functools.reduce(lambda a, b: 1 / 0, [7]) == 7\nassert functools.reduce(lambda a, b: 1 / 0, [], 7) == 7\n\n# `initial` is also accepted by keyword\nassert functools.reduce(lambda a, b: a + b, [1, 2], initial=10) == 13\n\n# the accumulator is threaded left to right\nassert functools.reduce(lambda a, b: (a, b), [1, 2, 3]) == ((1, 2), 3)\nassert functools.reduce(lambda a, b: a + [b], [1, 2], []) == [1, 2]\n\n\n# an exception from the function propagates unchanged\ndef raiser(a, b):\n    raise ValueError('inner')\n\n\ntry:\n    functools.reduce(raiser, [1, 2])\n    assert False, 'expected reduce to fail'\nexcept ValueError as exc:\n    assert str(exc) == 'inner'\n\ntry:\n    functools.reduce(lambda a, b: a, [])\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'reduce() of empty iterable with no initial value'\n\n# the callable is never checked up front, so an empty iterable wins\ntry:\n    functools.reduce(5, [])\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'reduce() of empty iterable with no initial value'\n\ntry:\n    functools.reduce(5, [1, 2])\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'int' object is not callable\"\n\ntry:\n    functools.reduce(lambda a, b: a, 5)\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'reduce() arg 2 must support iteration'\n\ntry:\n    functools.reduce(lambda a, b: a)\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'reduce() takes at least 2 positional arguments (1 given)'\n\ntry:\n    functools.reduce(lambda a, b: a, [1], 2, 3)\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'reduce() takes at most 3 arguments (4 given)'\n\ntry:\n    functools.reduce(lambda a, b: a, [1], bogus=1)\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"reduce() got an unexpected keyword argument 'bogus'\"\n\n# `function` and `iterable` are positional-only, so the arity error comes first\ntry:\n    functools.reduce(function=lambda a, b: a, iterable=[1])\n    assert False, 'expected reduce to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'reduce() takes at least 2 positional arguments (0 given)'\n",
  'global__error_assigned_before.py': "# Regression coverage for the `global X` ordering diagnostics, including the\n# CPython quirk reported in https://github.com/pydantic/monty/issues/423:\n# `import` bindings DO NOT count as \"assigned to before global declaration\"\n# even though every other binding form does.\n#\n# Each `def` below stresses one rule. The function bodies are never executed\n# — defining them is enough to trigger prepare-time scope validation. The\n# file ends with the one form that IS expected to raise a SyntaxError, which\n# the harness verifies through the `# Raise=` comment.\n\n\n# --- Import bindings are accepted by CPython ---------------------------\n# `import X`, `import X as Y`, and `from M import X [as Y]` are treated as\n# \"soft\" bindings that don't conflict with a subsequent `global` in the same\n# scope (issue #423). The `global` declaration takes precedence, making the\n# import effectively rebind the module-level name.\n\n\ndef import_plain_then_global():\n    import os\n\n    global os  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\ndef import_as_then_global():\n    import os as alias_plain\n\n    global alias_plain  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\ndef from_import_then_global():\n    from os import path\n\n    global path  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\ndef from_import_as_then_global():\n    from os import path as alias_path\n\n    global alias_path  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\n# --- Reads inside a nested scope don't pollute this scope --------------\n# Reads inside a `lambda` body or nested `def` happen in a sub-scope, so\n# they don't trigger this scope's \"used prior to\" check.\n\n\ndef lambda_read_then_global():\n    lambda: lambda_target\n    global lambda_target\n\n\ndef nested_def_read_then_global():\n    def nested_reader():\n        return nested_target\n\n    _ = nested_reader  # keep pyright happy about the nested def\n    global nested_target\n\n    def nested_target():\n        pass\n\n\n# --- The non-import binding form that DOES error -----------------------\n# A plain assignment before `global` is the canonical SyntaxError.\n\n\ndef f():\n    x = 1\n    global x  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\nf()\n# Raise=SyntaxError(\"name 'x' is assigned to before global declaration\")\n",
  'global__ops.py': "# === Basic global read/write ===\nx1 = 42\n\n\ndef read_explicit():\n    global x1\n    return x1\n\n\nassert read_explicit() == 42\n\n\nx2 = 1\n\n\ndef write_explicit():\n    global x2\n    x2 = 2\n\n\nwrite_explicit()\nassert x2 == 2\n\n\nx3 = 42\n\n\ndef read_implicit():\n    return x3  # no local x3, reads global\n\n\nassert read_implicit() == 42\n\n\n# === Multiple functions sharing global ===\ncounter1 = 0\n\n\ndef inc():\n    global counter1\n    counter1 = counter1 + 1\n\n\ndef get_counter():\n    return counter1\n\n\ninc()\ninc()\nassert get_counter() == 2\n\n\n# === Mutating global containers (no 'global' needed) ===\ndata1 = {'a': 1}\n\n\ndef add_dict_entry():\n    data1['b'] = 2\n\n\nadd_dict_entry()\nassert data1 == {'a': 1, 'b': 2}\n\n\nitems1 = [1, 2]\n\n\ndef append_list_item():\n    items1.append(3)\n\n\nappend_list_item()\nassert items1 == [1, 2, 3]\n\n\nitems2 = ['a', 'c']\n\n\ndef insert_list_item():\n    items2.insert(1, 'b')\n\n\ninsert_list_item()\nassert items2 == ['a', 'b', 'c']\n\n\nitems3 = []\n\n\ndef build_list():\n    items3.append(1)\n    items3.append(2)\n    items3.append(3)\n\n\nbuild_list()\nassert items3 == [1, 2, 3]\n\n\n# === Reassigning global containers (requires 'global') ===\nitems4 = [1, 2]\n\n\ndef replace_list():\n    global items4\n    items4 = [3, 4, 5]\n\n\nreplace_list()\nassert items4 == [3, 4, 5]\n\n\n# === Nested functions with global ===\nx4 = 1\n\n\ndef outer_global():\n    def inner():\n        global x4\n        x4 = 10\n\n    inner()\n\n\nouter_global()\nassert x4 == 10\n\n\nx5 = 42\n\n\ndef outer_read():\n    def inner():\n        return x5  # reads global\n\n    return inner()\n\n\nassert outer_read() == 42\n\n\n# === Shadowing ===\nx6 = 10\n\n\ndef shadow_local():\n    x6 = 20  # creates local (shadows global)\n    return x6\n\n\nassert shadow_local() == 20\n\n\nx7 = 10\n\n\ndef shadow_unchanged():\n    x7 = 99  # local\n    return x7\n\n\nassert shadow_unchanged() == 99\nassert x7 == 10\n\n\n# === `global X` for a name that doesn't yet exist at module level ===\n\n\ndef declare_then_write():\n    global ghost1\n    ghost1 = 5\n\n\ndeclare_then_write()\nassert ghost1 == 5\n\n\ndef declare_then_read():\n    global ghost2\n    return ghost2\n\n\ntry:\n    declare_then_read()\n    raise AssertionError('expected NameError for never-assigned global')\nexcept NameError as exc:\n    assert str(exc) == \"name 'ghost2' is not defined\"\n\n\n# === Forward reference to a later module-level binding ===\n\n\ndef read_late_value():\n    return late_value\n\n\nlate_value = 'bound'\nassert read_late_value() == 'bound'\n\n\n# === Late binding overrides parse-time builtin resolution ===\n\n\ndef call_min():\n    return min([3, 1, 2])\n\n\nassert call_min() == 1\n\n\ndef min(*args):\n    return 'shadowed'\n\n\nassert call_min() == 'shadowed'\n\n\n# === Module-scope shadowing builtins ===\n\nassert max(1, 2) == 2\n\n\ndef max(*args):\n    return 'shadowed-max'\n\n\nassert max(1, 2) == 'shadowed-max'\n\n\n# === Deeply nested `global X` ===\n\n\ndef deep_outer():\n    def deep_inner():\n        global deep_x\n        deep_x = 'reached-module'\n\n    deep_inner()\n\n\ndeep_outer()\nassert deep_x == 'reached-module'\n",
  'hash__dict_unhashable.py': "hash({})\n# Raise=TypeError(\"unhashable type: 'dict'\")\n",
  'hash__list_unhashable.py': "hash([1, 2, 3])\n# Raise=TypeError(\"unhashable type: 'list'\")\n",
  'hash__ops.py': "# === Hash returns int type ===\nassert isinstance(hash(42), int)\nassert isinstance(hash('hello'), int)\nassert isinstance(hash((1, 2, 3)), int)\nassert isinstance(hash(3.14), int)\n\n# === Hash consistency for same values ===\nassert hash(42) == hash(42)\nassert hash(-1) == hash(-1)\nassert hash(0) == hash(0)\nassert hash('hello') == hash('hello')\nassert hash('') == hash('')\nassert hash(b'hello') == hash(b'hello')\nassert hash(b'') == hash(b'')\nassert hash(None) == hash(None)\nassert hash(True) == hash(True)\nassert hash(False) == hash(False)\nassert hash((1, 2, 3)) == hash((1, 2, 3))\nassert hash(()) == hash(())\nassert hash((1,)) == hash((1,))\nassert hash(3.14) == hash(3.14)\nassert hash(0.0) == hash(0.0)\nassert hash(-0.0) == hash(-0.0)\nassert hash(...) == hash(...)\n\n# === Range hash consistency ===\nassert hash(range(10)) == hash(range(10))\nassert hash(range(0)) == hash(range(0))\nassert hash(range(1, 10)) == hash(range(1, 10))\nassert hash(range(1, 10, 2)) == hash(range(1, 10, 2))\nassert hash(range(-5, 5)) == hash(range(-5, 5))\n\n# === Different range values should hash differently ===\nassert hash(range(10)) != hash(range(11))\nassert hash(range(10)) != hash(range(1, 10))\nassert hash(range(10)) != hash(range(0, 10, 2))\nassert hash(range(1, 10, 2)) != hash(range(1, 10, 3))\n\n# === Different values should hash differently ===\nassert hash(1) != hash(2)\nassert hash('a') != hash('b')\nassert hash(b'a') != hash(b'b')\nassert hash((1, 2)) != hash((1, 3))\nassert hash((1, 2)) != hash((2, 1))\nassert hash(True) != hash(False)\nassert hash(3.14) != hash(2.71)\n\n# === Type differentiation for clearly different types ===\nassert hash(()) != hash('')\nassert hash('1') != hash(1)\nassert hash(b'1') != hash(1)\n\n# === Nested tuple hashing ===\nassert hash((1, (2, 3))) == hash((1, (2, 3)))\nassert hash((1, (2, 3))) != hash((1, (2, 4)))\nassert hash(((1, 2), (3, 4))) == hash(((1, 2), (3, 4)))\n\n# === String/bytes content equality across representations ===\n# Interned strings and heap strings with same content should hash the same\ns1 = 'test'\ns2 = 'te' + 'st'\nassert hash(s1) == hash(s2)\n\nb1 = b'test'\nb2 = b'te' + b'st'\nassert hash(b1) == hash(b2)\n\n\n# === Function hashing ===\ndef f():\n    pass\n\n\ndef g():\n    pass\n\n\nassert hash(f) == hash(f)\nassert hash(g) == hash(g)\nassert hash(f) != hash(g)\n\n# === Builtin function hashing ===\nassert hash(len) == hash(len)\nassert hash(print) == hash(print)\nassert hash(len) != hash(print)\n\n# === Builtin type hashing ===\nassert hash(int) == hash(int)\nassert hash(str) == hash(str)\nassert hash(int) != hash(str)\nassert hash(int) != hash(float)\n\n# === Exception type hashing ===\nassert hash(ValueError) == hash(ValueError)\nassert hash(TypeError) == hash(TypeError)\nassert hash(ValueError) != hash(TypeError)\n\n# === Dict key behavior with hashes ===\n# Verify that hash consistency works with dict lookups\nd = {}\nd[42] = 'int'\nd['hello'] = 'str'\nd[(1, 2)] = 'tuple'\nd[range(5)] = 'range'\nd[3.14] = 'float'\nd[None] = 'none'\n\nassert d[42] == 'int'\nassert d['hello'] == 'str'\nassert d[(1, 2)] == 'tuple'\nassert d[range(5)] == 'range'\nassert d[3.14] == 'float'\nassert d[None] == 'none'\n\n# === Multiple ranges as dict keys ===\nrd = {}\nrd[range(5)] = 'a'\nrd[range(10)] = 'b'\nrd[range(1, 5)] = 'c'\nrd[range(0, 5, 2)] = 'd'\n\nassert rd[range(5)] == 'a'\nassert rd[range(10)] == 'b'\nassert rd[range(1, 5)] == 'c'\nassert rd[range(0, 5, 2)] == 'd'\nassert len(rd) == 4\n\n\n# === Functions as dict keys ===\ndef key_fn():\n    pass\n\n\nfd = {}\nfd[key_fn] = 'func_value'\nassert fd[key_fn] == 'func_value'\n\n# === Builtins as dict keys ===\nbd = {}\nbd[len] = 'len_value'\nbd[print] = 'print_value'\nassert bd[len] == 'len_value'\nassert bd[print] == 'print_value'\nassert len(bd) == 2\n\n# === Types as dict keys ===\ntd = {}\ntd[int] = 'int_type'\ntd[str] = 'str_type'\ntd[ValueError] = 'value_error'\nassert td[int] == 'int_type'\nassert td[str] == 'str_type'\nassert td[ValueError] == 'value_error'\n\n# Types which compare equal should hash the same\nassert hash(1) == hash(True) and 1 == True, 'int 1 and bool True hash and compare equal'\nassert hash(0) == hash(False) and 0 == False, 'int 0 and bool False hash and compare equal'\nassert hash(-0.0) == hash(0.0) and -0.0 == 0.0, 'float -0.0 and 0.0 hash and compare equal'\nassert hash(1) == hash(1.0) and 1 == 1.0, 'int 1 and float 1.0 hash and compare equal'\nassert hash(0) == hash(0.0) and 0 == 0.0, 'int 0 and float 0.0 hash and compare equal'\nassert hash(0.0) == hash(False) and 0.0 == False, 'float 0.0 and bool False hash and compare equal'\nassert hash(1.0) == hash(True) and 1.0 == True, 'float 1.0 and bool True hash and compare equal'\n",
  'id__bytes_literals_distinct.py': "# xfail=cpython\nid(b'test') == id(b'test')\n# Return=False\n",
  'id__int_copy_distinct.py': "# value-based identity: same value = same id\nx = 100\ny = x\nid(x) == id(y)\n# Return=True\n",
  'id__is_number_is_number.py': "# value-based identity: same value = same identity\n1 is 1\n# Return=True\n",
  'id__non_overlapping_lifetimes_distinct_types.py': "# xfail=cpython\n# === Heap types may have the same id if lifetimes do not overlap ===\n# See https://docs.python.org/3/library/functions.html#id\n# for Cpython it happens to be the case that for different types they end\n# up being allocated in different memory locations, but this is not guaranteed by the language spec\nassert id([]) == id([])\nassert id([]) == id({})\nassert id([]) == id((1,))\nassert id((1, 2)) == id((1, 2))\nassert id([1, 2]) == id([1, 2])\n",
  'id__non_overlapping_lifetimes_same_types.py': "# === Heap types may have the same id if lifetimes do not overlap ===\n# See https://docs.python.org/3/library/functions.html#id\nassert id([]) == id([])\nassert id({}) == id({})\nassert id((1, 2)) == id((1, 2))\nassert id([1, 2]) == id([1, 2])\n",
  'id__ops.py': "# === id() returns int type ===\nassert isinstance(id(None), int)\nassert isinstance(id([]), int)\nassert isinstance(id('hello'), int)\nassert isinstance(id(42), int)\n\n# === Identity operator (is) ===\nassert (True is True) == True\nassert (False is False) == True\nassert (None is None) == True\nassert (... is ...) == True\n\n# === Identity operator (is not) ===\nassert (True is not True) == False\nassert (True is not False) == True\n\n# === Singleton identity ===\nassert id(None) == id(None)\nassert id(True) == id(True)\nassert id(False) == id(False)\nassert id(...) == id(...)\n\n# bool and int are distinct\nassert id(True) != id(1)\nassert id(False) != id(0)\n\n# distinct singletons\nassert id(None) != id(True)\nassert id(None) != id(False)\nassert id(None) != id(...)\n\n# === Integer identity ===\nassert id(10) != id(20)\n\n# === Float identity ===\nassert id(1.0) != id(2.0)\n\n# === List assignment shares identity ===\nlst = [1, 2]\nref = lst\nassert id(lst) == id(ref)\nassert lst is ref\n\n# === Variable identity is stable ===\nlst = [1, 2]\nassert id(lst) == id(lst)\n\n# === List mutation preserves identity ===\na = [1, 2]\nb = a\nb.append(3)\nassert a is b\n\n# === Mixed types have distinct ids ===\nassert id(1) != id('1')\n\n# === Tuple singleton is guaranteed to have a unique id ===\nassert id([]) != id(())\nassert id({}) != id(())\nassert id(1) != id(())\n\n# === Multiple refs share id ===\nx = [1, 2]\ny = x\nz = y\nassert id(x) == id(y)\nassert id(y) == id(z)\n\n# === String assignment shares identity ===\ns = 'hello'\nr = s\nassert id(s) == id(r)\n\n# === Bytes assignment shares identity ===\nb = b'hello'\nr = b\nassert id(b) == id(r)\n\n# === Tuple assignment shares identity ===\nt = (1, 2)\nr = t\nassert id(t) == id(r)\n\n# === Boolean is tests ===\nassert (True is True) == True\nassert (False is False) == True\n\n# === Array is test ===\na = [1, 2]\nb = a\nassert (a is b) == True\nassert (a is [1, 2]) == False\n\n# === None is tests ===\nx = None\nassert (x is None) == True\nassert (1 is None) == False\n",
  'id__str_literals_same.py': "# With string interning, identical literals have the same id\nid('hello') == id('hello')\n# Return=True\n",
  'if__elif_else.py': "# === Basic elif chains ===\n\n# if branch taken\nx = 0\nif True:\n    x = 1\nelif True:\n    x = 2\nassert x == 1\n\n# elif branch taken (first elif)\ny = 0\nif False:\n    y = 1\nelif True:\n    y = 2\nelif True:\n    y = 3\nassert y == 2\n\n# second elif taken\nz = 0\nif False:\n    z = 1\nelif False:\n    z = 2\nelif True:\n    z = 3\nassert z == 3\n\n# else branch taken after if\na = 0\nif False:\n    a = 1\nelse:\n    a = 2\nassert a == 2\n\n# else branch taken after elif chain\nb = 0\nif False:\n    b = 1\nelif False:\n    b = 2\nelif False:\n    b = 3\nelse:\n    b = 4\nassert b == 4\n\n# === Value-based conditions ===\n\nval = 5\n\nc = 0\nif val < 3:\n    c = 1\nelif val < 6:\n    c = 2\nelif val < 9:\n    c = 3\nelse:\n    c = 4\nassert c == 2\n\nval2 = 10\nd = 0\nif val2 < 3:\n    d = 1\nelif val2 < 6:\n    d = 2\nelif val2 < 9:\n    d = 3\nelse:\n    d = 4\nassert d == 4\n\n# === Multiple statements in branches ===\n\ne = 0\nf = 0\nif False:\n    e = 1\n    f = 1\nelif True:\n    e = 2\n    f = 2\nelse:\n    e = 3\n    f = 3\nassert e == 2\nassert f == 2\n\n# === Nested if inside elif ===\n\ng = 0\nif False:\n    g = 1\nelif True:\n    if True:\n        g = 100\n    else:\n        g = 200\nelse:\n    g = 3\nassert g == 100\n\n# nested if in else\nh = 0\nif False:\n    h = 1\nelif False:\n    h = 2\nelse:\n    if True:\n        h = 300\n    else:\n        h = 400\nassert h == 300\n\n# === Short-circuit evaluation ===\n\n# elif condition not evaluated if earlier branch taken\ncalled = False\n\n\ndef set_called():\n    global called\n    called = True\n    return True\n\n\ni = 0\nif True:\n    i = 1\nelif set_called():\n    i = 2\nassert i == 1\nassert called == False\n\n# reset and test elif evaluation\ncalled = False\nj = 0\nif False:\n    j = 1\nelif set_called():\n    j = 2\nassert j == 2\nassert called == True\n\n# === Empty body handling (pass) ===\n\nk = 0\nif False:\n    pass\nelif True:\n    k = 1\nelse:\n    pass\nassert k == 1\n\n# === Boolean expression conditions ===\n\nand_result = 0\nif False and True:\n    and_result = 1\nelif True and True:\n    and_result = 2\nelse:\n    and_result = 3\nassert and_result == 2\n\nor_result = 0\nif False or False:\n    or_result = 1\nelif False or True:\n    or_result = 2\nelse:\n    or_result = 3\nassert or_result == 2\n\n# === Multiple conditions with and ===\n\nn = 5\no = 0\nif n > 1 and n < 3:\n    o = 1\nelif n > 3 and n < 7:\n    o = 2\nelse:\n    o = 3\nassert o == 2\n\n# === Variable assignment in conditions (walrus operator style via temp var) ===\n\n# Test value propagation through elif chain\np = 0\ntemp = 10\nif temp > 20:\n    p = 1\nelif temp > 5:\n    p = 2\nelif temp > 0:\n    p = 3\nelse:\n    p = 4\nassert p == 2\n",
  'if__raise_elif.py': "if False:\n    pass\nelif True:\n    raise ValueError('in elif body')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"if__raise_elif.py\", line 4, in <module>\n    raise ValueError('in elif body')\nValueError: in elif body\n\"\"\"\n",
