  'try_except__all.py': "# === Basic exception catching ===\ncaught = False\ntry:\n    raise ValueError('test')\nexcept ValueError:\n    caught = True\nassert caught\n\n# === Exception variable binding ===\nmsg = None\ntry:\n    raise TypeError('the message')\nexcept TypeError as e:\n    msg = repr(e)\n# repr(e) returns \"TypeError('the message')\" - confirms we caught the right exception\nassert msg == \"TypeError('the message')\"\n\n# === Multiple handlers - first match wins ===\nwhich = None\ntry:\n    raise TypeError('type error')\nexcept ValueError:\n    which = 'value'\nexcept TypeError:\n    which = 'type'\nexcept:\n    which = 'bare'\nassert which == 'type'\n\n# === Bare except catches all ===\ncaught_bare = False\ntry:\n    raise KeyError('key')\nexcept:\n    caught_bare = True\nassert caught_bare\n\n# === Else block runs when no exception ===\nelse_ran = False\ntry:\n    x = 1\nexcept:\n    pass\nelse:\n    else_ran = True\nassert else_ran\n\n# === Else block does not run when exception occurs ===\nelse_ran_with_exc = True\ntry:\n    raise ValueError()\nexcept ValueError:\n    pass\nelse:\n    else_ran_with_exc = False\nassert else_ran_with_exc\n\n# === Finally always runs after try ===\nfinally_ran = False\ntry:\n    x = 1\nfinally:\n    finally_ran = True\nassert finally_ran\n\n# === Finally runs after exception caught ===\nfinally_after_catch = False\ntry:\n    raise ValueError()\nexcept ValueError:\n    pass\nfinally:\n    finally_after_catch = True\nassert finally_after_catch\n\n# === Bare raise re-raises current exception ===\ncaught_reraised = False\ntry:\n    try:\n        raise ValueError('original')\n    except ValueError:\n        raise  # bare raise\nexcept ValueError as e:\n    caught_reraised = repr(e) == \"ValueError('original')\"\nassert caught_reraised\n\n# === Nested try/except ===\nouter_caught = False\ninner_caught = False\ntry:\n    try:\n        raise ValueError('inner')\n    except ValueError:\n        inner_caught = True\n        raise TypeError('outer')\nexcept TypeError:\n    outer_caught = True\nassert inner_caught and outer_caught, 'nested exceptions should work'\n\n# === Exception base class matches all ===\ncaught_by_base = False\ntry:\n    raise KeyError('key')\nexcept Exception:\n    caught_by_base = True\nassert caught_by_base\n\n# === Tuple of exception types ===\ncaught_tuple = False\ntry:\n    raise TypeError('type')\nexcept (ValueError, TypeError):\n    caught_tuple = True\nassert caught_tuple\n\n\n# === Return in try with finally ===\ndef try_return_finally():\n    try:\n        return 1\n    finally:\n        pass\n\n\nassert try_return_finally() == 1\n\n\n# === Return in finally overrides try return ===\ndef finally_return_overrides():\n    try:\n        return 1\n    finally:\n        return 2  # type: ignore[returnInFinally]\n\n\nassert finally_return_overrides() == 2\n\n# === Exception in handler propagates ===\nhandler_exc_propagated = False\ntry:\n    try:\n        raise ValueError()\n    except ValueError:\n        raise TypeError('from handler')\nexcept TypeError as e:\n    handler_exc_propagated = repr(e) == \"TypeError('from handler')\"\nassert handler_exc_propagated\n\n\n# === Return in finally overrides exception from handler ===\ndef finally_return_overrides_handler_exc():\n    try:\n        raise TypeError('Error')\n    finally:\n        return 'finally wins handler'  # type: ignore\n\n\nassert finally_return_overrides_handler_exc() == 'finally wins handler'\n\n\ndef finally_return_overrides_handler_exc2():\n    try:\n        try:\n            raise ValueError('inner')\n        except ValueError:\n            raise TypeError('handler failure')\n    finally:\n        return 'finally wins handler'  # type: ignore\n\n\nassert finally_return_overrides_handler_exc2() == 'finally wins handler'\n\n\n# === Return in finally overrides exception from else ===\ndef finally_return_overrides_else_exc():\n    try:\n        try:\n            pass\n        except ValueError:\n            pass\n        else:\n            raise RuntimeError('else failure')\n    finally:\n        return 'finally wins else'  # type: ignore\n\n\nassert finally_return_overrides_else_exc() == 'finally wins else'\n\n# === Exception variable is cleared after handler ===\n# After except handler, the exception variable is deleted (Python 3 behavior)\ne_cleared = False\ntry:\n    try:\n        raise ValueError('test')\n    except ValueError as e:\n        pass\n    # e should be undefined here in Python 3, accessing it raises NameError\n    _ = e  # This should raise NameError\nexcept NameError:\n    e_cleared = True\nassert e_cleared\n\n# === Unhandled exception propagates ===\nunhandled_propagated = False\ntry:\n    try:\n        raise KeyError('unhandled')\n    except ValueError:\n        pass  # KeyError doesn't match, should propagate\nexcept KeyError as e:\n    unhandled_propagated = repr(e) == \"KeyError('unhandled')\"\nassert unhandled_propagated\n\n# === Finally runs before unhandled exception propagates ===\nfinally_before_propagate = False\ntry:\n    try:\n        raise KeyError('propagate')\n    except ValueError:\n        pass\n    finally:\n        finally_before_propagate = True\nexcept KeyError:\n    pass\nassert finally_before_propagate\n\n# === Exception in finally replaces original exception ===\nfinally_exc_wins = False\ntry:\n    try:\n        raise ValueError('original')\n    finally:\n        raise TypeError('from finally')\nexcept TypeError as e:\n    finally_exc_wins = repr(e) == \"TypeError('from finally')\"\nexcept ValueError:\n    finally_exc_wins = False  # Should not reach here\nassert finally_exc_wins\n\n# === Exception in else propagates ===\nelse_exc_propagated = False\ntry:\n    try:\n        pass  # No exception in try\n    except:\n        pass\n    else:\n        raise ValueError('from else')\nexcept ValueError as e:\n    else_exc_propagated = repr(e) == \"ValueError('from else')\"\nassert else_exc_propagated\n\n# === Finally runs after exception in else ===\nfinally_after_else_exc = False\ntry:\n    try:\n        pass\n    except:\n        pass\n    else:\n        raise ValueError('else error')\n    finally:\n        finally_after_else_exc = True\nexcept ValueError:\n    pass\nassert finally_after_else_exc\n\n# === Exception hierarchy: LookupError ===\n# LookupError should catch KeyError\ncaught_key_by_lookup = False\ntry:\n    raise KeyError('key')\nexcept LookupError:\n    caught_key_by_lookup = True\nassert caught_key_by_lookup\n\n# LookupError should catch IndexError\ncaught_index_by_lookup = False\ntry:\n    raise IndexError('index')\nexcept LookupError:\n    caught_index_by_lookup = True\nassert caught_index_by_lookup\n\n# LookupError should NOT catch ValueError\ncaught_value_by_lookup = False\ntry:\n    try:\n        raise ValueError('value')\n    except LookupError:\n        caught_value_by_lookup = True\nexcept ValueError:\n    pass\nassert not caught_value_by_lookup, 'LookupError should NOT catch ValueError'\n\n# === Exception hierarchy: ArithmeticError ===\n# ArithmeticError should catch ZeroDivisionError\ncaught_zero_by_arith = False\ntry:\n    raise ZeroDivisionError('zero')\nexcept ArithmeticError:\n    caught_zero_by_arith = True\nassert caught_zero_by_arith\n\n# ArithmeticError should catch OverflowError\ncaught_overflow_by_arith = False\ntry:\n    raise OverflowError('overflow')\nexcept ArithmeticError:\n    caught_overflow_by_arith = True\nassert caught_overflow_by_arith\n\n# === Exception hierarchy: RuntimeError ===\n# RuntimeError should catch NotImplementedError\ncaught_notimpl_by_runtime = False\ntry:\n    raise NotImplementedError('not impl')\nexcept RuntimeError:\n    caught_notimpl_by_runtime = True\nassert caught_notimpl_by_runtime\n\n# RuntimeError should catch RecursionError\ncaught_recursion_by_runtime = False\ntry:\n    raise RecursionError('recursion')\nexcept RuntimeError:\n    caught_recursion_by_runtime = True\nassert caught_recursion_by_runtime\n\n# === Exception hierarchy: OSError ===\n# OSError should catch TimeoutError (subclass since Python 3.3)\ncaught_timeout_by_oserror = False\ntry:\n    raise TimeoutError('timed out')\nexcept OSError:\n    caught_timeout_by_oserror = True\nassert caught_timeout_by_oserror, 'OSError should catch TimeoutError'\n\n# TimeoutError should still be caught specifically before OSError\ncaught_timeout_specifically = False\ntry:\n    raise TimeoutError('timed out')\nexcept TimeoutError:\n    caught_timeout_specifically = True\nexcept OSError:\n    pass\nassert caught_timeout_specifically, 'TimeoutError handler should match TimeoutError'\n\ntry:\n    raise TimeoutError('timed out')\nexcept TimeoutError as e:\n    assert isinstance(e, TimeoutError), 'exception should be instance of TimeoutError'\n    assert isinstance(e, OSError), 'TimeoutError should be instance of OSError'\n    assert not isinstance(e, ValueError), 'TimeoutError should not be ValueError'\n\n# === Exception hierarchy in tuple ===\n# Tuple containing base class should catch derived\ncaught_by_tuple_base = False\ntry:\n    raise KeyError('key')\nexcept (ValueError, LookupError):\n    caught_by_tuple_base = True\nassert caught_by_tuple_base\n\n# === isinstance with exception hierarchy ===\ntry:\n    raise KeyError('key')\nexcept KeyError as e:\n    assert isinstance(e, KeyError)\n    assert isinstance(e, LookupError)\n    assert isinstance(e, Exception)\n    assert not isinstance(e, ArithmeticError), 'KeyError should not be ArithmeticError'\n\ntry:\n    raise ZeroDivisionError('zero')\nexcept ZeroDivisionError as e:\n    assert isinstance(e, ZeroDivisionError)\n    assert isinstance(e, ArithmeticError)\n    assert isinstance(e, Exception)\n    assert not isinstance(e, LookupError), 'ZeroDivisionError should not be LookupError'\n\n# === Multiple handlers where none match ===\n# Exception should propagate when no handler matches\nmulti_no_match_propagated = False\ntry:\n    try:\n        raise MemoryError('out of memory')\n    except ValueError:\n        pass\n    except TypeError:\n        pass\n    except KeyError:\n        pass\nexcept MemoryError as e:\n    multi_no_match_propagated = repr(e) == \"MemoryError('out of memory')\"\nassert multi_no_match_propagated\n\n# === BaseException hierarchy ===\n# BaseException should catch all exceptions including Exception subclasses\ncaught_value_by_base = False\ntry:\n    raise ValueError('value')\nexcept BaseException:\n    caught_value_by_base = True\nassert caught_value_by_base\n\ncaught_key_by_base = False\ntry:\n    raise KeyError('key')\nexcept BaseException:\n    caught_key_by_base = True\nassert caught_key_by_base\n\ncaught_type_by_base = False\ntry:\n    raise TypeError('type')\nexcept BaseException:\n    caught_type_by_base = True\nassert caught_type_by_base\n\n# BaseException catches KeyboardInterrupt\ncaught_keyboard_by_base = False\ntry:\n    raise KeyboardInterrupt()\nexcept BaseException:\n    caught_keyboard_by_base = True\nassert caught_keyboard_by_base\n\n# BaseException catches SystemExit\ncaught_sysexit_by_base = False\ntry:\n    raise SystemExit()\nexcept BaseException:\n    caught_sysexit_by_base = True\nassert caught_sysexit_by_base\n\n# === Exception does NOT catch BaseException direct subclasses ===\n# Exception should NOT catch KeyboardInterrupt\ncaught_keyboard_by_exc = False\ntry:\n    try:\n        raise KeyboardInterrupt()\n    except Exception:\n        caught_keyboard_by_exc = True\nexcept BaseException:\n    pass\nassert not caught_keyboard_by_exc, 'Exception should NOT catch KeyboardInterrupt'\n\n# Exception should NOT catch SystemExit\ncaught_sysexit_by_exc = False\ntry:\n    try:\n        raise SystemExit()\n    except Exception:\n        caught_sysexit_by_exc = True\nexcept BaseException:\n    pass\nassert not caught_sysexit_by_exc, 'Exception should NOT catch SystemExit'\n\n# But Exception SHOULD catch regular exceptions\ncaught_value_by_exc = False\ntry:\n    raise ValueError('test')\nexcept Exception:\n    caught_value_by_exc = True\nassert caught_value_by_exc\n\n# === isinstance with BaseException ===\ntry:\n    raise ValueError('test')\nexcept ValueError as e:\n    assert isinstance(e, BaseException)\n\ntry:\n    raise KeyboardInterrupt()\nexcept KeyboardInterrupt as e:\n    assert isinstance(e, BaseException)\n    assert not isinstance(e, Exception), 'KeyboardInterrupt should NOT be instance of Exception'\n\ntry:\n    raise SystemExit()\nexcept SystemExit as e:\n    assert isinstance(e, BaseException)\n    assert not isinstance(e, Exception), 'SystemExit should NOT be instance of Exception'\n\n# === Tuple containing BaseException ===\ncaught_by_tuple_with_base = False\ntry:\n    raise KeyboardInterrupt()\nexcept (ValueError, BaseException):\n    caught_by_tuple_with_base = True\nassert caught_by_tuple_with_base\n\n# === Nested tuples in except are rejected (CPython parity) ===\n# CPython only accepts a single level of tuple in an `except` clause. A nested\n# tuple element is not a class inheriting from BaseException, so matching against\n# it raises TypeError rather than descending into the sub-tuple. This also bounds\n# the matcher: the except type is built at runtime and could otherwise be nested\n# arbitrarily deeply, overflowing the host stack inside one bytecode instruction.\n#\n# The TypeError is raised while evaluating the `except` clause itself, so it\n# propagates out of the whole `try` (later `except` clauses of the *same* try are\n# not tried against it) and must be caught by an enclosing `try`.\n_msg = 'catching classes that do not inherit from BaseException is not allowed'\n\n# Single-element tuple wrapping a tuple.\n_rejected = False\ntry:\n    try:\n        raise TypeError()\n    except ((ValueError,),):\n        assert False, 'nested tuple should not be descended into'\nexcept TypeError as exc:\n    _rejected = True\n    assert str(exc) == _msg, f'unexpected message: {exc}'\nassert _rejected\n\n# Tuple of tuples.\n_rejected = False\ntry:\n    try:\n        raise TypeError()\n    except ((ValueError,), (KeyError, TypeError)):\n        assert False, 'tuple of tuples should not match'\nexcept TypeError as exc:\n    _rejected = True\n    assert str(exc) == _msg, f'unexpected message: {exc}'\nassert _rejected\n\n# The whole tuple is validated, so an invalid element raises even when an\n# earlier element already matched the raised exception.\n_rejected = False\ntry:\n    try:\n        raise TypeError()\n    except (TypeError, (ValueError,)):\n        assert False, 'must validate whole tuple, not short-circuit on match'\nexcept TypeError as exc:\n    _rejected = True\n    assert str(exc) == _msg, f'unexpected message: {exc}'\nassert _rejected\n\n# Invalid element appears before a valid match.\n_rejected = False\ntry:\n    try:\n        raise TypeError()\n    except ((ValueError,), TypeError):\n        assert False, 'leading nested tuple should be rejected'\nexcept TypeError as exc:\n    _rejected = True\n    assert str(exc) == _msg, f'unexpected message: {exc}'\nassert _rejected\n\n# Deeply nested, runtime-constructed tuple: rejected with TypeError, not a host\n# stack overflow and not a RecursionError.\ndeep = (ValueError,)\nfor _ in range(1000):\n    deep = (deep,)\n_rejected = False\ntry:\n    try:\n        raise TypeError()\n    except deep:\n        assert False, 'deeply nested tuple should not be descended into'\nexcept TypeError as exc:\n    _rejected = True\n    assert str(exc) == _msg, f'unexpected message: {exc}'\nassert _rejected\n\n# An empty tuple is valid (never matches): the original exception propagates\n# unchanged rather than raising the \"catching classes\" TypeError.\ncaught_empty_tuple = False\ntry:\n    try:\n        raise TypeError('propagate')\n    except ():\n        assert False, 'empty tuple never matches'\nexcept TypeError as exc:\n    caught_empty_tuple = True\n    assert str(exc) == 'propagate', f'unexpected message: {exc}'\nassert caught_empty_tuple\n\n# A large flat tuple built at runtime still matches normally.\nbig_flat = tuple([ValueError] * 5000 + [TypeError])\ncaught_big_flat = False\ntry:\n    raise TypeError()\nexcept big_flat:\n    caught_big_flat = True\nassert caught_big_flat\n\n# === Exception state cleared on `return` from inside an except handler ===\n# When `return` exits an except clause, the exception is cleared from the\n# active-exception state before any surrounding finally runs and before\n# control returns to the caller. A bare `raise` inside that finally (or\n# in subsequent code in the caller) must therefore see `RuntimeError(\n# \"No active exception to reraise\")` rather than re-raising the exception\n# the except clause had just been handling.\n\n\n# Bare raise inside a try/except inside a finally that runs after\n# return-from-except: should be caught as RuntimeError, not ValueError.\ndef _return_from_except_then_bare_raise_in_finally() -> None:\n    try:\n        try:\n            raise ValueError('original')\n        except ValueError:\n            return\n    finally:\n        try:\n            raise  # bare reraise — exception should already be cleared\n        except ValueError:\n            assert False, '`return` from except must clear the exception before finally runs'\n        except RuntimeError as exc:\n            assert str(exc) == 'No active exception to reraise'\n\n\n_return_from_except_then_bare_raise_in_finally()\n\n\n# Return from a doubly-nested except handler should clear EVERY enclosing\n# handler's exception state, not just the innermost.\ndef _return_from_doubly_nested_except() -> None:\n    try:\n        try:\n            try:\n                raise ValueError('inner')\n            except ValueError:\n                raise TypeError('middle')\n        except TypeError:\n            return\n    finally:\n        try:\n            raise\n        except (ValueError, TypeError):\n            assert False, \"`return` from doubly-nested except must clear every handler's exception state\"\n        except RuntimeError as exc:\n            assert str(exc) == 'No active exception to reraise'\n\n\n_return_from_doubly_nested_except()\n\n\n# After a function returns from inside an except clause, the caller's\n# active-exception state should NOT contain that function's exception.\ndef _returns_from_except_no_finally() -> str:\n    try:\n        raise ValueError('original')\n    except ValueError:\n        return 'returned'\n\n\nassert _returns_from_except_no_finally() == 'returned'\ntry:\n    raise  # bare raise in caller — no exception should be active here\nexcept ValueError:\n    assert False, \"caller should not see inner function's exception as current\"\nexcept RuntimeError as exc:\n    assert str(exc) == 'No active exception to reraise'\n\n\n# === Exception state cleared when an exception propagates past handlers ===\n# When an exception is raised from inside an except clause and is caught\n# by a sibling/outer handler, the inner (abandoned) handler's exception\n# must be cleared from the active-exception state — its trailer that\n# would normally pop it is dead code (the handler body terminated via\n# raise rather than falling through). Without this, a bare `raise` later\n# resurrects the abandoned exception instead of producing\n# `RuntimeError(\"No active exception to reraise\")`.\n\n# Triple-nested: `raise X` → `raise Y` → `raise Z`, then bare raise outside.\n# Each abandoned handler should be cleared.\ntry:\n    try:\n        try:\n            raise ValueError('first')\n        except ValueError:\n            raise TypeError('second')\n    except TypeError:\n        raise KeyError('third')\nexcept KeyError as third:\n    assert str(third) == \"'third'\"\n\ntry:\n    raise\nexcept RuntimeError as exc:\n    assert str(exc) == 'No active exception to reraise'\n\n\n# Raising from a NESTED try body inside an except clause must NOT clear\n# the surrounding handler's exception — the inner raise is caught locally\n# and the outer handler is still active. After the inner try-except\n# completes, a bare `raise` in the outer handler should re-raise the\n# outer's original exception, not produce RuntimeError.\ntry:\n    raise ValueError('outer')\nexcept ValueError as caught:\n    try:\n        raise KeyError('inner')\n    except KeyError:\n        pass  # inner caught locally; outer's ValueError should remain active\n\n    # Bare raise here should re-raise the outer's ValueError.\n    try:\n        raise\n    except ValueError as bare:\n        assert str(bare) == 'outer'\n\n\n# Function-call boundary: an exception raised and caught inside a callee\n# must not leak active-exception state back to the caller. Probe via bare\n# `raise` in the caller after the callee returns.\ndef _callee_raises_and_handles():\n    try:\n        raise ValueError('callee internal')\n    except ValueError:\n        pass\n\n\n_callee_raises_and_handles()\ntry:\n    raise\nexcept RuntimeError as exc:\n    assert str(exc) == 'No active exception to reraise'\n\n\n# === Return through inner try-finally inside an except keeps outer exception ===\n# When `return` is inside a try-finally nested inside an except handler,\n# the inner finally must run with the OUTER except's exception still\n# active — a bare `raise` inside the inner finally should re-raise the\n# outer exception, not produce RuntimeError. The active-exception cleanup\n# for the outer except must be deferred until after the inner finally\n# completes.\n\n_return_through_inner_finally_log: list[tuple[str, str]] = []\n\n\ndef _return_through_inner_finally() -> str:\n    try:\n        raise ValueError('outer')\n    except ValueError:\n        try:\n            return 'done'\n        finally:\n            try:\n                raise  # outer ValueError should still be the active exception\n            except ValueError as caught:\n                _return_through_inner_finally_log.append(('ValueError', str(caught)))\n            except RuntimeError as e:\n                _return_through_inner_finally_log.append(('RuntimeError', str(e)))\n    return 'unreachable'\n\n\nassert _return_through_inner_finally() == 'done'\nassert _return_through_inner_finally_log == [('ValueError', 'outer')], (\n    f'expected outer ValueError to remain active inside inner finally, got {_return_through_inner_finally_log!r}'\n)\n\n\n# After the function returns, the caller's active-exception state must\n# still be clean — the outer except's exception was cleared on return.\ntry:\n    raise\nexcept RuntimeError as exc:\n    assert str(exc) == 'No active exception to reraise'\n\n\n# === Return through TWO nested finallys inside two excepts ===\n# Each finally runs with the textually-active exception still on top\n# of `exception_stack` — the inner finally sees the inner except's\n# exception, the outer finally sees the outer except's exception.\n# This exercises both the per-finally cleanup boundary in\n# `emit_return_routing` and the clone-not-pop behavior of bare `raise`\n# (without which the inner finally's locally-caught reraise would\n# strand the outer except's entry).\n\n_two_finally_log: list[tuple[str, str, str]] = []\n\n\ndef _return_through_two_finallys() -> str:\n    try:\n        raise ValueError('A')\n    except ValueError:\n        try:  # outer try has finally\n            try:\n                raise TypeError('B')\n            except TypeError:\n                try:  # inner try has finally\n                    return 'done'\n                finally:\n                    try:\n                        raise  # outer=A and inner=B both active; reraises B\n                    except TypeError as t:\n                        _two_finally_log.append(('inner_finally', 'TypeError', str(t)))\n                    except ValueError as v:\n                        _two_finally_log.append(('inner_finally', 'ValueError', str(v)))\n        finally:\n            try:\n                raise  # only A is still active here; B was bound to the inner except that we exited\n            except ValueError as v:\n                _two_finally_log.append(('outer_finally', 'ValueError', str(v)))\n            except TypeError as t:\n                _two_finally_log.append(('outer_finally', 'TypeError', str(t)))\n            except RuntimeError as r:\n                _two_finally_log.append(('outer_finally', 'RuntimeError', str(r)))\n    return 'fallback'\n\n\nassert _return_through_two_finallys() == 'done'\nassert _two_finally_log == [\n    ('inner_finally', 'TypeError', 'B'),\n    ('outer_finally', 'ValueError', 'A'),\n], f'unexpected log {_two_finally_log!r}'\n\n\n# === re-raising preserves the exception object's identity ===\n# `raise e` and a bare `raise` both propagate the very object that was caught,\n# rather than an equal copy, matching CPython.\ndef _bare_raise_identity():\n    try:\n        try:\n            raise ValueError('ident')\n        except ValueError as inner:\n            captured = inner\n            raise\n    except ValueError as outer:\n        return outer is captured\n\n\nassert _bare_raise_identity() is True, 'bare raise should re-raise the same object'\n\n\ndef _explicit_raise_identity():\n    try:\n        raise ValueError('ident')\n    except ValueError as first:\n        captured = first\n    try:\n        raise captured\n    except ValueError as second:\n        return second is captured\n\n\nassert _explicit_raise_identity() is True, 'raise <instance> should re-raise the same object'\n\n\n# identity survives propagation through intervening finally blocks\ndef _identity_through_finally():\n    order = []\n    try:\n        try:\n            raise ValueError('deep')\n        except ValueError as inner:\n            captured = inner\n            try:\n                raise\n            finally:\n                order.append('finally')\n    except ValueError as outer:\n        return outer is captured, order\n\n\nassert _identity_through_finally() == (True, ['finally'])\n",
  'try_except__bare_raise_no_context.py': "raise\n# Raise=RuntimeError('No active exception to reraise')\n",
  'try_except__invalid_type.py': "try:\n    raise ValueError('test')\nexcept 123:\n    pass\n# Raise=TypeError('catching classes that do not inherit from BaseException is not allowed')\n",
  'try_finally__control_flow.py': "# Control flow (break/continue/return) interacting with finally blocks,\n# especially on the exception path — regression tests for\n# https://github.com/pydantic/monty/issues/647 (finally ran twice when\n# entered via an in-flight exception and exited via break/return).\n\n# === break in finally swallows an in-flight exception, finally runs once ===\nxs = []\nwhile True:\n    try:\n        raise ValueError\n    finally:\n        xs.append(1)\n        break\nassert xs == [1]\n\n# === return in finally swallows an in-flight exception, finally runs once ===\nxs = []\n\n\ndef return_in_finally():\n    try:\n        raise ValueError\n    finally:\n        xs.append(1)\n        return 2\n\n\nassert return_in_finally() == 2\nassert xs == [1]\n\n# === continue in finally swallows an in-flight exception ===\nxs = []\nfor i in range(3):\n    try:\n        raise ValueError\n    finally:\n        xs.append(i)\n        continue\nassert xs == [0, 1, 2]\n\n\n# === after a swallow, there is no active exception to re-raise ===\ndef swallow_then_bare_raise():\n    while True:\n        try:\n            raise ValueError('swallowed')\n        finally:\n            break\n    raise\n\n\ntry:\n    swallow_then_bare_raise()\n    assert False, 'expected RuntimeError'\nexcept RuntimeError as e:\n    assert str(e) == 'No active exception to reraise'\n\n# === finally raising on the return path runs once and propagates ===\nxs = []\n\n\ndef raise_in_finally_during_return():\n    try:\n        return 1\n    finally:\n        xs.append(1)\n        raise ValueError('boom')\n\n\ntry:\n    raise_in_finally_during_return()\n    assert False, 'expected ValueError'\nexcept ValueError as e:\n    assert str(e) == 'boom'\nassert xs == [1]\n\n# === return value is evaluated before the finally body runs ===\norder = []\n\n\ndef note(tag, value):\n    order.append(tag)\n    return value\n\n\ndef return_evaluation_order():\n    try:\n        return note('value', 42)\n    finally:\n        order.append('finally')\n\n\nassert return_evaluation_order() == 42\nassert order == ['value', 'finally']\n\n\n# === break in finally discards a pending return value ===\ndef break_discards_return():\n    for i in range(3):\n        try:\n            return 1\n        finally:\n            break\n    return 'after loop'\n\n\nassert break_discards_return() == 'after loop'\n\n\n# === continue in finally discards a pending return value ===\ndef continue_discards_return():\n    runs = []\n    for i in range(2):\n        try:\n            return 1\n        finally:\n            runs.append(i)\n            continue\n    return runs\n\n\nassert continue_discards_return() == [0, 1]\n\n\n# === return in finally overrides return in try ===\ndef finally_overrides_return():\n    try:\n        return 'try'\n    finally:\n        return 'finally'\n\n\nassert finally_overrides_return() == 'finally'\n\n# === nested finallys each run once, inner first, on break ===\nxs = []\nwhile True:\n    try:\n        try:\n            raise ValueError\n        finally:\n            xs.append('inner')\n    finally:\n        xs.append('outer')\n        break\nassert xs == ['inner', 'outer']\n\n# === break crossing an inner finally from inside an outer finally ===\nxs = []\nwhile True:\n    try:\n        raise ValueError\n    finally:\n        try:\n            xs.append('inner-try')\n        finally:\n            xs.append('inner-finally')\n        xs.append('outer-finally')\n        break\nassert xs == ['inner-try', 'inner-finally', 'outer-finally']\n\n# === exception raised inside a finally during break is caught outside ===\nxs = []\ntry:\n    while True:\n        try:\n            break\n        finally:\n            xs.append('finally')\n            raise ValueError('from finally')\nexcept ValueError as e:\n    xs.append(str(e))\nassert xs == ['finally', 'from finally']\n\n# === try/except nested inside an exception-path finally ===\n# The inner handler must not disturb the in-flight exception: the outer\n# except still sees the original, and a bare raise in the finally would too.\nout = []\ntry:\n    try:\n        raise ValueError('original')\n    finally:\n        try:\n            raise TypeError('inner')\n        except TypeError:\n            pass\n        out.append('finally done')\nexcept ValueError as e:\n    out.append(str(e))\nassert out == ['finally done', 'original']\n\n\n# === bare raise in a finally inside an except handler sees the handler's exception ===\ndef bare_raise_in_inner_finally():\n    seen = []\n    try:\n        raise ValueError('original')\n    except ValueError:\n        try:\n            return seen\n        finally:\n            try:\n                raise\n            except ValueError as e:\n                seen.append(str(e))\n\n\nassert bare_raise_in_inner_finally() == ['original']\n\n# === handler variable is unbound after break out of the handler ===\nfor i in range(3):\n    try:\n        raise ValueError('x')\n    except ValueError as caught:\n        break\ntry:\n    caught\n    assert False, 'expected NameError'\nexcept NameError:\n    pass\n\n\n# === handler target is cleared before an exceptional exit reaches finally ===\nhandler_cleanup = []\ntry:\n    try:\n        try:\n            raise ValueError('original')\n        except ValueError as abandoned:\n            raise TypeError('replacement')\n    finally:\n        try:\n            abandoned\n        except NameError:\n            handler_cleanup.append('unbound')\n        else:\n            handler_cleanup.append('bound')\nexcept TypeError as replacement:\n    handler_cleanup.append(str(replacement))\nassert handler_cleanup == ['unbound', 'replacement']\n\n\n# === captured handler target is cleared on an exceptional exit ===\n# The cleanup path for a replacement exception uses DeleteCell when a closure\n# captures the handler target; normal fall-through and return use other paths.\ndef exceptional_handler_cell_cleanup():\n    probe = None\n    try:\n        try:\n            raise ValueError('original')\n        except ValueError as captured:\n            probe = lambda: captured\n            raise TypeError('replacement')\n    except TypeError:\n        pass\n\n    try:\n        probe()\n        return 'still bound'\n    except NameError as e:\n        return str(e)\n\n\nassert exceptional_handler_cell_cleanup() == (\n    \"cannot access free variable 'captured' where it is not associated with a value in enclosing scope\"\n)\n\n\n# === handler variable is unbound after return out of the handler ===\n# the probe closure captures `exc2`, so calling it after the return observes\n# the handler cleanup unbinding the cell (a module-level lookup could not —\n# it would be NameError regardless)\n\n\ndef return_from_handler():\n    try:\n        raise ValueError('x')\n    except ValueError as exc2:\n        return 'returned', lambda: exc2\n\n\nvalue, probe = return_from_handler()\nassert value == 'returned'\ntry:\n    probe()\n    assert False, 'expected NameError'\nexcept NameError:\n    pass\n\n\n# === owning frame reads the handler variable after cleanup: UnboundLocalError ===\n# only the nested closure's read (above) is the free-variable NameError; the\n# frame that owns the cell gets UnboundLocalError, like any unassigned local\ndef owner_read_after_cleanup():\n    try:\n        raise ValueError('x')\n    except ValueError as exc3:\n        hold = lambda: exc3\n    return exc3\n\n\ntry:\n    owner_read_after_cleanup()\n    assert False, 'expected UnboundLocalError'\nexcept UnboundLocalError as e:\n    assert str(e) == \"cannot access local variable 'exc3' where it is not associated with a value\"\n\n\n# === handler variable is unbound after continue out of the handler ===\nfor i in range(2):\n    try:\n        raise ValueError('x')\n    except ValueError as caught2:\n        continue\ntry:\n    caught2\n    assert False, 'expected NameError'\nexcept NameError:\n    pass\n\n# === with + finally: __exit__ and finally each run once on break ===\nevents = []\n\n\nclass Tracker:\n    def __enter__(self):\n        events.append('enter')\n        return self\n\n    def __exit__(self, typ, val, tb):\n        events.append('exit')\n        return False\n\n\nwhile True:\n    try:\n        with Tracker():\n            raise ValueError\n    finally:\n        events.append('finally')\n        break\nassert events == ['enter', 'exit', 'finally']\n\n# === __exit__ failure replaces return and is caught by the enclosing region ===\nevents = []\n\n\nclass ExplodingExit:\n    def __init__(self, tag):\n        self.tag = tag\n\n    def __enter__(self):\n        events.append(f'enter {self.tag}')\n        return self\n\n    def __exit__(self, typ, val, tb):\n        events.append(f'exit {self.tag}')\n        raise RuntimeError(f'exit failed {self.tag}')\n\n\ndef return_through_exploding_exit():\n    try:\n        with ExplodingExit('return'):\n            return 'discarded'\n    except RuntimeError as e:\n        return str(e)\n\n\nassert return_through_exploding_exit() == 'exit failed return'\nassert events == ['enter return', 'exit return']\n\n# === __exit__ failure replaces break and is caught outside the loop ===\nevents = []\ntry:\n    while True:\n        with ExplodingExit('break'):\n            break\nexcept RuntimeError as e:\n    events.append(str(e))\nassert events == ['enter break', 'exit break', 'exit failed break']\n\n# === break inside with inside finally calls __exit__ once ===\nevents = []\nwhile True:\n    try:\n        raise ValueError\n    finally:\n        with Tracker():\n            events.append('body')\n            break\nassert events == ['enter', 'body', 'exit']\n\n# === return through with + for + finally unwinds innermost first ===\nevents = []\n\n\ndef deep_unwind():\n    try:\n        for i in range(5):\n            with Tracker():\n                return 'done'\n    finally:\n        events.append('finally')\n\n\nassert deep_unwind() == 'done'\nassert events == ['enter', 'exit', 'finally']\n\n\n# === exception in the exception-path finally replaces the original ===\ndef replace_exception():\n    try:\n        raise ValueError('original')\n    finally:\n        raise TypeError('replacement')\n\n\ntry:\n    replace_exception()\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == 'replacement'\n\n# === finally runs once per path in try/except/else/finally ===\nxs = []\nfor mode in ['ok', 'caught', 'uncaught', 'ret']:\n\n    def run(mode=mode):\n        try:\n            if mode in ('caught', 'uncaught'):\n                raise KeyError(mode)\n        except KeyError as e:\n            xs.append(f'except {mode}')\n            if mode == 'uncaught':\n                raise ValueError(mode)\n        else:\n            xs.append(f'else {mode}')\n            if mode == 'ret':\n                return 'ret'\n        finally:\n            xs.append(f'finally {mode}')\n\n    try:\n        run()\n    except ValueError:\n        xs.append(f'caught {mode}')\nassert xs == [\n    'else ok',\n    'finally ok',\n    'except caught',\n    'finally caught',\n    'except uncaught',\n    'finally uncaught',\n    'caught uncaught',\n    'else ret',\n    'finally ret',\n]\n\n# === break through try/except/finally from the handler body ===\nxs = []\nwhile True:\n    try:\n        raise ValueError\n    except ValueError:\n        xs.append('except')\n        break\n    finally:\n        xs.append('finally')\nassert xs == ['except', 'finally']\n\n\n# === continue clears a named handler before the enclosing finally runs ===\ndef continue_from_handler_through_finally():\n    seen = []\n    for i in range(2):\n        try:\n            try:\n                raise ValueError(str(i))\n            except ValueError as current:\n                seen.append(f'handler {current}')\n                continue\n        finally:\n            try:\n                current\n                seen.append('bound')\n            except UnboundLocalError:\n                seen.append('unbound')\n            seen.append(f'finally {i}')\n    return seen\n\n\nassert continue_from_handler_through_finally() == [\n    'handler 0',\n    'unbound',\n    'finally 0',\n    'handler 1',\n    'unbound',\n    'finally 1',\n]\n\n# === continue in exception-path finally keeps looping, then loop ends normally ===\nxs = []\nfor i in range(2):\n    try:\n        raise ValueError(str(i))\n    finally:\n        xs.append(i)\n        continue\nelse:\n    xs.append('else')\nassert xs == [0, 1, 'else']\n\n# === break through finally skips the loop else block ===\nxs = []\nfor i in range(2):\n    try:\n        raise ValueError\n    finally:\n        break\nelse:\n    xs.append('else')\nassert xs == []\n\n# === break targeting a loop *inside* the finally does not swallow ===\n# The loop lives entirely within the finally body, so its break must not\n# discard the in-flight exception.\nxs = []\ntry:\n    try:\n        raise ValueError('kept')\n    finally:\n        for k in range(5):\n            xs.append(k)\n            break\n        xs.append('after inner loop')\nexcept ValueError as e:\n    xs.append(str(e))\nassert xs == [0, 'after inner loop', 'kept']\n\n\n# === break targeting a loop inside an except body keeps handler state ===\ndef break_in_handler_loop():\n    try:\n        raise ValueError('original')\n    except ValueError:\n        while True:\n            break\n        try:\n            raise\n        except ValueError as e:\n            return str(e)\n\n\nassert break_in_handler_loop() == 'original'\n\n\n# === for+break inside an except body, then bare raise propagates ===\ndef for_break_then_reraise():\n    try:\n        raise ValueError('kept by handler')\n    except ValueError:\n        for i in [1, 2]:\n            break\n        raise\n\n\ntry:\n    for_break_then_reraise()\n    assert False, 'expected ValueError'\nexcept ValueError as e:\n    assert str(e) == 'kept by handler'\n\n\n# === return crossing two nested finallys runs both, inner first ===\norder = []\n\n\ndef return_two_finallys():\n    try:\n        try:\n            return 'value'\n        finally:\n            order.append('inner')\n    finally:\n        order.append('outer')\n\n\nassert return_two_finallys() == 'value'\nassert order == ['inner', 'outer']\n\n# === return in inner finally swallows exception, still crosses outer finally ===\norder = []\n\n\ndef swallow_then_outer():\n    try:\n        try:\n            raise ValueError\n        finally:\n            order.append('inner')\n            return 'swallowed'\n    finally:\n        order.append('outer')\n\n\nassert swallow_then_outer() == 'swallowed'\nassert order == ['inner', 'outer']\n\n# === break from a non-first except handler runs the finally ===\nxs = []\nwhile True:\n    try:\n        raise KeyError('k')\n    except ValueError:\n        xs.append('wrong handler')\n    except KeyError:\n        xs.append('key')\n        break\n    finally:\n        xs.append('finally')\nassert xs == ['key', 'finally']\n\n# === break inside with inside except handler unwinds both ===\nevents = []\n\n\nclass Recorder:\n    def __enter__(self):\n        events.append('enter')\n        return self\n\n    def __exit__(self, typ, val, tb):\n        events.append(f'exit {typ is None}')\n        return False\n\n\nwhile True:\n    try:\n        raise ValueError\n    except ValueError:\n        with Recorder():\n            break\nassert events == ['enter', 'exit True']\n\n\n# === __exit__ swallowing the exception, then loop control flow continues ===\nclass Swallow:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        return True\n\n\nxs = []\nfor i in range(3):\n    with Swallow():\n        raise ValueError(str(i))\n    xs.append(f'resumed {i}')\nassert xs == ['resumed 0', 'resumed 1', 'resumed 2']\n\nxs = []\nfor i in range(3):\n    with Swallow():\n        if i == 1:\n            raise ValueError('swallowed')\n        xs.append(i)\n    xs.append(f'after {i}')\nassert xs == [0, 'after 0', 'after 1', 2, 'after 2']\n\n# === try/finally inside with body: break swallows, __exit__ sees no exception ===\nevents = []\nwhile True:\n    with Recorder():\n        try:\n            raise ValueError\n        finally:\n            events.append('finally')\n            break\nassert events == ['enter', 'finally', 'exit True']\n\n# === exception propagating out of with body reaches __exit__ with the type ===\nevents = []\ntry:\n    with Recorder():\n        raise ValueError('through exit')\nexcept ValueError as e:\n    events.append(str(e))\nassert events == ['enter', 'exit False', 'through exit']\n\n# === for → with → try/finally → return unwinds innermost first ===\nevents = []\n\n\ndef deep_mixed():\n    for i in range(3):\n        with Recorder():\n            try:\n                return 'deep'\n            finally:\n                events.append('finally')\n\n\nassert deep_mixed() == 'deep'\nassert events == ['enter', 'finally', 'exit True']\n\n# === continue crossing with + finally in one step ===\nevents = []\nfor i in range(2):\n    with Recorder():\n        try:\n            events.append(i)\n            continue\n        finally:\n            events.append('finally')\nassert events == ['enter', 0, 'finally', 'exit True', 'enter', 1, 'finally', 'exit True']\n\n# === exception raised by the call in `return f()` still reaches handlers ===\n# Regression: the return's unwind used to interrupt the protected region at\n# exactly the callee's exception-delivery offset (the instruction after the\n# call), so except/finally/__exit__ were all skipped when the call raised.\n\n\ndef boom():\n    raise ValueError('boom')\n\n\ndef return_call_except():\n    try:\n        return boom()\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_call_except() == 'caught boom'\n\n\ndef return_call_short_circuit():\n    try:\n        return False or boom()\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_call_short_circuit() == 'caught boom'\n\n\n# Attribute and indirect calls have distinct bytecode call shapes, while `and`\n# reaches its right operand through the same fall-through path as `or`.\nclass ReturnBoom:\n    def fail(self):\n        raise ValueError('attribute boom')\n\n\ndef return_attr_call_except():\n    try:\n        return ReturnBoom().fail()\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_attr_call_except() == 'caught attribute boom'\n\n\ndef get_boom():\n    return boom\n\n\ndef return_indirect_call_except():\n    try:\n        return get_boom()()\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_indirect_call_except() == 'caught boom'\n\n\ndef return_call_and_fallthrough():\n    try:\n        return True and boom()\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_call_and_fallthrough() == 'caught boom'\n\n\ndef return_call_ternary_fallthrough():\n    try:\n        return 0 if False else boom()\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_call_ternary_fallthrough() == 'caught boom'\n\n\ndef return_call_ternary_jump():\n    try:\n        return boom() if True else 0\n    except ValueError as e:\n        return f'caught {e}'\n\n\nassert return_call_ternary_jump() == 'caught boom'\n\nevents = []\n\n\ndef return_call_finally():\n    try:\n        return boom()\n    finally:\n        events.append('finally')\n\n\ntry:\n    return_call_finally()\nexcept ValueError as e:\n    events.append(str(e))\nassert events == ['finally', 'boom']\n\nevents = []\n\n\ndef return_call_with():\n    with Recorder():\n        return boom()\n\n\ntry:\n    return_call_with()\nexcept ValueError:\n    events.append('caught')\nassert events == ['enter', 'exit False', 'caught']\n\nevents = []\n\n\ndef return_call_nested():\n    try:\n        try:\n            return boom()\n        except ValueError:\n            events.append('inner')\n            raise\n    finally:\n        events.append('finally')\n\n\ntry:\n    return_call_nested()\nexcept ValueError:\n    events.append('outer')\nassert events == ['inner', 'finally', 'outer']\n\n\ndef return_call_in_loop():\n    for i in range(3):\n        try:\n            return boom()\n        except ValueError:\n            return f'caught in loop {i}'\n\n\nassert return_call_in_loop() == 'caught in loop 0'\n",
  'tuple__getitem_out_of_bounds.py': "a = (1, 2)\na[5]\n# Raise=IndexError('tuple index out of range')\n",
  'tuple__index_not_found.py': "(1, 2, 3).index(4)\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"tuple__index_not_found.py\", line 1, in <module>\n    (1, 2, 3).index(4)\n    ~~~~~~~~~~~~~~~~~~\nValueError: tuple.index(x): x not in tuple\n\"\"\"\n",
  'tuple__index_start_gt_end.py': "# Test that tuple.index with start > end doesn't panic but raises ValueError\n(1, 2, 3).index(1, 5, 2)\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"tuple__index_start_gt_end.py\", line 2, in <module>\n    (1, 2, 3).index(1, 5, 2)\n    ~~~~~~~~~~~~~~~~~~~~~~~~\nValueError: tuple.index(x): x not in tuple\n\"\"\"\n",
  'tuple__methods.py': "# === tuple.index() ===\nt = (1, 2, 3, 2)\nassert t.index(2) == 1\nassert t.index(3) == 2\nassert t.index(2, 2) == 3\nassert t.index(2, 1, 4) == 1\n\n# Regression: `-index` on i64::MIN used to panic when normalising start/end\n_I64_MIN = -(2**63)\nassert t.index(1, _I64_MIN) == 0\nassert t.index(2, _I64_MIN, 4) == 1\n\nt = ('a', 'b', 'c')\nassert t.index('b') == 1\n\n# === tuple.count() ===\nt = (1, 2, 2, 3, 2)\nassert t.count(2) == 3\nassert t.count(1) == 1\nassert t.count(4) == 0\nassert ().count(1) == 0\n\nt = ('a', 'b', 'a')\nassert t.count('a') == 2\n",
  'tuple__ops.py': "# === Empty tuple identity (singleton optimization) ===\n# In Python, () is () is always True because empty tuples are interned\nassert () is ()\nassert tuple() is ()\nassert tuple() is tuple()\na = ()\nb = ()\nassert a is b\n# Empty tuple from operations\nassert (1,)[1:] is ()\nassert (1, 2) * 0 is ()\n\n# === Tuple length ===\nassert len(()) == 0\nassert len((1,)) == 1\nassert len((1, 2, 3)) == 3\n\n# === Tuple indexing ===\na = (1, 2, 3)\nassert a[1] == 2\n\na = ('a', 'b', 'c')\nassert a[0 - 2] == 'b'\nassert a[-1] == 'c'\n\n# === Nested tuples ===\nassert ((1, 2), (3, 4)) == ((1, 2), (3, 4))\n\n# === Tuple repr/str ===\nassert repr((1, 2)) == '(1, 2)'\nassert str((1, 2)) == '(1, 2)'\n\n# === Tuple concatenation (+) ===\nassert (1, 2) + (3, 4) == (1, 2, 3, 4)\nassert () + (1, 2) == (1, 2)\nassert (1, 2) + () == (1, 2)\nassert () + () == ()\nassert ('a', 'b') + ('c',) == ('a', 'b', 'c')\nassert ((1, 2),) + ((3, 4),) == ((1, 2), (3, 4))\n\n# === Tuple repetition (*) ===\nassert (1, 2) * 3 == (1, 2, 1, 2, 1, 2)\nassert 3 * (1, 2) == (1, 2, 1, 2, 1, 2)\nassert (1,) * 0 == ()\nassert (1,) * -1 == ()\nassert () * 5 == ()\nassert () * (2**30) == ()\nassert (2**30) * () == ()\nassert (1, 2) * 1 == (1, 2)\n\n# === Tuple augmented assignment edge cases ===\nt = ([1],)\ntry:\n    t[0] += [2]\n    assert False, 'tuple item augmented assignment should fail'\nexcept TypeError as e:\n    assert e.args == (\"'tuple' object does not support item assignment\",)\n    assert t == ([1, 2],)\n\n# === tuple() constructor ===\nassert tuple() == ()\nassert tuple([1, 2, 3]) == (1, 2, 3)\nassert tuple((1, 2, 3)) == (1, 2, 3)\nassert tuple(range(3)) == (0, 1, 2)\nassert tuple('abc') == ('a', 'b', 'c')\nassert tuple(b'abc') == (97, 98, 99)\nassert tuple({'a': 1, 'b': 2}) == ('a', 'b')\n\n# non-ASCII strings (multi-byte UTF-8)\nassert tuple('héllo') == ('h', 'é', 'l', 'l', 'o')\nassert tuple('日本') == ('日', '本')\nassert tuple('a🎉b') == ('a', '🎉', 'b')\n\n# === Tuple unpacking (PEP 448) ===\na = (1, 2)\nb = (3, 4)\nassert (*a,) == (1, 2)\nassert (*a, *b) == (1, 2, 3, 4)\nassert (0, *a, 5) == (0, 1, 2, 5)\nassert (*(),) == ()\nassert (*[1, 2],) == (1, 2)\n\n# === Tuple comparison (<, >, <=, >=) ===\nassert (1, 2) < (1, 3)\nassert (1,) < (2,)\nassert () < (1,)\nassert (1, 2) < (1, 2, 3)\nassert not (1, 2) < (1, 2), 'not lt when equal'\nassert not (1, 3) < (1, 2), 'not lt when greater'\n\nassert (1, 3) > (1, 2)\nassert (2,) > (1,)\nassert (1,) > ()\nassert (1, 2, 3) > (1, 2)\nassert not (1, 2) > (1, 2), 'not gt when equal'\n\nassert (1, 2) <= (1, 2)\nassert (1, 2) <= (1, 3)\nassert not (1, 3) <= (1, 2), 'not le when greater'\n\nassert (1, 2) >= (1, 2)\nassert (1, 3) >= (1, 2)\nassert not (1, 2) >= (1, 3), 'not ge when less'\n\n# === Tuple comparison with sorted() ===\nassert sorted([(2, 'b'), (1, 'a')]) == [(1, 'a'), (2, 'b')]\nassert sorted([(1, 'b'), (1, 'a')]) == [(1, 'a'), (1, 'b')]\nassert sorted([(3,), (1,), (2,)]) == [(1,), (2,), (3,)]\n\n# === Nested tuple comparison ===\nassert ((1, 2), 3) < ((1, 3), 2)\nassert (1, (2, 3)) < (1, (2, 4))\n\n# === Equal-but-unorderable elements (None, lists, dicts) ===\n# CPython checks __eq__ first; equal elements skip ordering comparison\nassert not (1, None) < (1, None), 'equal None elements not lt'\nassert (1, None) <= (1, None)\nassert (1, None) >= (1, None)\nassert not (1, None) > (1, None), 'equal None elements not gt'\nassert (1, None) < (2, None)\nassert (1, [1, 2]) <= (1, [1, 2])\n\n# === Mixed types in tuple comparison ===\nassert (1,) < (2.0,)\nassert (1.0,) < (2,)\nassert (True,) < (2,)\nassert (False,) < (True,)\nassert (1, 'a') < (1, 'b')\nassert ('a', 1) < ('b', 1)\n\n# === Empty and equal tuples ===\nassert not () < (), 'empty tuples not lt'\nassert () <= ()\nassert () >= ()\nassert not () > (), 'empty tuples not gt'\n\n# === Tuple reprs ===\nassert repr(()) == '()'\nassert repr((1,)) == '(1,)'\nassert repr((1, 2)) == '(1, 2)'\nassert repr((1, (2, 3))) == '(1, (2, 3))'\n\n# === `in` / `not in` ===\ntu = (1, 'two', 3)\nassert 1 in tu\nassert 'two' in tu\nassert 9 not in tu\nassert () == ()\nassert 2 in (1, (2, 3))[1]\n# Members compare by value, across types where Python considers them equal.\nassert True in (1, 2)\nassert 1.0 in (1, 2)\nassert (2, 3) in (1, (2, 3))\nassert [2, 3] in (1, [2, 3])\nassert None in (None,)\nassert 1 not in ()\n",
