  'type_error__unary_minus_str.py': "# unary minus on heap-allocated string should raise TypeError\n# str() creates a heap-allocated string, triggering ref count check\n-str(42)\n# Raise=TypeError(\"bad operand type for unary -: 'str'\")\n",
  'type_error__unary_neg_str.py': "# unary minus on string should raise TypeError\n-'hello'\n# Raise=TypeError(\"bad operand type for unary -: 'str'\")\n",
  'type_error__unary_plus_str.py': "# unary plus on heap-allocated string should raise TypeError\n# str() creates a heap-allocated string, triggering ref count check\n+str(42)\n# Raise=TypeError(\"bad operand type for unary +: 'str'\")\n",
  'typing__types.py': "# Tests for typing module type() behavior\n#\n# CPython's typing module uses various internal types for different constructs.\n# Monty simplifies this by using typing._SpecialForm for all typing markers.\n# Where CPython also uses _SpecialForm, we use == for exact match.\n# Where CPython uses different internal types, we accept both representations.\n\nimport typing\n\n# === Types that match between CPython and Monty ===\nassert repr(type(typing.Optional)) == \"<class 'typing._SpecialForm'>\"\nassert repr(type(typing.ClassVar)) == \"<class 'typing._SpecialForm'>\"\nassert repr(type(typing.Final)) == \"<class 'typing._SpecialForm'>\"\nassert repr(type(typing.Union)) == \"<class 'type'>\"\n\n# === Types that differ between CPython and Monty ===\n# CPython uses specialized internal types; Monty uses _SpecialForm for all\nassert repr(type(typing.Any)) in (\"<class 'typing._SpecialForm'>\", \"<class 'typing._AnyMeta'>\")\nassert repr(type(typing.Callable)) in (\"<class 'typing._SpecialForm'>\", \"<class 'typing._CallableType'>\")\n\n# === Verify TYPE_CHECKING is False ===\nassert typing.TYPE_CHECKING is False\n",
  'unary__ops.py': "# Unary `-` and `+` across every type that implements them, and the types that\n# do not (which raise CPython's `bad operand type` TypeError).\nfrom collections import Counter, defaultdict\nfrom datetime import timedelta\n\n# === int and float ===\n# through variables, so the operand is negated at runtime rather than folded\nx = 5\nassert -x == -5\nassert +x == 5\nassert -(-x) == 5\nf = 2.5\nassert -f == -2.5\nassert +f == 2.5\n\n# === bool promotes to int ===\nassert -True == -1\nassert +True == 1\nassert -False == 0\nassert type(+True).__name__ == 'int'\nassert type(-False).__name__ == 'int'\n\n# === the i64 boundary: negating the smallest int needs a big int ===\nsmallest = -9223372036854775808\nassert -smallest == 9223372036854775808\nassert type(-smallest).__name__ == 'int'\nassert -(-smallest) == smallest\n\n# === big ints ===\nbig = 2**70\nassert -big == -1180591620717411303424\nassert +big == 1180591620717411303424\nassert -(-big) == big\nassert +(-big) == -big\nassert type(-big).__name__ == 'int'\n\n# === timedelta ===\nd = timedelta(days=1, seconds=2)\nassert -d == timedelta(days=-1, seconds=-2)\nassert +d == d\nassert -(-d) == d\nassert -timedelta(0) == timedelta(0)\n\n# === Counter: both signs keep only the counts that end up positive ===\nc = Counter(a=2, b=-1)\nassert +c == Counter(a=2)\nassert -c == Counter(b=1)\nassert type(-c).__name__ == 'Counter'\n# the operand itself is untouched — the result is a fresh Counter\nassert c == Counter(a=2, b=-1)\n\n\ndef unary_err(fn):\n    try:\n        fn()\n        raise AssertionError('expected TypeError')\n    except TypeError as exc:\n        return str(exc)\n\n\n# === types with no unary form ===\nassert unary_err(lambda: -'x') == \"bad operand type for unary -: 'str'\"\nassert unary_err(lambda: +'x') == \"bad operand type for unary +: 'str'\"\n# a heap-allocated (non-interned) string takes a different dispatch path\nbuilt = 'a' + str(1)\nassert unary_err(lambda: -built) == \"bad operand type for unary -: 'str'\"\nassert unary_err(lambda: -[1]) == \"bad operand type for unary -: 'list'\"\nassert unary_err(lambda: +[1]) == \"bad operand type for unary +: 'list'\"\nassert unary_err(lambda: -(1, 2)) == \"bad operand type for unary -: 'tuple'\"\nassert unary_err(lambda: +{1: 2}) == \"bad operand type for unary +: 'dict'\"\nassert unary_err(lambda: -{1, 2}) == \"bad operand type for unary -: 'set'\"\nassert unary_err(lambda: -b'ab') == \"bad operand type for unary -: 'bytes'\"\nassert unary_err(lambda: +None) == \"bad operand type for unary +: 'NoneType'\"\n# a defaultdict is a dict of a different kind, so it has no Counter algebra\nassert unary_err(lambda: +defaultdict(int)) == \"bad operand type for unary +: 'collections.defaultdict'\"\nassert unary_err(lambda: -defaultdict(int)) == \"bad operand type for unary -: 'collections.defaultdict'\"\n",
  'unicodedata__bad_arg.py': "import unicodedata\n\nunicodedata.category('ab')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"unicodedata__bad_arg.py\", line 3, in <module>\n    unicodedata.category('ab')\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~\nTypeError: category(): argument must be a unicode character, not a string of length 2\n\"\"\"\n",
  'unicodedata__core.py': "import unicodedata as u\n\n# Precomposed vs decomposed forms are visually identical, so use explicit\n# escapes: NFC_E is U+00E9 (é), NFD_E is 'e' + U+0301 (combining acute).\nNFC_E = 'é'\nNFD_E = 'é'\nACUTE = '́'\nFI = 'ﬁ'\nUNNAMED = '￿'  # a permanently-unassigned code point (has no name)\n\n# === unidata_version ===\nassert u.unidata_version == '16.0.0'\n\n# === category ===\nassert u.category('A') == 'Lu'\nassert u.category('a') == 'Ll'\nassert u.category('1') == 'Nd'\nassert u.category(' ') == 'Zs'\nassert u.category('!') == 'Po'\nassert u.category(NFC_E) == 'Ll'\nassert u.category(ACUTE) == 'Mn'\nassert u.category('_') == 'Pc'\nassert u.category('+') == 'Sm'\n\n# === name / lookup ===\nassert u.name('A') == 'LATIN CAPITAL LETTER A'\nassert u.name(NFC_E) == 'LATIN SMALL LETTER E WITH ACUTE'\nassert u.lookup('LATIN SMALL LETTER A') == 'a'\nassert u.lookup('GREEK SMALL LETTER ALPHA') == 'α'\nassert u.name(UNNAMED, 'DEFAULT') == 'DEFAULT'\n\n# An unknown name raises KeyError whose single arg is the (unquoted) message;\n# str() of a KeyError repr-quotes it, matching CPython.\ntry:\n    u.lookup('NOPE NOT A NAME')\n    assert False, 'expected lookup of an unknown name to raise'\nexcept KeyError as exc:\n    assert exc.args[0] == \"undefined character name 'NOPE NOT A NAME'\"\n\n# === combining ===\nassert u.combining('a') == 0\nassert u.combining(ACUTE) == 230\n\n# === normalize ===\nassert u.normalize('NFC', NFD_E) == NFC_E\nassert u.normalize('NFD', NFC_E) == NFD_E\nassert u.normalize('NFKC', FI) == 'fi'\nassert u.normalize('NFKD', FI) == 'fi'\nassert u.normalize('NFC', '') == ''\nassert u.normalize('NFC', 'hello') == 'hello'\n\n# === is_normalized ===\nassert u.is_normalized('NFC', NFC_E) is True\nassert u.is_normalized('NFC', NFD_E) is False\nassert u.is_normalized('NFD', NFD_E) is True\nassert u.is_normalized('NFD', NFC_E) is False\n\n# === error cases ===\n# A well-typed but unrecognised form is a *value* error, distinct from the\n# type error for a non-str form (regression guard: the two must not be conflated).\ntry:\n    u.normalize('XYZ', 'abc')\n    assert False, 'expected invalid form to raise'\nexcept ValueError as exc:\n    assert str(exc) == 'invalid normalization form'\ntry:\n    u.is_normalized('BAD', 'abc')\n    assert False, 'expected invalid form to raise'\nexcept ValueError as exc:\n    assert str(exc) == 'invalid normalization form'\n\n# All arguments are type-checked before the form's *value* is validated:\n# a bad form plus a non-str unistr raises the arg-2 TypeError, not ValueError.\ntry:\n    u.normalize('XYZ', 123)\n    assert False, 'expected non-str unistr to win over invalid form'\nexcept TypeError as exc:\n    assert str(exc) == 'normalize() argument 2 must be str, not int'\ntry:\n    u.is_normalized('XYZ', 123)\n    assert False, 'expected non-str unistr to win over invalid form'\nexcept TypeError as exc:\n    assert str(exc) == 'is_normalized() argument 2 must be str, not int'\n\n# A non-str form/string is a type error, numbered by argument position.\ntry:\n    u.normalize(123, 'abc')\n    assert False, 'expected non-str form to raise'\nexcept TypeError as exc:\n    assert str(exc) == 'normalize() argument 1 must be str, not int'\ntry:\n    u.normalize('NFC', 123)\n    assert False, 'expected non-str unistr to raise'\nexcept TypeError as exc:\n    assert str(exc) == 'normalize() argument 2 must be str, not int'\n\n# Single-character functions distinguish wrong-type from wrong-length.\ntry:\n    u.category(123)\n    assert False, 'expected non-str to raise'\nexcept TypeError as exc:\n    assert str(exc) == 'category() argument must be a unicode character, not int'\ntry:\n    u.combining('ab')\n    assert False, 'expected multi-char string to raise'\nexcept TypeError as exc:\n    assert str(exc) == 'combining(): argument must be a unicode character, not a string of length 2'\n\n# name() uses PyArg_UnpackTuple arity wording: a min..max range, so too-few and\n# too-many report \"at least\"/\"at most\" rather than an exact count.\ntry:\n    u.name()\n    assert False, 'expected name() with no args to raise'\nexcept TypeError as exc:\n    assert str(exc) == 'name expected at least 1 argument, got 0'\ntry:\n    u.name('a', 'b', 'c')\n    assert False, 'expected name() with 3 args to raise'\nexcept TypeError as exc:\n    assert str(exc) == 'name expected at most 2 arguments, got 3'\n",
  'unicodedata__name_error.py': "import unicodedata\n\n# U+FFFF is a permanently-unassigned noncharacter, so it has no name and no\n# default is supplied.\nunicodedata.name('￿')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"unicodedata__name_error.py\", line 5, in <module>\n    unicodedata.name('￿')\n    ~~~~~~~~~~~~~~~~~~~~~\nValueError: no such name\n\"\"\"\n",
  'unpack__nested.py': "# Test nested tuple unpacking\n\n# === Basic nested unpacking ===\ndata = ((1, 2), 'x')\n(a, b), c = data\nassert a == 1\nassert b == 2\nassert c == 'x'\n\n# === Deeply nested ===\n((a, b), (c, d)) = ((1, 2), (3, 4))\nassert a == 1\nassert b == 2\nassert c == 3\nassert d == 4\n\n# === Mixed depths ===\n(a, (b, c)) = (1, (2, 3))\nassert a == 1\nassert b == 2\nassert c == 3\n\n# === Three levels deep ===\n(a, (b, (c, d))) = (1, (2, (3, 4)))\nassert a == 1\nassert b == 2\nassert c == 3\nassert d == 4\n\n# === In for loops ===\nitems = [((1, 2), 'a'), ((3, 4), 'b')]\nsums = []\nletters = []\nfor (a, b), c in items:\n    sums.append(a + b)\n    letters.append(c)\nassert sums == [3, 7]\nassert letters == ['a', 'b']\n\n# === In comprehensions ===\nitems = [((1, 2), 'a'), ((3, 4), 'b')]\nresult = [a + b for (a, b), c in items]\nassert result == [3, 7]\n\n# === Deep nested in comprehension ===\nitems = [((1, 2), (3, 4)), ((5, 6), (7, 8))]\nresult = [a + b + c + d for (a, b), (c, d) in items]\nassert result == [10, 26]\n",
  'unpack__non_sequence.py': "a, b = 42\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"unpack__non_sequence.py\", line 1, in <module>\n    a, b = 42\n    ~~~~\nTypeError: cannot unpack non-iterable int object\n\"\"\"\n",
  'unpack__not_enough.py': "a, b, c = (1, 2)\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"unpack__not_enough.py\", line 1, in <module>\n    a, b, c = (1, 2)\n    ~~~~~~~\nValueError: not enough values to unpack (expected 3, got 2)\n\"\"\"\n",
  'unpack__ops.py': "# === Basic tuple unpacking ===\na, b = (1, 2)\nassert a == 1\nassert b == 2\n\n# === Unpacking without parentheses ===\nx, y = 10, 20\nassert x == 10\nassert y == 20\n\n# === Three element unpacking ===\na, b, c = (1, 2, 3)\nassert a == 1\nassert b == 2\nassert c == 3\n\n\n# === Unpacking from function return ===\ndef returns_pair():\n    return 42, 37\n\n\nx, y = returns_pair()\nassert x == 42\nassert y == 37\n\n\ndef returns_triple():\n    return 'a', 'b', 'c'\n\n\np, q, r = returns_triple()\nassert p == 'a'\nassert q == 'b'\nassert r == 'c'\n\n# === Unpacking list ===\na, b = [100, 200]\nassert a == 100\nassert b == 200\n\na, b, c, d = [1, 2, 3, 4]\nassert a == 1\nassert d == 4\n\n# === Unpacking string ===\na, b = 'xy'\nassert a == 'x'\nassert b == 'y'\n\np, q, r = 'abc'\nassert p == 'a'\nassert q == 'b'\nassert r == 'c'\n\n# === Unpacking with different value types ===\na, b = (True, False)\nassert a is True\nassert b is False\n\na, b = (1.5, 2.5)\nassert a == 1.5\nassert b == 2.5\n\na, b = (None, 42)\nassert a is None\nassert b == 42\n\n# === Unpacking with nested containers ===\na, b = ([1, 2], [3, 4])\nassert a == [1, 2]\nassert b == [3, 4]\n\na, b = ((1, 2), (3, 4))\nassert a == (1, 2)\nassert b == (3, 4)\n\n# === Reassignment via unpacking ===\nx = 1\ny = 2\nx, y = y, x\nassert x == 2\nassert y == 1\n\n# === Single element tuple (edge case) ===\n# Note: (x,) = (1,) is valid Python\n(a,) = (42,)\nassert a == 42\n\n(a,) = [99]\nassert a == 99\n\n(a,) = 'z'\nassert a == 'z'\n\n# === Star unpacking (extended unpacking) ===\n# Star at end\nfirst, *rest = [1, 2, 3, 4, 5]\nassert first == 1\nassert rest == [2, 3, 4, 5]\n\n# Star at start\n*init, last = [1, 2, 3, 4, 5]\nassert init == [1, 2, 3, 4]\nassert last == 5\n\n# Star in middle\nfirst, *middle, last = [1, 2, 3, 4, 5]\nassert first == 1\nassert middle == [2, 3, 4]\nassert last == 5\n\n# Empty rest (minimum values)\nfirst, *rest, last = [1, 2]\nassert first == 1\nassert rest == []\nassert last == 2\n\n# From tuple\na, *b = (10, 20, 30)\nassert a == 10\nassert b == [20, 30]\n\n# From string\nfirst, *mid, last = 'abcde'\nassert first == 'a'\nassert mid == ['b', 'c', 'd']\nassert last == 'e'\n\n# With more targets before star\na, b, c, *rest = [1, 2, 3, 4, 5, 6]\nassert a == 1\nassert b == 2\nassert c == 3\nassert rest == [4, 5, 6]\n\n# With more targets after star\n*init, x, y, z = [1, 2, 3, 4, 5, 6]\nassert init == [1, 2, 3]\nassert x == 4\nassert y == 5\nassert z == 6\n\n# Star captures all but one\nhead, *tail = [1]\nassert head == 1\nassert tail == []\n\n# Star with bracket syntax\n[a, *b, c] = [1, 2, 3, 4]\nassert a == 1\nassert b == [2, 3]\nassert c == 4\n",
  'unpack__star_not_enough.py': "a, *b, c = [1]\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"unpack__star_not_enough.py\", line 1, in <module>\n    a, *b, c = [1]\n    ~~~~~~~~\nValueError: not enough values to unpack (expected at least 2, got 1)\n\"\"\"\n",
