  'version__cpython.py': "import sys\n\nv = sys.version_info\nassert (v[0], v[1]) == (3, 14), f'Expected Python 3.14, got ({v[0]}, {v[1]})'\n",
  'walrus__all.py': "# === Basic walrus operator ===\n# Simple assignment expression\nassert (x := 5) == 5\nassert x == 5\n\n# Walrus in parentheses\ny = (z := 10)\nassert y == 10\nassert z == 10\n\n# simple if\nx = None\nanswer = 'unset'\nif y := x:\n    answer = f'x is {y}'\n\nassert answer == 'unset'\n\nx = 123\nif y := x:\n    answer = f'x is {y}'\n\nassert answer == 'x is 123'\nx = 0\nif y := x:\n    answer = f'x is {y}'\nelse:\n    answer = 'x is unset'\n\nassert answer == 'x is unset'\n\n# === Walrus in if conditions ===\nif (a := 3) > 0:\n    assert a == 3\nelse:\n    assert False, 'should not reach else'\n\n# With falsy value\nif b := 0:\n    assert False, 'should not reach truthy branch'\nelse:\n    assert b == 0\n\n# === Walrus in while loops ===\ncounter = 0\nresult = []\nwhile (n := counter) < 3:\n    result.append(n)\n    counter += 1\nassert result == [0, 1, 2]\nassert n == 3\n\n# === Nested walrus ===\n# Inner walrus assigned first, then outer\nassert (outer := (inner := 7) + 1) == 8\nassert inner == 7\nassert outer == 8\n\n# === Walrus in list literals ===\nitems = [(v := 1), v + 1, v + 2]\nassert items == [1, 2, 3]\nassert v == 1\n\n# === Walrus in ternary expressions ===\nresult = (t := 5) if True else 0\nassert result == 5\nassert t == 5\n\nresult2 = 0 if False else (f := 6)\nassert result2 == 6\nassert f == 6\n\n# === Walrus in dict/set literals ===\nd = {(k := 'key'): (val := 42)}\nassert d == {'key': 42}\nassert k == 'key'\nassert val == 42\n\ns = {(s1 := 1), (s2 := 2)}\nassert s == {1, 2}\nassert s1 == 1\nassert s2 == 2\n\n# === Walrus in subscript expressions ===\narr = [10, 20, 30]\nvalue = arr[(idx := 1)]\nassert value == 20\nassert idx == 1\n\n\n# === Walrus in function calls ===\ndef identity(x):\n    return x\n\n\nresult = identity((arg := 99))\nassert result == 99\nassert arg == 99\n\n# === Walrus with comparison operators ===\nassert (cmp := 10) > 5\nassert cmp == 10\n\n# === Walrus in chained comparisons ===\n# Note: Chained comparisons like `0 < (mid := 5) < 10` are not yet supported\n# Testing a simpler comparison chain\nmid = (chain := 5)\nassert 0 < chain and chain < 10, 'walrus result used in comparison chain'\nassert mid == 5\n\n# === Walrus in boolean expressions ===\n# Short-circuit with and\nresult = (first := 1) and (second := 2)\nassert result == 2\nassert first == 1\nassert second == 2\n\n# Short-circuit with or (second not evaluated)\nresult = (or_first := 1) or (or_skip := 999)\nassert result == 1\nassert or_first == 1\n\n# === Walrus with operations ===\nassert (op := 3) + 2 == 5\nassert op == 3\n\n# === Walrus in f-strings ===\nmsg = f'{(fvar := \"hello\")} world'\nassert msg == 'hello world'\nassert fvar == 'hello'\n\n# === Walrus with global ===\nglobal_var = None\n\n\ndef set_global():\n    global global_var\n    return (global_var := 'set')\n\n\nresult = set_global()\nassert result == 'set'\nassert global_var == 'set'\n\n\n# === Walrus creates local in function scope ===\ndef func_scope():\n    if local := 42:\n        pass\n    return local\n\n\nassert func_scope() == 42\n\n# === Walrus in list comprehension element (leaks to enclosing scope) ===\n# Per PEP 572, walrus in comprehension assigns to enclosing scope\n# Note: walrus in comprehension iterable is not allowed, but in element/condition it is\nresult = [(leak := x) for x in range(3)]\nassert result == [0, 1, 2]\nassert leak == 2\n\n# === Walrus in comprehension condition ===\nresult = [x for x in range(5) if (limit := 3) and x < limit]\nassert result == [0, 1, 2]\nassert limit == 3\n\n# === Multiple walrus in same expression ===\nresult = (m1 := 1) + (m2 := 2) + (m3 := 3)\nassert result == 6\nassert m1 == 1\nassert m2 == 2\nassert m3 == 3\n\n# === Walrus in tuple ===\ntup = ((t1 := 'a'), (t2 := 'b'))\nassert tup == ('a', 'b')\nassert t1 == 'a'\nassert t2 == 'b'\n",
  'while__all.py': "# === Basic while loop ===\ni = 0\nresult = []\nwhile i < 3:\n    result.append(i)\n    i += 1\nassert result == [0, 1, 2]\n\n# === While with break ===\ni = 0\nresult = []\nwhile i < 10:\n    if i == 3:\n        break\n    result.append(i)\n    i += 1\nassert result == [0, 1, 2]\n\n# === While with continue ===\ni = 0\nresult = []\nwhile i < 5:\n    i += 1\n    if i % 2 == 0:\n        continue\n    result.append(i)\nassert result == [1, 3, 5]\n\n# === While with else (no break - else runs) ===\ni = 0\nflag = 0\nwhile i < 3:\n    i += 1\nelse:\n    flag = 1\nassert flag == 1\n\n# === While with else (with break - else skipped) ===\ni = 0\nflag = 0\nwhile i < 10:\n    i += 1\n    if i == 2:\n        break\nelse:\n    flag = 1\nassert flag == 0\n\n# === while True with break ===\ni = 0\nresult = []\nwhile True:\n    result.append(i)\n    i += 1\n    if i >= 3:\n        break\nassert result == [0, 1, 2]\n\n# === while False (never executes) ===\nflag = 0\nwhile False:\n    flag = 1\nassert flag == 0\n\n# === while False with else (else runs immediately) ===\nflag = 0\nwhile False:\n    flag = 1\nelse:\n    flag = 2\nassert flag == 2\n\n# === Nested while loops ===\ni = 0\nresult = []\nwhile i < 2:\n    j = 0\n    while j < 2:\n        result.append((i, j))\n        j += 1\n    i += 1\nassert result == [(0, 0), (0, 1), (1, 0), (1, 1)]\n\n# === Nested while with break inner ===\ni = 0\nresult = []\nwhile i < 3:\n    j = 0\n    while j < 3:\n        if j == 1:\n            break\n        result.append((i, j))\n        j += 1\n    i += 1\nassert result == [(0, 0), (1, 0), (2, 0)]\n\n# === For inside while ===\ni = 0\nresult = []\nwhile i < 2:\n    for j in ['a', 'b']:\n        result.append((i, j))\n    i += 1\nassert result == [(0, 'a'), (0, 'b'), (1, 'a'), (1, 'b')]\n\n# === While inside for ===\nresult = []\nfor i in [0, 1]:\n    j = 0\n    while j < 2:\n        result.append((i, j))\n        j += 1\nassert result == [(0, 0), (0, 1), (1, 0), (1, 1)]\n\n# === Complex condition with and ===\ni = 0\nj = 10\nresult = []\nwhile i < 5 and j > 5:\n    result.append((i, j))\n    i += 1\n    j -= 1\nassert result == [(0, 10), (1, 9), (2, 8), (3, 7), (4, 6)]\n\n# === Complex condition with or ===\ni = 5\ncount = 0\nwhile i < 3 or count < 2:\n    count += 1\n    i += 1\nassert count == 2\n\n\n# === While with function call condition ===\ndef check(n):\n    return n < 3\n\n\ni = 0\nresult = []\nwhile check(i):\n    result.append(i)\n    i += 1\nassert result == [0, 1, 2]\n\n# === Continue does not skip else ===\ni = 0\nflag = 0\nwhile i < 3:\n    i += 1\n    if i == 2:\n        continue\nelse:\n    flag = 1\nassert flag == 1\n\n# === Nested while - break outer via flag ===\ni = 0\nresult = []\ndone = False\nwhile i < 3 and not done:\n    j = 0\n    while j < 3:\n        if i == 1 and j == 1:\n            done = True\n            break\n        result.append((i, j))\n        j += 1\n    i += 1\nassert result == [(0, 0), (0, 1), (0, 2), (1, 0)]\n\n# === While with negative condition ===\ni = 5\nresult = []\nwhile not i == 3:\n    result.append(i)\n    i -= 1\nassert result == [5, 4]\n\n# === Nested while with inner else ===\ni = 0\nresult = []\nwhile i < 2:\n    j = 0\n    while j < 2:\n        result.append(j)\n        j += 1\n    else:\n        result.append('inner-else')\n    i += 1\nassert result == [0, 1, 'inner-else', 0, 1, 'inner-else']\n\n# === Break in nested while skips inner else ===\ni = 0\nresult = []\nwhile i < 2:\n    j = 0\n    while j < 3:\n        if j == 1:\n            break\n        result.append(j)\n        j += 1\n    else:\n        result.append('inner-else')\n    i += 1\nassert result == [0, 0]\n\n\n# === Exception raised by the condition is caught by an enclosing try ===\ndef exploding_condition():\n    raise ValueError('cond boom')\n\n\nlog = []\ntry:\n    while exploding_condition():\n        log.append('unreached')\nexcept ValueError as e:\n    log.append(str(e))\nassert log == ['cond boom']\n\n# === Condition raising on a later evaluation, after iterations ran ===\ncount = 0\n\n\ndef cond():\n    global count\n    count += 1\n    if count == 3:\n        raise ValueError('third check')\n    return True\n\n\nlog = []\ntry:\n    while cond():\n        log.append(count)\nexcept ValueError as e:\n    log.append(str(e))\nassert log == [1, 2, 'third check']\n",
  'with__all.py': "# mount-fs\n\n# === Basic with + open ===\nwith open(root / 'open_with.txt', 'w') as f:\n    assert f.write('hello') == 5\n    assert f.closed == False\nassert f.closed == True\nassert (root / 'open_with.txt').read_text() == 'hello'\n\n# === Read with `with` ===\nwith open(root / 'hello.txt') as r:\n    assert r.read() == 'hello world\\n'\nassert r.closed == True\n\n# === `__enter__` returns the file itself ===\npre = open(root / 'hello.txt')\nwith pre as bound:\n    assert bound is pre\nassert pre.closed == True\n\n# === Closed on exception ===\nerrfile = open(root / 'hello.txt')\ncaught = None\ntry:\n    with errfile:\n        raise ValueError('boom')\nexcept ValueError as e:\n    caught = str(e)\nassert caught == 'boom'\nassert errfile.closed == True\n\n# === Without `as` target ===\nwith open(root / 'hello.txt'):\n    pass\n\n# === Nested with ===\nwith open(root / 'open_with_a.txt', 'w') as a:\n    with open(root / 'open_with_b.txt', 'w') as b:\n        a.write('A')\n        b.write('B')\nassert a.closed == True\nassert b.closed == True\nassert (root / 'open_with_a.txt').read_text() == 'A'\nassert (root / 'open_with_b.txt').read_text() == 'B'\n\n# === Multi-item with (desugared to nested) ===\nwith open(root / 'open_with_m1.txt', 'w') as m1, open(root / 'open_with_m2.txt', 'w') as m2:\n    m1.write('M1')\n    m2.write('M2')\nassert m1.closed == True\nassert m2.closed == True\nassert (root / 'open_with_m1.txt').read_text() == 'M1'\nassert (root / 'open_with_m2.txt').read_text() == 'M2'\n\n# === Multi-item with: exception inside body closes both ===\nmexa = open(root / 'hello.txt')\nmexb = open(root / 'hello.txt')\ncaught = None\ntry:\n    with mexa as _ma, mexb as _mb:\n        raise ValueError('multi-item-boom')\nexcept ValueError as e:\n    caught = str(e)\nassert caught == 'multi-item-boom'\nassert mexa.closed == True\nassert mexb.closed == True\n\n# === Multi-item with: bare items without `as` ===\nwith open(root / 'hello.txt'), open(root / 'hello.txt'):\n    pass\n\n\n# === `return` inside with calls __exit__ ===\ndef write_and_return(path):\n    with open(path, 'w') as out:\n        out.write('via-return')\n        return out\n\n\nreturned = write_and_return(root / 'open_with_ret.txt')\nassert returned.closed == True\nassert (root / 'open_with_ret.txt').read_text() == 'via-return'\n\n# === `break` inside with calls __exit__ ===\nbreak_file = None\nfor _ in range(1):\n    with open(root / 'open_with_break.txt', 'w') as bf:\n        break_file = bf\n        bf.write('via-break')\n        break\nassert break_file.closed == True\nassert (root / 'open_with_break.txt').read_text() == 'via-break'\n\n# === `continue` inside with calls __exit__ ===\ncont_files = []\ncont_paths = [root / 'open_with_cont_0.txt', root / 'open_with_cont_1.txt']\nfor i in range(2):\n    with open(cont_paths[i], 'w') as cf:\n        cont_files.append(cf)\n        cf.write('iter-' + str(i))\n        continue\nassert all(f.closed for f in cont_files)\nassert cont_paths[0].read_text() == 'iter-0'\nassert cont_paths[1].read_text() == 'iter-1'\n\n# === Direct `__enter__()` / `__exit__()` invocation ===\ndirect = open(root / 'hello.txt')\nentered = direct.__enter__()\nassert entered is direct\nassert direct.__exit__(None, None, None) is None\nassert direct.closed == True\n\n# === `__enter__` on a closed file raises ===\nclosed = open(root / 'hello.txt')\nclosed.close()\nerr = None\ntry:\n    with closed:\n        assert False, 'should not enter body when ctx is closed'\nexcept ValueError as e:\n    err = str(e)\nassert err == 'I/O operation on closed file.'\n",
  'with__class.py': "# User-defined classes as context managers: `__enter__` / `__exit__` are\n# dispatched by the `with` statement (`BeforeWith` / `WithExit` /\n# `WithExceptStart` opcodes) with CPython's type-level lookup and call\n# semantics. `__enter__`/`__exit__` run as real frames, so unlike\n# `__repr__`/`__str__` they may suspend on external/OS calls (covered by\n# `with__class_external.py`).\n\n# === Basic protocol: enter/exit ordering, as-target binding ===\nlog = []\n\n\nclass Tracked:\n    def __init__(self, name):\n        self.name = name\n\n    def __enter__(self):\n        log.append('enter ' + self.name)\n        return self\n\n    def __exit__(self, typ, val, tb):\n        log.append('exit ' + self.name)\n        return None\n\n\nwith Tracked('a') as bound:\n    log.append('body')\n    assert bound.name == 'a'\nassert log == ['enter a', 'body', 'exit a']\n\n\n# === __enter__ may return a non-self value ===\nclass EnterValue:\n    def __enter__(self):\n        return 42\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\nwith EnterValue() as v:\n    assert v == 42\n\n\n# === __exit__ receives (None, None, None) on the normal path ===\nclass Grab:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        self.typ = typ\n        self.val = val\n        self.tb = tb\n        return True\n\n\ng = Grab()\nwith g:\n    pass\nassert g.typ is None\nassert g.val is None\nassert g.tb is None\n\n# === __exit__ receives the exception type and value on the exception path ===\n# The traceback argument is not asserted: CPython passes a real traceback\n# object, Monty always passes None (see limitations/with.md).\ng = Grab()\nwith g:\n    raise ValueError('boom')\nassert g.typ is ValueError\nassert isinstance(g.val, ValueError)\nassert str(g.val) == 'boom'\n\n# === Truthy __exit__ return swallows the in-flight exception ===\nswallowed = False\nwith Grab():\n    raise ValueError('to-swallow')\n    swallowed = False  # unreachable\nswallowed = True\nassert swallowed\n\n\n# Any truthy value suppresses, not just True.\nclass TruthyStr:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        return 'truthy'\n\n\nwith TruthyStr():\n    raise ValueError('swallowed by str')\n\n\n# === Falsy/None __exit__ return propagates the exception ===\nclass Passthrough:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\ncaught = None\ntry:\n    with Passthrough():\n        raise ValueError('passthrough-prop')\nexcept ValueError as e:\n    caught = str(e)\nassert caught == 'passthrough-prop'\n\n# The return value is ignored entirely on the normal-exit path.\nwith Grab():\n    inside = 'ran'\nassert inside == 'ran'\n\n\n# === __enter__ raising skips the body AND __exit__ ===\nclass BadEnter:\n    def __enter__(self):\n        raise ValueError('no-entry')\n\n    def __exit__(self, typ, val, tb):\n        # Would swallow the ValueError if incorrectly invoked, making the\n        # try/except below fail loudly.\n        return True\n\n\nran_body = False\ncaught = None\ntry:\n    with BadEnter():\n        ran_body = True\nexcept ValueError as e:\n    caught = str(e)\nassert caught == 'no-entry'\nassert not ran_body, 'body skipped when __enter__ raises'\n\n\n# === __exit__ raising on the normal path propagates ===\nclass BadExit:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        raise ValueError('cleanup-failed')\n\n\ncaught = None\ntry:\n    with BadExit():\n        pass\nexcept ValueError as e:\n    caught = str(e)\nassert caught == 'cleanup-failed'\n\n# === __exit__ raising on the exception path REPLACES the in-flight exception ===\ncaught_info = None\ntry:\n    with BadExit():\n        raise RuntimeError('original')\nexcept ValueError as e:\n    caught_info = ('ValueError', str(e))\nexcept RuntimeError as e:\n    caught_info = ('RuntimeError', str(e))\nassert caught_info == ('ValueError', 'cleanup-failed')\n\n\n# === Missing dunders: CPython's protocol TypeError, __exit__ checked first ===\nclass NoEnter:\n    def __exit__(self, typ, val, tb):\n        return None\n\n\nclass NoExit:\n    def __enter__(self):\n        return self\n\n\nclass Neither:\n    pass\n\n\ncaught = None\ntry:\n    with NoEnter():\n        pass\nexcept TypeError as e:\n    caught = str(e)\nassert caught == \"'NoEnter' object does not support the context manager protocol (missed __enter__ method)\"\n\ncaught = None\ntry:\n    with NoExit():\n        pass\nexcept TypeError as e:\n    caught = str(e)\nassert caught == \"'NoExit' object does not support the context manager protocol (missed __exit__ method)\"\n\ncaught = None\ntry:\n    with Neither():\n        pass\nexcept TypeError as e:\n    caught = str(e)\nassert caught == \"'Neither' object does not support the context manager protocol (missed __exit__ method)\"\n\n\n# === Non-callable __enter__ class member ===\nclass IntEnter:\n    __enter__ = 5\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\ncaught = None\ntry:\n    with IntEnter():\n        pass\nexcept TypeError as e:\n    caught = str(e)\nassert caught == \"'int' object is not callable\"\n\n\n# === Lambda dunders work (any callable class member), including on\n# classes created dynamically via 3-arg type() ===\nDynCm = type('DynCm', (), {'__enter__': lambda self: 'dyn', '__exit__': lambda self, typ, val, tb: None})\nwith DynCm() as v:\n    assert v == 'dyn'\n\n# === Direct __enter__() / __exit__() calls are ordinary method calls ===\np = Passthrough()\nassert p.__enter__() is p\nassert p.__exit__(None, None, None) is None\nassert Grab().__exit__(ValueError, ValueError('x'), None) is True\n\n\n# The `with` statement looks dunders up on the CLASS only; a direct call\n# reads through the instance and so sees an instance attribute shadowing it.\nclass Shadow:\n    def __enter__(self):\n        return 'class-enter'\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\ndef instance_enter():\n    return 'instance-enter'\n\n\ns = Shadow()\ns.__enter__ = instance_enter\nwith s as v:\n    assert v == 'class-enter'\nassert s.__enter__() == 'instance-enter'\n\n# === Unpack failure inside the `with` still invokes __exit__ ===\n# `Passthrough.__enter__` returns self, which is not iterable, so the\n# `as (a, b)` unpack raises; the unpack lives inside the protected region,\n# so __exit__ runs — here it raises its own error which replaces the\n# in-flight TypeError, proving it was called.\ncaught = None\ntry:\n    with BadExit() as (a, b):\n        pass\nexcept ValueError as e:\n    caught = str(e)\nexcept TypeError:\n    caught = 'unpack-error-uncaught'\nassert caught == 'cleanup-failed'\n\n# === Early exits (return/break/continue) call __exit__ ===\nlog = []\n\n\ndef early_return():\n    with Tracked('ret'):\n        return 'early'\n\n\nassert early_return() == 'early'\nassert log == ['enter ret', 'exit ret']\n\nlog = []\nfor i in range(3):\n    with Tracked('loop' + str(i)):\n        if i == 1:\n            continue\n        if i == 2:\n            break\nassert log == [\n    'enter loop0',\n    'exit loop0',\n    'enter loop1',\n    'exit loop1',\n    'enter loop2',\n    'exit loop2',\n]\n\n# === Nested and multi-item with: LIFO exit order ===\nlog = []\nwith Tracked('outer'), Tracked('inner'):\n    log.append('body')\nassert log == ['enter outer', 'enter inner', 'body', 'exit inner', 'exit outer']\n\n# Inner suppress prevents the outer manager from seeing the exception.\noutcome = None\nwith Passthrough():\n    try:\n        with Grab():\n            raise ValueError('inner-swallow')\n        outcome = 'fell-through'\n    except ValueError:\n        outcome = 'propagated'\nassert outcome == 'fell-through'\n\n# Outer __exit__ raising while an inner exception propagates replaces it.\ncaught_info = None\ntry:\n    with BadExit():\n        with Passthrough():\n            raise RuntimeError('inner-raise')\nexcept ValueError as e:\n    caught_info = ('ValueError', str(e))\nexcept RuntimeError as e:\n    caught_info = ('RuntimeError', str(e))\nassert caught_info == ('ValueError', 'cleanup-failed')\n",
  'with__class_external.py': "# call-external\n# `__enter__` and `__exit__` run as real pushed frames (unlike\n# `__repr__`/`__str__`), so they can suspend on external function calls and\n# resume mid-`with`. `add_ints`/`concat_strings` are external functions\n# resolved by the host on the Monty side and plain functions on the CPython\n# side.\n\n\nclass Resource:\n    def __init__(self, base):\n        self.base = base\n        self.closed = False\n\n    def __enter__(self):\n        # Suspends inside the BeforeWith opcode's pushed frame.\n        self.value = add_ints(self.base, 100)\n        return self.value\n\n    def __exit__(self, typ, val, tb):\n        # Suspends inside the WithExit / WithExceptStart pushed frame.\n        self.closed = concat_strings('closed:', str(typ))\n        return None\n\n\nr = Resource(7)\nwith r as v:\n    assert v == 107\n    assert r.value == 107\nassert r.closed == 'closed:None'\n\n# Exception path: __exit__ still suspends and sees the exception type.\nr2 = Resource(1)\ncaught = None\ntry:\n    with r2:\n        raise ValueError('boom')\nexcept ValueError as e:\n    caught = str(e)\nassert caught == 'boom'\nassert r2.closed == \"closed:<class 'ValueError'>\"\n\n\n# A suspending __exit__ that swallows the exception.\nclass Swallow:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        self.note = add_ints(20, 22)\n        return typ is not None\n\n\ns = Swallow()\nwith s:\n    raise ValueError('to-swallow')\nassert s.note == 42\n\n\n# Host name lookup (not a call) inside the dunders: resolving an unknown\n# global suspends to the host's NameLookup handler mid-`with`, a different\n# suspension path from an external function call. `CONST_INT`/`CONST_STR`\n# are host-injected constants.\nclass NameLookupCm:\n    def __enter__(self):\n        return CONST_INT + 1\n\n    def __exit__(self, typ, val, tb):\n        self.closed_with = CONST_STR\n        return None\n\n\nn = NameLookupCm()\nwith n as v:\n    assert v == 43\nassert n.closed_with == 'hello'\n",
  'with__cm_context_expr_raises_traceback.py': "# Exception raised by the context expression itself (constructing the\n# manager), before `__enter__` is ever invoked: neither `__enter__` nor\n# `__exit__` runs and the `__init__` frame shows under the `with` line.\nclass CM:\n    def __init__(self):\n        raise TypeError('ctor boom')\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\nwith CM():\n    raise RuntimeError('body should not run')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"with__cm_context_expr_raises_traceback.py\", line 15, in <module>\n    with CM():\n         ~~~~\n  File \"with__cm_context_expr_raises_traceback.py\", line 6, in __init__\n    raise TypeError('ctor boom')\nTypeError: ctor boom\n\"\"\"\n",
  'with__cm_enter_raises_traceback.py': "# `__enter__` raises before the body runs: the body never executes and\n# `__exit__` is never called. `__enter__` is a real frame on both sides,\n# so it appears in the traceback under the `with` line.\nclass CM:\n    def __enter__(self):\n        raise ValueError('fail-enter')\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\nwith CM():\n    raise RuntimeError('body should not run')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"with__cm_enter_raises_traceback.py\", line 12, in <module>\n    with CM():\n         ~~~~\n  File \"with__cm_enter_raises_traceback.py\", line 6, in __enter__\n    raise ValueError('fail-enter')\nValueError: fail-enter\n\"\"\"\n",
  'with__cm_exit_raises_normal_exit_traceback.py': "# `__exit__` raises on the normal-exit path (the body completed cleanly,\n# but the cleanup itself fails). `__exit__` is a real frame on both sides,\n# so it appears in the traceback under the `with` line.\nclass CM:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        raise ValueError('fail-exit')\n\n\nwith CM():\n    pass\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"with__cm_exit_raises_normal_exit_traceback.py\", line 12, in <module>\n    with CM():\n         ~~~~\n  File \"with__cm_exit_raises_normal_exit_traceback.py\", line 9, in __exit__\n    raise ValueError('fail-exit')\nValueError: fail-exit\n\"\"\"\n",
  'with__cm_nested_body_raises_traceback.py': "# Nested `with` blocks with a passthrough class cm at each level: an\n# exception raised in the innermost body propagates through both\n# `__exit__` calls (both return None) and surfaces with the body's frame\n# intact. Verifies that `WithExceptStart` doesn't perturb the propagating\n# exception's traceback when `__exit__` is a no-op cleanup.\nclass CM:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\nwith CM() as outer:\n    with CM() as inner:\n        raise ValueError('from inner body')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"with__cm_nested_body_raises_traceback.py\", line 16, in <module>\n    raise ValueError('from inner body')\nValueError: from inner body\n\"\"\"\n",
  'with__cm_traceback.py': "# A passthrough class context manager: an exception raised inside the\n# `with` body propagates with its original traceback intact — `__exit__`\n# returns None, never raises, and so adds no frame of its own.\nclass CM:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, typ, val, tb):\n        return None\n\n\nwith CM() as cm:\n    raise ValueError('inside passthrough')\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"with__cm_traceback.py\", line 13, in <module>\n    raise ValueError('inside passthrough')\nValueError: inside passthrough\n\"\"\"\n",
  'with__not_context_manager.py': "# `with` on a value without `__exit__` raises CPython's specific TypeError\n# (not a generic AttributeError), even though the bytecode check itself\n# fails on `__enter__` first. We surface CPython's text so user-facing\n# diagnostics match.\nwith 5:\n    assert False, 'body should never execute'\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"with__not_context_manager.py\", line 5, in <module>\n    with 5:\n         ~\nTypeError: 'int' object does not support the context manager protocol (missed __exit__ method)\n\"\"\"\n",
};
